LOG_DIR = ROOT_DIR / "logs"
LOG_FILE = LOG_DIR / "app_errors.log"


def _build_app_logger() -> logging.Logger:
    """Create one rotating application error logger without changing the UI."""
    logger = logging.getLogger("agentic_sketch_to_ppt")
    logger.setLevel(logging.ERROR)
    logger.propagate = False

    if logger.handlers:
        return logger

    try:
        LOG_DIR.mkdir(parents=True, exist_ok=True)
        handler = RotatingFileHandler(
            LOG_FILE,
            maxBytes=2_000_000,
            backupCount=5,
            encoding="utf-8",
        )
    except Exception:
        # If the project folder is read-only, logging must never crash the app.
        handler = logging.StreamHandler(sys.stderr)

    handler.setLevel(logging.ERROR)
    handler.setFormatter(
        logging.Formatter(
            "%(asctime)s | %(levelname)s | %(message)s",
            datefmt="%Y-%m-%d %H:%M:%S",
        )
    )
    logger.addHandler(handler)
    return logger


APP_LOGGER = _build_app_logger()


def _exception_location(exc: BaseException) -> tuple[str, str, int]:
    """Return the exact source file, function and line for the deepest error frame."""
    try:
        frames = traceback.extract_tb(exc.__traceback__)
        if frames:
            frame = frames[-1]
            return str(frame.filename), str(frame.name), int(frame.lineno)
    except Exception:
        pass
    return "<unknown>", "<unknown>", 0


def log_app_error(context: str, exc: BaseException) -> None:
    """Log exact error details and full traceback without exposing them in the UI."""
    try:
        file_name, function_name, line_number = _exception_location(exc)
        APP_LOGGER.error(
            "Context=%s | ErrorType=%s | Error=%s | File=%s | Function=%s | Line=%s\n%s",
            context,
            type(exc).__name__,
            str(exc),
            file_name,
            function_name,
            line_number,
            "".join(
                traceback.format_exception(
                    type(exc),
                    exc,
                    exc.__traceback__,
                )
            ),
        )
    except Exception:
        # Error reporting itself must never become a second application failure.
        pass


def show_friendly_error(action: str = "completing this operation") -> None:
    """Show a simple UI message while technical details remain only in the log."""
    try:
        st.error(
            f"Something went wrong while {action}. "
            "Please try again. The technical details have been recorded in the application log."
        )
    except Exception:
        pass


def guarded_ui(context: str, *, action: str | None = None):
    """Guard a UI helper so a local failure does not terminate the full application."""
    def decorator(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            try:
                return func(*args, **kwargs)
            except Exception as exc:
                log_app_error(context, exc)
                show_friendly_error(action or context.lower())
                return None
        return wrapper
    return decorator


def _global_exception_logger(exc_type, exc_value, exc_traceback):
    """Last-resort logger for any unexpected error not caught by a local guard."""
    if exc_value is not None:
        log_app_error("Unhandled application exception", exc_value)
    try:
        sys.__excepthook__(exc_type, exc_value, exc_traceback)
    except Exception:
        pass


sys.excepthook = _global_exception_logger

