# =============================================================================
# PERFORMANCE-ONLY MEMOIZATION
# =============================================================================

def _call_component_catalog_function(
    function_name: str,
    *args,
    **kwargs,
):
    """Call the current on-disk component-catalog function safely.

    Streamlit keeps imported modules alive between reruns. If the project files
    are replaced while Streamlit is already running, an older cached catalog
    function can otherwise remain in memory and reject newer keyword arguments.
    Reload only in that exact stale-signature case; normal runs use the already
    imported module with zero behavioral change.
    """
    function = getattr(component_catalog_module, function_name)
    try:
        return function(*args, **kwargs)
    except TypeError as exc:
        if "expand_repeated_instances" not in str(exc):
            raise

        refreshed_module = importlib.reload(component_catalog_module)
        refreshed_function = getattr(refreshed_module, function_name)
        return refreshed_function(*args, **kwargs)


def _cached_allowed_connection_options(
    selected_names: tuple[str, ...],
) -> tuple:
    """Memoize the existing trained connection-option calculation per session.

    The underlying catalog function remains the sole source of relationship
    truth. A fresh list is returned by the public wrapper, so no caller can
    mutate the cached tuple.
    """
    cache = st.session_state.setdefault("_allowed_connection_options_cache", {})
    cached = cache.get(selected_names)
    if cached is not None:
        return cached

    result = tuple(
        _call_component_catalog_function(
            "allowed_connection_options",
            list(selected_names),
            expand_repeated_instances=True,
        )
        or []
    )
    cache[selected_names] = result
    if len(cache) > 256:
        for stale_key in list(cache.keys())[:-256]:
            cache.pop(stale_key, None)
    return result


def allowed_connection_options(selected_names) -> list:
    """Return all rule-valid instance choices for the current Worksheet.

    The catalog rule table remains authoritative. Repeated components only expand
    the already-valid type relationship into concrete instance choices; no new
    relationship is inferred from layout, distance, or proximity.
    """
    return list(
        _cached_allowed_connection_options(
            tuple(str(name) for name in list(selected_names or []))
        )
    )


def _cached_conservative_allowed_connection_options(
    selected_names: tuple[str, ...],
) -> tuple:
    """Memoize the unchanged conservative/trained connection expansion."""
    cache = st.session_state.setdefault(
        "_conservative_allowed_connection_options_cache", {}
    )
    cached = cache.get(selected_names)
    if cached is not None:
        return cached

    result = tuple(
        _call_component_catalog_function(
            "allowed_connection_options",
            list(selected_names),
            expand_repeated_instances=False,
        )
        or []
    )
    cache[selected_names] = result
    if len(cache) > 256:
        for stale_key in list(cache.keys())[:-256]:
            cache.pop(stale_key, None)
    return result


def _conservative_allowed_connection_options(selected_names) -> list:
    """Preserve the pre-existing automatic/trained instance-pairing behavior.

    Manual Worksheet selection needs every valid repeated-instance candidate, but
    previously trained automatic profiles must keep their exact established
    pairings. This helper calls the same catalog with repeated expansion disabled.
    """
    return list(
        _cached_conservative_allowed_connection_options(
            tuple(str(name) for name in list(selected_names or []))
        )
    )


def _allowed_connection_id_set(selected_names) -> frozenset[str]:
    """Reuse the expanded option-id set across validation passes in one session."""
    selected_key = tuple(str(name) for name in list(selected_names or []))
    cache = st.session_state.setdefault("_allowed_connection_id_set_cache", {})
    cached = cache.get(selected_key)
    if cached is not None:
        return cached

    result = frozenset(
        str(option.id)
        for option in _cached_allowed_connection_options(selected_key)
    )
    cache[selected_key] = result
    if len(cache) > 256:
        for stale_key in list(cache.keys())[:-256]:
            cache.pop(stale_key, None)
    return result


@st.cache_resource(show_spinner=False)
def _cached_gemini_client(api_key: str):
    """Reuse the same Gemini client instead of reconstructing it on every run."""
    return genai.Client(api_key=api_key)


@st.cache_data(max_entries=8, show_spinner=False)
def _cached_sketch_processing(
    uploaded_bytes: bytes,
    orientation: str,
):
    """Cache deterministic sketch preprocessing across Streamlit reruns.

    The cached function body runs only for a new image/orientation combination.
    Unrelated widget reruns reuse the already processed PIL images immediately.
    """
    with st.spinner("Loading and processing sketch..."):
        source_image = rotate_image(load_image(uploaded_bytes), orientation)
        ai_image = resize_for_ai(source_image)
        enhanced_image = enhance_sketch(ai_image)
        return source_image, ai_image, enhanced_image



