# =============================================================================
# HELPERS
# =============================================================================

WORKSHEET_OUTPUT_KEYS = (
    "diagram",
    "preview_png",
    "pdf_bytes",
    "processed_hash",
    "editor_saved_state",
)


# 2A default requirement/control choices. These are intentionally kept separate
# from the three manual base components (Sump / Bore Well / OHT Tank).  Selecting
# one of these entries from the existing second 2A box adds that component as a
# requirement, after which the normal allowed-connection rules expose only the
# valid relationships for it.  The wireless trio remains protected by the
# existing strict Distance + Interference rule and is therefore not manually
# addable from this list.
REQUIREMENT_COMPONENT_OPTION_PREFIX = "requirement_component::"
PROTECTED_WIRELESS_AUTO_COMPONENTS = {"Master", "Repeater", "Transmitter"}
DEFAULT_REQUIREMENT_COMPONENTS = tuple(
    item.name
    for item in COMPONENT_CATALOG
    if item.name not in set(MANUAL_BASE_COMPONENTS)
    and item.name not in PROTECTED_WIRELESS_AUTO_COMPONENTS
)
REQUIREMENT_COMPONENT_LABELS = {
    item.name: (
        f"{item.name} — {item.connection_label}"
        if str(item.connection_label or "").strip()
        else item.name
    )
    for item in COMPONENT_CATALOG
    if item.name in DEFAULT_REQUIREMENT_COMPONENTS
}


# Performance-only constants: these values are catalog-derived and immutable for
# the lifetime of the running app, so do not rebuild them on every Streamlit rerun.
DEFAULT_REQUIREMENT_OPTION_IDS = tuple(
    f"{REQUIREMENT_COMPONENT_OPTION_PREFIX}{component_name}"
    for component_name in DEFAULT_REQUIREMENT_COMPONENTS
)
DEFAULT_REQUIREMENT_OPTION_LABELS = {
    f"{REQUIREMENT_COMPONENT_OPTION_PREFIX}{component_name}":
        REQUIREMENT_COMPONENT_LABELS.get(component_name, component_name)
    for component_name in DEFAULT_REQUIREMENT_COMPONENTS
}


def _requirement_component_option_id(component_name: str) -> str:
    return f"{REQUIREMENT_COMPONENT_OPTION_PREFIX}{component_name}"


def _requirement_component_from_option_id(option_id: str) -> str | None:
    option_id = str(option_id or "")
    if not option_id.startswith(REQUIREMENT_COMPONENT_OPTION_PREFIX):
        return None
    component_name = option_id[len(REQUIREMENT_COMPONENT_OPTION_PREFIX):].strip()
    return component_name if component_name in DEFAULT_REQUIREMENT_COMPONENTS else None


def _sanitize_requirement_components(values) -> list[str]:
    valid = set(DEFAULT_REQUIREMENT_COMPONENTS)
    result: list[str] = []
    seen: set[str] = set()
    for value in list(values or []):
        name = str(value or "").strip()
        if not name or name not in valid or name in seen:
            continue
        seen.add(name)
        result.append(name)
    return result


def _new_worksheet(worksheet_id: int, number: int) -> dict:
    """Create one blank worksheet without changing any diagram functionality."""
    return {
        "id": worksheet_id,
        "name": f"Worksheet {number}",
        "selected_components": [],
        "selected_requirement_components": [],
        "selected_connections": [],
        "connection_transport_settings": {},
        "inline_flow_meter_settings": {},
        "diagram": None,
        "preview_png": None,
        "pdf_bytes": None,
        "processed_hash": None,
    }


def ensure_worksheet_state() -> None:
    """Initialize the multi-worksheet container with the existing first worksheet."""
    _apply_pending_saved_project_restore_if_needed()

    # Finish deletion cleanup before any worksheet-specific widgets are created in
    # this rerun. This removes stale uploader/editor/rename widget state belonging
    # to worksheets that were deleted in the previous run.
    deleted_ids = st.session_state.pop("_pending_deleted_worksheet_ids", []) or []
    for deleted_id in deleted_ids:
        for widget_key in (
            f"sketch_uploader_{deleted_id}",
            f"sketch_upload_generation_{deleted_id}",
            f"image_orientation_{deleted_id}",
            f"component_selection_editor_{deleted_id}",
            f"worksheet_name_editor_{deleted_id}",
            f"delete_worksheet_button_{deleted_id}",
        ):
            st.session_state.pop(widget_key, None)
        for widget_key in list(st.session_state.keys()):
            if str(widget_key).startswith(f"sketch_uploader_{deleted_id}_"):
                st.session_state.pop(widget_key, None)
            if str(widget_key).startswith(f"connection_intent_editor_{deleted_id}_"):
                st.session_state.pop(widget_key, None)
            if str(widget_key).startswith(f"flow_meter_placement_editor_{deleted_id}_"):
                st.session_state.pop(widget_key, None)

    if "worksheets" not in st.session_state:
        first = _new_worksheet(1, 1)

        # Preserve any output already present in the current Streamlit session when
        # this version is first loaded. On a fresh run these values are simply empty.
        first["selected_components"] = list(
            st.session_state.get("selected_components", []) or []
        )
        first["selected_requirement_components"] = _sanitize_requirement_components(
            st.session_state.get("selected_requirement_components", []) or []
        )
        first["selected_connections"] = list(
            st.session_state.get("selected_connections", []) or []
        )
        first["connection_transport_settings"] = dict(
            st.session_state.get("connection_transport_settings", {}) or {}
        )
        first["inline_flow_meter_settings"] = dict(
            st.session_state.get("inline_flow_meter_settings", {}) or {}
        )
        for key in WORKSHEET_OUTPUT_KEYS:
            first[key] = st.session_state.get(key)

        st.session_state["worksheets"] = [first]
        st.session_state["active_worksheet_id"] = 1
        st.session_state["next_worksheet_id"] = 2

    worksheets = st.session_state.get("worksheets", [])
    # Backward-compatible worksheet migrations.
    for sheet in worksheets:
        sheet.setdefault("selected_requirement_components", [])
        sheet["selected_requirement_components"] = _sanitize_requirement_components(
            sheet.get("selected_requirement_components", [])
        )
        sheet.setdefault("selected_connections", [])
        sheet.setdefault("connection_transport_settings", {})
        sheet.setdefault("inline_flow_meter_settings", {})

    valid_ids = [sheet["id"] for sheet in worksheets]
    if not valid_ids:
        first = _new_worksheet(1, 1)
        st.session_state["worksheets"] = [first]
        valid_ids = [1]
        st.session_state["next_worksheet_id"] = 2

    # A newly added worksheet cannot directly modify the selectbox widget state
    # after that widget has already been instantiated in the current Streamlit run.
    # Store the requested selection temporarily, then apply it here on the next
    # rerun, before the worksheet selectbox is created.
    pending_selector = st.session_state.pop("_pending_worksheet_selector", None)
    if pending_selector in valid_ids:
        st.session_state["active_worksheet_id"] = pending_selector
        st.session_state["worksheet_selector"] = pending_selector

    selector_value = st.session_state.get("worksheet_selector")
    if selector_value in valid_ids:
        st.session_state["active_worksheet_id"] = selector_value

    if st.session_state.get("active_worksheet_id") not in valid_ids:
        st.session_state["active_worksheet_id"] = valid_ids[0]

    if st.session_state.get("worksheet_selector") not in valid_ids:
        st.session_state["worksheet_selector"] = st.session_state["active_worksheet_id"]

    # Apply a page requested by the existing ❮ / ❯ controls only after any
    # pending saved-project restore and worksheet-selector synchronization have
    # completed. This keeps the requested saved-project page authoritative for
    # this rerun without changing normal worksheet/dropdown behavior.
    _apply_pending_worksheet_page_navigation_if_needed(valid_ids)


def get_active_worksheet() -> dict:
    active_id = st.session_state.get("active_worksheet_id", 1)
    for sheet in st.session_state.get("worksheets", []):
        if sheet.get("id") == active_id:
            return sheet
    return st.session_state["worksheets"][0]


def load_active_worksheet_state() -> None:
    """Expose the active worksheet through the original state keys.

    The rest of the application continues using its existing keys, so all current
    generation, rendering, details and export functionality remains unchanged.
    """
    sheet = get_active_worksheet()
    st.session_state["selected_components"] = list(
        sheet.get("selected_components", []) or []
    )
    st.session_state["selected_requirement_components"] = _sanitize_requirement_components(
        sheet.get("selected_requirement_components", []) or []
    )
    st.session_state["selected_connections"] = list(
        sheet.get("selected_connections", []) or []
    )
    st.session_state["connection_transport_settings"] = dict(
        sheet.get("connection_transport_settings", {}) or {}
    )
    st.session_state["inline_flow_meter_settings"] = dict(
        sheet.get("inline_flow_meter_settings", {}) or {}
    )
    for key in WORKSHEET_OUTPUT_KEYS:
        value = sheet.get(key)
        if value is None:
            st.session_state.pop(key, None)
        else:
            st.session_state[key] = value


def persist_active_worksheet_state() -> None:
    """Save the current legacy state keys back into the active worksheet."""
    sheet = get_active_worksheet()
    sheet["selected_components"] = list(
        st.session_state.get("selected_components", []) or []
    )
    sheet["selected_requirement_components"] = _sanitize_requirement_components(
        st.session_state.get("selected_requirement_components", []) or []
    )
    sheet["selected_connections"] = list(
        st.session_state.get("selected_connections", []) or []
    )
    sheet["connection_transport_settings"] = dict(
        st.session_state.get("connection_transport_settings", {}) or {}
    )
    sheet["inline_flow_meter_settings"] = dict(
        st.session_state.get("inline_flow_meter_settings", {}) or {}
    )
    for key in WORKSHEET_OUTPUT_KEYS:
        sheet[key] = st.session_state.get(key)


def add_worksheet() -> None:
    """Append one unlimited blank worksheet and make it active on the next rerun."""
    worksheets = st.session_state["worksheets"]
    worksheet_id = int(st.session_state.get("next_worksheet_id", len(worksheets) + 1))
    number = len(worksheets) + 1
    worksheets.append(_new_worksheet(worksheet_id, number))
    st.session_state["next_worksheet_id"] = worksheet_id + 1
    st.session_state["active_worksheet_id"] = worksheet_id
    st.session_state[_WORKSHEET_PAGE_FLOW_KEY] = _worksheet_page_flow_token(
        "worksheet",
        worksheet_id,
    )

    # Do not assign st.session_state["worksheet_selector"] here. At the point the
    # + button is clicked, the selectbox with that key has already been instantiated
    # in this run, and Streamlit correctly rejects modifying its widget state.
    # The pending value is applied by ensure_worksheet_state() before the selectbox
    # is instantiated on the next rerun.
    st.session_state["_pending_worksheet_selector"] = worksheet_id


def rename_worksheet(worksheet_id: int, new_name: str) -> None:
    """Save a worksheet name without changing worksheet or diagram state."""
    new_name = str(new_name or "").strip()
    if not new_name:
        return

    for sheet in st.session_state.get("worksheets", []):
        if sheet.get("id") == int(worksheet_id):
            sheet["name"] = new_name
            break


_WORKSHEET_PAGE_FLOW_KEY = "_worksheet_price_page_flow"
_PENDING_WORKSHEET_PAGE_NAVIGATION_KEY = "_pending_worksheet_page_navigation"


def _apply_pending_worksheet_page_navigation_if_needed(
    valid_worksheet_ids: list[int] | tuple[int, ...],
) -> None:
    """Apply one requested ❮ / ❯ page after saved-project state is restored."""
    target_token = str(
        st.session_state.pop(
            _PENDING_WORKSHEET_PAGE_NAVIGATION_KEY,
            "",
        )
        or ""
    ).strip().lower()
    if not target_token:
        return

    page_type, worksheet_id = _parse_worksheet_page_flow_token(
        target_token
    )

    if page_type == "welcome":
        st.session_state[_WORKSHEET_PAGE_FLOW_KEY] = "welcome"
        st.session_state["_worksheet_page_flow_navigation_target"] = "welcome"
        return

    normalized_valid_ids = {
        int(value)
        for value in list(valid_worksheet_ids or [])
    }
    if (
        page_type not in {"worksheet", "price"}
        or worksheet_id is None
        or int(worksheet_id) not in normalized_valid_ids
    ):
        return

    worksheet_id = int(worksheet_id)
    normalized_target = _worksheet_page_flow_token(
        page_type,
        worksheet_id,
    )
    st.session_state["active_worksheet_id"] = worksheet_id
    st.session_state["worksheet_selector"] = worksheet_id
    st.session_state[_WORKSHEET_PAGE_FLOW_KEY] = normalized_target

    # Keep the existing active-sheet/page synchronization from coercing this
    # deliberate navigation back to the worksheet page during the same rerun.
    st.session_state["_worksheet_page_flow_last_active_id"] = worksheet_id
    st.session_state["_worksheet_page_flow_navigation_target"] = (
        normalized_target
    )


def _worksheet_page_flow_token(
    page_type: str,
    worksheet_id: int | None = None,
) -> str:
    page_type = str(page_type or "").strip().lower()
    if page_type == "welcome":
        return "welcome"
    return f"{page_type}:{int(worksheet_id or 0)}"


def _parse_worksheet_page_flow_token(
    token: str,
) -> tuple[str, int | None]:
    token = str(token or "").strip().lower()
    if token == "welcome":
        return "welcome", None

    if ":" not in token:
        return "", None

    page_type, worksheet_id_text = token.split(":", 1)
    if page_type not in {"worksheet", "price"}:
        return "", None

    try:
        worksheet_id = int(worksheet_id_text)
    except (TypeError, ValueError):
        return "", None

    return page_type, worksheet_id


def _worksheet_page_flow_sequence() -> list[dict]:
    """Return the required page order for all current worksheets.

    Welcome Page -> Worksheet 1 -> Price Details 1 -> Worksheet 2 ->
    Price Details 2 -> ...
    """
    sequence: list[dict] = [
        {
            "token": "welcome",
            "page_type": "welcome",
            "worksheet_id": None,
            "worksheet_number": None,
            "label": "Welcome Page",
        }
    ]

    for worksheet_number, sheet in enumerate(
        st.session_state.get("worksheets", []) or [],
        start=1,
    ):
        worksheet_id = int(sheet.get("id", worksheet_number))
        worksheet_name = str(
            sheet.get("name", f"Worksheet {worksheet_number}")
            or f"Worksheet {worksheet_number}"
        ).strip()

        sequence.append(
            {
                "token": _worksheet_page_flow_token(
                    "worksheet",
                    worksheet_id,
                ),
                "page_type": "worksheet",
                "worksheet_id": worksheet_id,
                "worksheet_number": worksheet_number,
                "label": worksheet_name,
            }
        )
        sequence.append(
            {
                "token": _worksheet_page_flow_token(
                    "price",
                    worksheet_id,
                ),
                "page_type": "price",
                "worksheet_id": worksheet_id,
                "worksheet_number": worksheet_number,
                "label": f"Price Details {worksheet_number}",
            }
        )

    return sequence


def _navigate_worksheet_page_flow(target_token: str) -> None:
    """Navigate one page without changing any existing worksheet behavior."""
    persist_active_worksheet_state()

    target_token = str(target_token or "").strip().lower()
    page_type, worksheet_id = _parse_worksheet_page_flow_token(
        target_token
    )
    st.session_state[_WORKSHEET_PAGE_FLOW_KEY] = target_token

    # Stage the requested page as well as setting it immediately. On the next
    # Streamlit rerun ensure_worksheet_state() reapplies this target *after* any
    # saved-project restore/selector synchronization, preventing the restored
    # project from snapping back to the worksheet that was initially opened.
    st.session_state[_PENDING_WORKSHEET_PAGE_NAVIGATION_KEY] = target_token
    st.session_state["_worksheet_page_flow_navigation_target"] = (
        target_token
    )

    if (
        page_type in {"worksheet", "price"}
        and worksheet_id is not None
    ):
        st.session_state["active_worksheet_id"] = int(worksheet_id)
        # Keep the existing selector synchronization path unchanged.
        st.session_state["_pending_worksheet_selector"] = int(worksheet_id)

    # Keep the arrow target alive through one possible delayed worksheet-dropdown
    # event after a saved project is reopened. Without this one-shot guard, that
    # frontend event can undo the first arrow click and make a second click appear
    # necessary. The guard is consumed immediately when that matching event arrives.
    try:
        st.session_state["_worksheet_page_flow_navigation_selector_id"] = int(
            st.session_state.get("active_worksheet_id")
        )
    except (TypeError, ValueError):
        st.session_state.pop(
            "_worksheet_page_flow_navigation_selector_id",
            None,
        )
    st.session_state["_worksheet_page_flow_navigation_guard_runs"] = 2


def _price_components_for_worksheet(worksheet_id: int) -> list[str]:
    """Return only the generated/selected components belonging to one worksheet."""
    worksheet_id = int(worksheet_id)

    cached = st.session_state.get(
        f"price_details_components_{worksheet_id}"
    )
    if cached is not None:
        return [
            str(name or "").strip()
            for name in list(cached or [])
            if str(name or "").strip()
        ]

    for sheet in st.session_state.get("worksheets", []) or []:
        if int(sheet.get("id", -1)) == worksheet_id:
            return [
                str(name or "").strip()
                for name in list(
                    sheet.get("selected_components", []) or []
                )
                if str(name or "").strip()
            ]

    return []


def handle_worksheet_dropdown_rename_request() -> None:
    """Apply the rename requested by the worksheet dropdown double-click editor."""
    try:
        params = st.query_params
        worksheet_id = params.get("worksheet_rename_id")
        worksheet_name = params.get("worksheet_rename_name")
    except Exception:
        return

    if worksheet_id and worksheet_name:
        rename_worksheet(int(worksheet_id), worksheet_name)
        try:
            st.query_params.clear()
        except Exception:
            pass


def delete_worksheet(worksheet_id: int) -> None:
    """Delete one worksheet and all diagram data stored inside that worksheet."""
    worksheets = st.session_state.get("worksheets", [])
    delete_index = next(
        (index for index, sheet in enumerate(worksheets) if sheet.get("id") == worksheet_id),
        None,
    )
    if delete_index is None:
        return

    # Removing the worksheet dictionary removes its selected components and all
    # generated PNG/PPT/PDF/diagram/hash data together with it.
    del worksheets[delete_index]

    if worksheets:
        next_index = min(delete_index, len(worksheets) - 1)
        next_active_id = worksheets[next_index]["id"]
    else:
        # The application always needs one active worksheet to keep the existing
        # generation workflow usable. If the last worksheet is deleted, create one
        # new blank worksheet with a fresh never-reused id.
        next_active_id = int(st.session_state.get("next_worksheet_id", 1))
        st.session_state["next_worksheet_id"] = next_active_id + 1
        worksheets.append(_new_worksheet(next_active_id, 1))

    st.session_state["active_worksheet_id"] = next_active_id
    st.session_state[_WORKSHEET_PAGE_FLOW_KEY] = _worksheet_page_flow_token(
        "worksheet",
        next_active_id,
    )
    deleted_ids = list(st.session_state.get("_pending_deleted_worksheet_ids", []) or [])
    deleted_ids.append(worksheet_id)
    st.session_state["_pending_deleted_worksheet_ids"] = deleted_ids

    # worksheet_selector is already instantiated when the Delete button is clicked,
    # so apply the new selection on the next rerun just like the existing + button.
    st.session_state["_pending_worksheet_selector"] = next_active_id


def reset_outputs() -> None:
    for key in WORKSHEET_OUTPUT_KEYS:
        st.session_state.pop(key, None)
    if "worksheets" in st.session_state:
        persist_active_worksheet_state()


def clear_sketch_upload(worksheet_id: int) -> None:
    """Clear only the active worksheet's sketch uploader.

    Streamlit file uploaders cannot be assigned ``None`` after creation.  A tiny
    per-worksheet generation counter gives the uploader a fresh widget key on the
    next rerun, which genuinely removes the selected file without touching any
    component-selection, routing, rendering, or backend logic.
    """
    generation_key = f"sketch_upload_generation_{worksheet_id}"
    current_generation = int(st.session_state.get(generation_key, 0) or 0)
    st.session_state[generation_key] = current_generation + 1

@st.dialog("Upload Sketch")
def _show_sketch_upload_dialog(worksheet_id: int) -> None:
    """Compact modal for the existing sketch-upload workflow.

    The main page intentionally shows only one upload icon.  The uploader and
    orientation controls live here so the existing downstream AI/image workflow
    still receives exactly the same UploadedFile object and orientation value.
    """
    generation_key = f"sketch_upload_generation_{worksheet_id}"
    if generation_key not in st.session_state:
        st.session_state[generation_key] = 0

    upload_generation = int(st.session_state.get(generation_key, 0) or 0)
    uploader_key = f"sketch_uploader_{worksheet_id}_{upload_generation}"

    st.file_uploader(
        "Upload sketch image",
        type=["png", "jpg", "jpeg", "webp"],
        key=uploader_key,
        help=(
            "Upload one hand-drawn engineering diagram. The existing AI extraction, "
            "component detection, connection logic, routing and rendering pipeline "
            "remain unchanged."
        ),
    )

    st.selectbox(
        "Image orientation",
        ["Auto / No rotation", "90° clockwise", "90° counter-clockwise", "180°"],
        index=0,
        key=f"image_orientation_{worksheet_id}",
    )

    current_upload = st.session_state.get(uploader_key)
    if current_upload is not None:
        st.success(f"Selected: {current_upload.name}")
        if st.button(
            "Remove sketch",
            key=f"dialog_remove_sketch_{worksheet_id}_{upload_generation}",
            use_container_width=True,
        ):
            clear_sketch_upload(worksheet_id)
            st.rerun()


# =============================================================================
# WELCOME PAGE PREVIEW FROM EXISTING PPT TEMPLATE
# =============================================================================

def _replace_welcome_placeholder_in_slide(slide, replacement: str) -> None:
    """Replace only the YYYYYYYYYYY placeholder on the first template slide."""
    placeholder = "YYYYYYYYYYY"
    replacement = str(replacement or "").strip() or placeholder

    def replace_in_text_frame(text_frame) -> None:
        for paragraph in text_frame.paragraphs:
            replaced_in_run = False
            for run in paragraph.runs:
                if placeholder in str(run.text or ""):
                    run.text = str(run.text or "").replace(placeholder, replacement)
                    replaced_in_run = True

            if not replaced_in_run and placeholder in str(paragraph.text or ""):
                combined = str(paragraph.text or "").replace(placeholder, replacement)
                if paragraph.runs:
                    paragraph.runs[0].text = combined
                    for extra_run in paragraph.runs[1:]:
                        extra_run.text = ""
                else:
                    paragraph.text = combined

    def walk_shape(shape) -> None:
        if getattr(shape, "has_text_frame", False):
            replace_in_text_frame(shape.text_frame)

        if getattr(shape, "has_table", False):
            for row in shape.table.rows:
                for cell in row.cells:
                    replace_in_text_frame(cell.text_frame)

        child_shapes = getattr(shape, "shapes", None)
        if child_shapes is not None:
            for child in child_shapes:
                walk_shape(child)

    for shape in slide.shapes:
        walk_shape(shape)


def _render_first_slide_with_powerpoint(pptx_path: Path, png_path: Path) -> bool:
    """Render slide 1 using locally installed Microsoft PowerPoint on Windows."""
    if os.name != "nt":
        return False

    env = os.environ.copy()
    env["RTS_WELCOME_PPT"] = str(pptx_path)
    env["RTS_WELCOME_PNG"] = str(png_path)

    powershell_script = """
$pptPath = $env:RTS_WELCOME_PPT
$pngPath = $env:RTS_WELCOME_PNG
$powerPoint = $null
$presentation = $null
try {
    $powerPoint = New-Object -ComObject PowerPoint.Application
    $powerPoint.Visible = 0
    $presentation = $powerPoint.Presentations.Open($pptPath, $true, $false, $false)
    $slide = $presentation.Slides.Item(1)
    $slide.Export($pngPath, "PNG", 1600, 900)
}
finally {
    if ($presentation -ne $null) { $presentation.Close() }
    if ($powerPoint -ne $null) { $powerPoint.Quit() }
}
"""

    try:
        completed = subprocess.run(
            [
                "powershell",
                "-NoProfile",
                "-ExecutionPolicy",
                "Bypass",
                "-Command",
                powershell_script,
            ],
            env=env,
            stdout=subprocess.DEVNULL,
            stderr=subprocess.DEVNULL,
            timeout=35,
            check=False,
        )
        return (
            completed.returncode == 0
            and png_path.exists()
            and png_path.stat().st_size > 0
        )
    except Exception:
        return False


def _render_first_slide_with_libreoffice(
    pptx_path: Path,
    png_path: Path,
    work_dir: Path,
) -> bool:
    """Cross-platform fallback: LibreOffice -> PDF -> first-page PNG."""
    soffice = shutil.which("soffice") or shutil.which("libreoffice")
    if not soffice:
        return False

    try:
        completed = subprocess.run(
            [
                soffice,
                "--headless",
                "--convert-to",
                "pdf",
                "--outdir",
                str(work_dir),
                str(pptx_path),
            ],
            stdout=subprocess.DEVNULL,
            stderr=subprocess.DEVNULL,
            timeout=35,
            check=False,
        )
        if completed.returncode != 0:
            return False

        pdf_path = work_dir / f"{pptx_path.stem}.pdf"
        if not pdf_path.exists():
            return False

        try:
            import fitz
        except Exception:
            return False

        with fitz.open(str(pdf_path)) as pdf:
            if len(pdf) < 1:
                return False
            page = pdf[0]
            pix = page.get_pixmap(matrix=fitz.Matrix(1.8, 1.8), alpha=False)
            pix.save(str(png_path))

        return png_path.exists() and png_path.stat().st_size > 0
    except Exception:
        return False


@st.cache_data(max_entries=24, show_spinner=False)
def _welcome_page_png_from_template(
    template_path_text: str,
    template_mtime_ns: int,
    template_size: int,
    display_name: str,
) -> bytes:
    """Render the first existing PPT-template slide with one placeholder replaced."""
    del template_mtime_ns, template_size

    template_path = Path(template_path_text)
    if not template_path.is_file():
        return b""

    try:
        from pptx import Presentation
    except Exception:
        return b""

    with tempfile.TemporaryDirectory(prefix="rts_welcome_") as temp_dir_text:
        temp_dir = Path(temp_dir_text)
        preview_pptx = temp_dir / "welcome_preview.pptx"
        preview_png = temp_dir / "welcome_preview.png"

        try:
            presentation = Presentation(str(template_path))
            if not presentation.slides:
                return b""

            _replace_welcome_placeholder_in_slide(
                presentation.slides[0],
                display_name,
            )
            presentation.save(str(preview_pptx))
        except Exception:
            return b""

        rendered = _render_first_slide_with_powerpoint(
            preview_pptx,
            preview_png,
        )
        if not rendered:
            rendered = _render_first_slide_with_libreoffice(
                preview_pptx,
                preview_png,
                temp_dir,
            )

        if not rendered:
            return b""

        try:
            return preview_png.read_bytes()
        except OSError:
            return b""


def _get_welcome_page_png(display_name: str) -> bytes:
    """Return cached Welcome Page bytes from the project's existing PPT template."""
    if not DEFAULT_PPT_TEMPLATE_PATH.is_file():
        return b""

    try:
        stat = DEFAULT_PPT_TEMPLATE_PATH.stat()
        return _welcome_page_png_from_template(
            str(DEFAULT_PPT_TEMPLATE_PATH.resolve()),
            int(stat.st_mtime_ns),
            int(stat.st_size),
            str(display_name or "").strip(),
        )
    except OSError:
        return b""




def _welcome_page_font(size: int):
    """Use an available serif font close to the supplied placeholder style."""
    candidates = (
        Path("C:/Windows/Fonts/times.ttf"),
        Path("C:/Windows/Fonts/timesbd.ttf"),
        Path("/usr/share/fonts/truetype/dejavu/DejaVuSerif.ttf"),
        Path("/usr/share/fonts/truetype/dejavu/DejaVuSerifCondensed.ttf"),
    )
    for candidate in candidates:
        try:
            if candidate.is_file():
                return ImageFont.truetype(str(candidate), int(size))
        except Exception:
            pass
    try:
        return ImageFont.truetype("DejaVuSerif.ttf", int(size))
    except Exception:
        return ImageFont.load_default()


@st.cache_data(max_entries=32, show_spinner=False)
def _exact_welcome_page_png(
    image_path_text: str,
    image_mtime_ns: int,
    image_size: int,
    display_name: str,
) -> bytes:
    """Return the supplied Welcome Page with only the YYYYYYYYYYYYY text replaced."""
    del image_mtime_ns, image_size
    image_path = Path(image_path_text)
    if not image_path.is_file():
        return b""

    try:
        with Image.open(image_path) as source:
            canvas = source.convert("RGB")
    except Exception:
        return b""

    display_name = str(display_name or "").strip()
    if not display_name:
        output = io.BytesIO()
        canvas.save(output, format="PNG")
        return output.getvalue()

    draw = ImageDraw.Draw(canvas)

    # Coordinates are proportional to the exact 1362x758 reference image.
    sx = canvas.width / 1362.0
    sy = canvas.height / 758.0
    cover_box = (
        int(round(370 * sx)),
        int(round(214 * sy)),
        int(round(1000 * sx)),
        int(round(292 * sy)),
    )

    # Exact orange from the supplied image; only the placeholder area is covered.
    draw.rectangle(cover_box, fill=(211, 72, 23))

    max_width = int((cover_box[2] - cover_box[0]) * 0.94)
    max_height = int((cover_box[3] - cover_box[1]) * 0.78)

    font_size = max(18, int(round(64 * min(sx, sy))))
    min_size = max(14, int(round(26 * min(sx, sy))))

    while True:
        font = _welcome_page_font(font_size)
        bbox = draw.textbbox((0, 0), display_name, font=font)
        text_w = bbox[2] - bbox[0]
        text_h = bbox[3] - bbox[1]
        if (text_w <= max_width and text_h <= max_height) or font_size <= min_size:
            break
        font_size -= 2

    center_x = (cover_box[0] + cover_box[2]) / 2.0
    center_y = (cover_box[1] + cover_box[3]) / 2.0
    text_x = center_x - (text_w / 2.0) - bbox[0]
    text_y = center_y - (text_h / 2.0) - bbox[1]

    draw.text((text_x, text_y), display_name, font=font, fill=(255, 255, 255))

    output = io.BytesIO()
    canvas.save(output, format="PNG")
    return output.getvalue()


def _get_exact_welcome_page_png(display_name: str) -> bytes:
    """Load the exact supplied Welcome Page and replace only the name placeholder."""
    display_name = str(display_name or "").strip()

    # Use the existing external file when it is present.
    if WELCOME_PAGE_REFERENCE_PATH.is_file():
        try:
            stat = WELCOME_PAGE_REFERENCE_PATH.stat()
            result = _exact_welcome_page_png(
                str(WELCOME_PAGE_REFERENCE_PATH.resolve()),
                int(stat.st_mtime_ns),
                int(stat.st_size),
                display_name,
            )
            if result:
                return result
        except OSError:
            pass

    # Fallback to the exact same Welcome Page embedded in this app.py.
    try:
        raw_image = base64.b64decode(WELCOME_PAGE_REFERENCE_B64)
        with Image.open(io.BytesIO(raw_image)) as source:
            canvas = source.convert("RGB")
    except Exception:
        return b""

    if not display_name:
        output = io.BytesIO()
        canvas.save(output, format="PNG")
        return output.getvalue()

    draw = ImageDraw.Draw(canvas)

    sx = canvas.width / 1362.0
    sy = canvas.height / 758.0
    cover_box = (
        int(round(370 * sx)),
        int(round(214 * sy)),
        int(round(1000 * sx)),
        int(round(292 * sy)),
    )
    draw.rectangle(cover_box, fill=(211, 72, 23))

    max_width = int((cover_box[2] - cover_box[0]) * 0.94)
    max_height = int((cover_box[3] - cover_box[1]) * 0.78)
    font_size = max(18, int(round(64 * min(sx, sy))))
    min_size = max(14, int(round(26 * min(sx, sy))))

    while True:
        font = _welcome_page_font(font_size)
        bbox = draw.textbbox((0, 0), display_name, font=font)
        text_w = bbox[2] - bbox[0]
        text_h = bbox[3] - bbox[1]
        if (text_w <= max_width and text_h <= max_height) or font_size <= min_size:
            break
        font_size -= 2

    center_x = (cover_box[0] + cover_box[2]) / 2.0
    center_y = (cover_box[1] + cover_box[3]) / 2.0
    text_x = center_x - (text_w / 2.0) - bbox[0]
    text_y = center_y - (text_h / 2.0) - bbox[1]

    draw.text(
        (text_x, text_y),
        display_name,
        font=font,
        fill=(255, 255, 255),
    )

    output = io.BytesIO()
    canvas.save(output, format="PNG")
    return output.getvalue()


def _render_welcome_page_full_view(display_name: str) -> None:
    """Render the Welcome Page as HTML/CSS using only the existing Welcome Page text."""
    safe_name = str(display_name or "").strip() or "YYYYYYYYYYYYY"
    safe_name = (
        safe_name
        .replace("&", "&amp;")
        .replace("<", "&lt;")
        .replace(">", "&gt;")
        .replace('"', "&quot;")
        .replace("'", "&#39;")
    )

    # Important: keep the HTML left-aligned in the string.
    # Markdown treats 4+ leading spaces as a code block, even with unsafe_allow_html=True.
    welcome_html = f"""<div class="rts-welcome-modern-page"><div class="rts-welcome-modern-shell"><div class="rts-welcome-modern-header"><div class="rts-welcome-modern-title">Smart Water Management System</div><div class="rts-welcome-modern-accent"></div></div><div class="rts-welcome-modern-name-panel"><div class="rts-welcome-modern-name">{safe_name}</div></div><div class="rts-welcome-modern-content"><div class="rts-welcome-modern-brand-card"><img class="rts-welcome-modern-realtech-logo" src="data:image/png;base64," alt="REAL TECH SYSTEMS"><img class="rts-welcome-modern-qr rts-welcome-modern-qr-left" src="data:image/png;base64," alt="Real Tech QR Code"></div><div class="rts-welcome-modern-center-line"></div><div class="rts-welcome-modern-brand-card rts-welcome-modern-brand-card-right"><img class="rts-welcome-modern-itank-logo" src="data:image/png;base64," alt="iTank"><img class="rts-welcome-modern-qr rts-welcome-modern-qr-right" src="data:image/png;base64," alt="iTank QR Code"></div></div><div class="rts-welcome-modern-support"><span class="rts-welcome-modern-support-label">FOR SUPPORT:</span><span class="rts-welcome-modern-support-at">@</span><span class="rts-welcome-modern-support-number">9865212396</span></div></div></div>"""

    st.markdown(
        welcome_html,
        unsafe_allow_html=True,
    )


def get_gemini_client():
    api_key = os.getenv("GEMINI_API_KEY")
    if not api_key:
        raise RuntimeError("GEMINI_API_KEY is missing. Add it to your .env file.")
    return _cached_gemini_client(api_key)


def safe_confidence(value) -> float:
    try:
        return round(float(value), 2)
    except (TypeError, ValueError):
        return 0.0


def get_component_asset_status() -> dict:
    status = {}
    for node_type, config in REQUIRED_COMPONENT_ASSETS.items():
        try:
            path = component_asset_path(ASSETS_DIR, node_type)
        except Exception as exc:
            log_app_error(f"Component asset lookup: {node_type}", exc)
            path = None
        status[node_type] = {
            "display_name": config["display_name"],
            "expected_names": config["expected_names"],
            "found": path is not None,
            "path": path,
        }
    return status


def missing_required_assets() -> list[dict]:
    return [item for item in get_component_asset_status().values() if not item["found"]]


def validate_required_assets() -> None:
    missing = missing_required_assets()
    if not missing:
        return
    lines = [f"{item['display_name']}: {item['expected_names']}" for item in missing]
    raise RuntimeError(
        "Required component images are missing.\n\n"
        f"Place these inside: {ASSETS_DIR}\n\n" + "\n".join(lines)
    )


def display_label(node) -> str:
    label = " ".join(str(getattr(node, "label", "") or "").split())
    return label or str(getattr(node, "id", "Component")).replace("_", " ").title()


def _add_wireless_symbol_above_component(asset_rgba: Image.Image) -> Image.Image:
    """Add only a clear Wi-Fi symbol above a wireless communication component image."""
    source = asset_rgba.convert("RGBA")
    icon_height = max(24, min(42, int(round(source.height * 0.30))))
    canvas_width = max(source.width, 44)
    canvas = Image.new(
        "RGBA",
        (canvas_width, source.height + icon_height),
        (255, 255, 255, 0),
    )

    image_x = (canvas_width - source.width) // 2
    canvas.alpha_composite(source, (image_x, icon_height))

    draw = ImageDraw.Draw(canvas)
    cx = canvas_width // 2
    baseline_y = icon_height - 5
    stroke = max(2, int(round(icon_height * 0.085)))
    wifi_color = (7, 76, 165, 255)

    # Three clean Wi-Fi arcs plus the center dot.  The icon is drawn in the new
    # transparent band, so it appears clearly above the existing component image.
    for radius in (int(icon_height * 0.42), int(icon_height * 0.31), int(icon_height * 0.20)):
        box = (cx - radius, baseline_y - radius, cx + radius, baseline_y + radius)
        draw.arc(box, start=205, end=335, fill=wifi_color, width=stroke)

    dot_r = max(2, int(round(icon_height * 0.065)))
    draw.ellipse(
        (cx - dot_r, baseline_y - dot_r, cx + dot_r, baseline_y + dot_r),
        fill=wifi_color,
    )
    return canvas


@st.cache_data(max_entries=128, show_spinner=False)
def _component_dropdown_css_thumbnail(
    path_text: str,
    mtime_ns: int,
    file_size: int,
) -> str:
    """Create a tiny image used only beside native component dropdown rows."""
    del mtime_ns, file_size
    try:
        with Image.open(path_text) as source:
            thumb = source.convert("RGBA")
            thumb.thumbnail((34, 34), Image.Resampling.LANCZOS)
            canvas = Image.new("RGBA", (34, 34), (255, 255, 255, 0))
            canvas.alpha_composite(
                thumb,
                ((34 - thumb.width) // 2, (34 - thumb.height) // 2),
            )
            buffer = io.BytesIO()
            canvas.save(buffer, format="PNG")
            return base64.b64encode(buffer.getvalue()).decode("ascii")
    except Exception as exc:
        log_app_error("Component dropdown image thumbnail", exc)
        return ""


def _component_dropdown_image_uri(component_name: str) -> str:
    """Return the exact dropdown image for the existing component name.

    The existing native Streamlit list is not changed.
    The project's real manually-copied *.png.png images are preferred first.
    No generic or cross-component fallback image is allowed.
    """
    component_name = str(component_name or "").strip()
    if not component_name:
        return ""

    image_dir = ROOT_DIR / "assets" / "component_images"

    exact_files = {
        "Master": ["Master.png.png", "Master.png"],
        "Sump": ["Sump.png.png", "Sump.png"],
        "Bore Well": [
            "Bore well.png.png",
            "Bore Well.png.png",
            "Bore well.png",
            "Bore Well.png",
        ],
        "Well": ["well.png.png", "Well.png.png", "well.png", "Well.png"],
        "Transmitter": ["Transmitter.png.png", "Transmitter.png"],
        "Repeater": ["Repeater.png.png", "Repeater.png"],
        "Display with GSM (DWG)": ["DWG.png.png", "DWG.png"],
        "Linear Level Sensor (LLS)": ["LLS.png"],
        "Motorized Valve (MV)": ["Motorized Valve.png.png", "Motorized Valve.png"],
        "Pressure Relief Valve (PRV)": ["PRV.png.png", "PRV.png"],
        "Non-Return Valve (NRV)": ["NRV.png.png", "NRV.png"],
        "OHT Tank": ["OHT Tank.png.png", "OHT Tank.png"],
        "Motor (Pump)": ["motor.png.png", "Motor.png.png", "motor.png", "Motor.png"],
        "Smart Motor Controller (SMC)": ["SMC.png.png", "SMC.png"],
        "Valve Controller (VCT)": ["VCT.png.png", "VCT.png"],
        "Auto Change Over Unit": [
            "Auto Change over.png.png",
            "Auto Change Over.png.png",
            "Auto Change over.png",
            "Auto Change Over.png",
        ],
        "Ultrasonic Flow Meter": ["Flow meter.png.png", "Flow meter.png"],
        "Flush Flow Meter": ["Flow meter.png.png", "Flow meter.png"],
        "Electromagnetic Flow Meter": ["Flow meter.png.png", "Flow meter.png"],
        "Valve Control Unit (VCU)": ["VCU.png.png", "VCU.png"],
        "Display (D)": ["Display.png.png", "Display.png"],
        "Data Logger": ["Data Logger.png.png", "Data Logger.png"],
        "OHT Tank with Valve": [
            "OHT Tank with Valve.png.png",
            "OHT Tank with Valve.png",
        ],
        "OHT Tank without Valve": [
            "OHT Tank without Valve.png.png",
            "OHT Tank without Valve.png",
        ],
    }

    asset_path = None
    for filename in exact_files.get(component_name, []):
        candidate = image_dir / filename
        if candidate.is_file():
            asset_path = candidate
            break

    # Never fall back to another component or to the renderer's older mapping.
    if asset_path is None:
        return ""

    try:
        stat = asset_path.stat()
        encoded = _component_dropdown_css_thumbnail(
            str(asset_path.resolve()),
            int(stat.st_mtime_ns),
            int(stat.st_size),
        )
    except Exception as exc:
        log_app_error(f"Component image lookup: {component_name}", exc)
        return ""

    return f"data:image/png;base64,{encoded}" if encoded else ""


@guarded_ui("Component selection image decoration", action="loading component images")
def _render_native_component_dropdown_image_decorator(
    component_names: list[str],
) -> None:
    """Decorate the EXISTING Streamlit component dropdown with exact images.

    The native st.multiselect remains the real control. This helper only observes
    its already-existing popup options and appends a matching image beside each
    component name. "Select all" is left untouched.
    """
    image_map = {
        name: _component_dropdown_image_uri(name)
        for name in list(component_names or [])
    }
    image_map = {
        name: uri for name, uri in image_map.items()
        if isinstance(uri, str) and uri.startswith("data:image/")
    }
    if not image_map:
        return

    payload = json.dumps(image_map)
    components.html(
        f"""
<script>
(() => {{
  const imageMap = {payload};

  function decorateNativeComponentList() {{
    let doc;
    try {{
      doc = window.parent.document;
    }} catch (e) {{
      return;
    }}

    const optionSelectors = [
      '[data-baseweb="popover"] [role="listbox"] [role="option"]',
      '[data-baseweb="popover"] [role="option"]',
      '[role="listbox"] [role="option"]'
    ];

    const seen = new Set();
    optionSelectors.forEach(selector => {{
      doc.querySelectorAll(selector).forEach(option => {{
        if (seen.has(option)) return;
        seen.add(option);

        const label = (option.textContent || '').trim();
        if (!label || label === 'Select all' || !imageMap[label]) return;

        if (option.querySelector(':scope > img[data-rts-component-option-image="1"]')) {{
          return;
        }}

        option.style.position = 'relative';
        option.style.paddingRight = '52px';

        const img = doc.createElement('img');
        img.setAttribute('data-rts-component-option-image', '1');
        img.alt = label;
        img.src = imageMap[label];
        img.style.position = 'absolute';
        img.style.right = '9px';
        img.style.top = '50%';
        img.style.transform = 'translateY(-50%)';
        img.style.width = '34px';
        img.style.height = '34px';
        img.style.objectFit = 'contain';
        img.style.pointerEvents = 'none';
        img.style.zIndex = '2';

        option.appendChild(img);
      }});
    }});
  }}

  decorateNativeComponentList();

  let parentBody;
  try {{
    parentBody = window.parent.document.body;
  }} catch (e) {{
    return;
  }}

  const observer = new MutationObserver(() => {{
    requestAnimationFrame(decorateNativeComponentList);
  }});
  observer.observe(parentBody, {{
    childList: true,
    subtree: true
  }});

  const timer = setInterval(decorateNativeComponentList, 300);

  window.addEventListener('beforeunload', () => {{
    observer.disconnect();
    clearInterval(timer);
  }});
}})();
</script>
        """,
        height=0,
        width=0,
    )


def _native_component_dropdown_image_css(component_names: list[str]) -> str:
    """Add images beside rows in the EXISTING native component multiselect only.

    The existing Streamlit multiselect, Search box, Select All row, component
    names, order, selection behavior, layout and styling are unchanged.
    Only a component-specific image is added beside each existing option row.
    """
    names = list(component_names or [])
    rules: list[str] = []

    # Keep the existing native list. Streamlit/BaseWeb mounts its open option list
    # in a portal, so scope the portal styling by detecting that THIS component
    # multiselect is currently expanded.
    open_guards = [
        'body:has([class*="st-key-component_compact_multiselect_"] [aria-expanded="true"])',
        'body:has([class*="st-key-component_compact_multiselect_"] [data-baseweb="select"]:focus-within)',
        'body:has([class*="st-key-component_section_compact_"] [aria-expanded="true"])',
    ]

    option_bases = [
        '[data-baseweb="popover"] [role="listbox"] > [role="option"]',
        '[data-baseweb="popover"] [role="option"]',
        '[role="listbox"] > [role="option"]',
    ]

    # "Select all" is the first existing native option. Never add an image there.
    for guard in open_guards:
        for base in option_bases:
            rules.append(
                f"""
{guard} {base}:nth-child(1)::after {{
    content: none !important;
    display: none !important;
    background-image: none !important;
}}
"""
            )

    # Existing option 2 = first catalog component, option 3 = second, etc.
    for option_index, component_name in enumerate(names, start=2):
        image_uri = _component_dropdown_image_uri(component_name)
        if not image_uri:
            continue

        for guard in open_guards:
            for base in option_bases:
                selector = f"{guard} {base}:nth-child({option_index})"
                rules.append(
                    f"""
{selector} {{
    position: relative !important;
    padding-right: 52px !important;
    min-height: 46px !important;
}}
{selector}::after {{
    content: "" !important;
    display: block !important;
    position: absolute !important;
    right: 9px !important;
    top: 50% !important;
    transform: translateY(-50%) !important;
    width: 34px !important;
    height: 34px !important;
    background-image: url("{image_uri}") !important;
    background-repeat: no-repeat !important;
    background-position: center center !important;
    background-size: contain !important;
    pointer-events: none !important;
    z-index: 999999 !important;
}}
"""
                )

    return "<style>" + "\n".join(rules) + "</style>" if rules else ""


def build_component_selection_df(selected_names: list[str] | None = None) -> pd.DataFrame:
    """Build the existing component table with an editable quantity per component.

    ``selected_names`` may contain the same component more than once.  The table
    stays one row per component; the Qty column controls how many instances of
    that component are generated when the row is selected.
    """
    selected_counts = Counter(selected_names or [])
    rows = []
    for index, item in enumerate(COMPONENT_CATALOG, start=1):
        quantity = int(selected_counts.get(item.name, 0))
        rows.append(
            {
                "Select": quantity > 0,
                "Qty": max(1, quantity),
                "#": index,
                "Component Type": item.group,
                "Component": item.name,
                "Code": item.code,
                "Details": item.connection_label,
            }
        )
    return pd.DataFrame(rows)


def selected_components_from_table(edited_table: pd.DataFrame) -> list[str]:
    """Expand the table selection into one item per requested component instance."""
    selected: list[str] = []
    for _, row in edited_table.iterrows():
        if not bool(row.get("Select", False)):
            continue

        try:
            quantity = int(row.get("Qty", 1))
        except (TypeError, ValueError):
            quantity = 1

        quantity = max(1, quantity)
        component_name = str(row.get("Component", "")).strip()
        if component_name:
            selected.extend([component_name] * quantity)

    return selected


def _component_selection_from_editor_delta(
    current_selected: list[str],
    editor_state: object,
) -> list[str]:
    """Merge *all* data-editor row edits into one canonical selection list.

    Streamlit stores ``st.data_editor`` edits as a row-indexed delta.  Treating
    only the latest edited row as the source of truth can drop earlier checkbox
    selections when several components are selected quickly.  This helper starts
    from the complete accepted selection, applies every pending row delta in one
    batch, and then rebuilds the list in catalog order.  There is deliberately no
    component-count or instance-count limit.
    """
    counts = Counter(current_selected or [])
    catalog_names = [item.name for item in COMPONENT_CATALOG]
    valid_names = set(catalog_names)

    # Ignore unknown/stale component names while preserving every valid count.
    counts = Counter(
        {name: max(0, int(value)) for name, value in counts.items() if name in valid_names}
    )

    if not isinstance(editor_state, dict):
        editor_state = {}
    edited_rows = editor_state.get("edited_rows", {}) or {}

    for raw_index, changes in edited_rows.items():
        try:
            row_index = int(raw_index)
        except (TypeError, ValueError):
            continue
        if not (0 <= row_index < len(catalog_names)) or not isinstance(changes, dict):
            continue

        component_name = catalog_names[row_index]
        current_count = int(counts.get(component_name, 0))
        selected_now = current_count > 0
        quantity_now = max(1, current_count)

        if "Select" in changes:
            selected_now = bool(changes.get("Select"))

        if "Qty" in changes:
            try:
                quantity_now = max(1, int(changes.get("Qty", 1)))
            except (TypeError, ValueError, OverflowError):
                quantity_now = max(1, current_count or 1)

        counts[component_name] = quantity_now if selected_now else 0

    selected: list[str] = []
    for component_name in catalog_names:
        quantity = max(0, int(counts.get(component_name, 0)))
        if quantity:
            selected.extend([component_name] * quantity)
    return selected


def _commit_component_editor_state(editor_key: str, worksheet_id: int) -> None:
    """Commit all checkbox/Qty edits before expensive diagram generation starts."""
    current_selected = list(st.session_state.get("selected_components", []) or [])
    merged_selected = _component_selection_from_editor_delta(
        current_selected,
        st.session_state.get(editor_key, {}),
    )
    st.session_state["selected_components"] = merged_selected

    # Keep only connection intents whose exact instance endpoints still exist.
    # Newly available connections are intentionally left unchecked, preserving
    # the existing 2A behavior.
    valid_option_ids = {option.id for option in allowed_connection_options(merged_selected)}
    st.session_state["selected_connections"] = [
        connection_id
        for connection_id in list(st.session_state.get("selected_connections", []) or [])
        if connection_id in valid_option_ids
    ]
    st.session_state["connection_transport_settings"] = {
        connection_id: _sanitize_connection_transport_setting(config)
        for connection_id, config in dict(
            st.session_state.get("connection_transport_settings", {}) or {}
        ).items()
        if connection_id in valid_option_ids
    }

    # Save the whole collection once; downstream generation then processes the
    # complete batch rather than one component at a time.
    persist_active_worksheet_state()


def selected_component_summary(selected_names: list[str]) -> str:
    """Return a compact selection summary such as 'OHT Tank × 2, Motor × 3'."""
    counts = Counter(selected_names)
    ordered_names = [item.name for item in COMPONENT_CATALOG if counts.get(item.name, 0)]
    return ", ".join(
        f"{name} × {counts[name]}" if counts[name] > 1 else f"{name} × 1"
        for name in ordered_names
    )


