def calculate_selected_component_price(
    selected_names: list[str] | tuple[str, ...] | None,
) -> tuple[int, int]:
    """Return selected-component total as (unit-cost total, with-tax total).

    Repeated component instances are counted independently. Components for which
    the supplied images contain no price are intentionally left out instead of
    inventing a value.
    """
    counts = Counter(
        str(name or "").strip()
        for name in list(selected_names or [])
        if str(name or "").strip()
    )

    unit_total = 0
    tax_total = 0

    for component_name, quantity in counts.items():
        price_source = APP_COMPONENT_PRICE_SOURCE.get(
            component_name,
            component_name,
        )
        price_row = COMPONENT_PRICE_LIST.get(price_source)
        if not price_row:
            continue

        quantity = max(0, int(quantity))
        unit_total += int(price_row["unit_cost"]) * quantity
        tax_total += int(price_row["with_tax"]) * quantity

    return int(unit_total), int(tax_total)




@st.dialog("Edit Final Amount")
def _show_price_adjustment_dialog(
    worksheet_id: int,
    tax_total: int,
) -> None:
    """Edit only the final customer amount after the existing tax calculation."""
    safe_worksheet_id = int(worksheet_id or 0)
    tax_total = int(tax_total or 0)
    adjustment_key = f"price_details_adjustment_{safe_worksheet_id}"

    adjustment_state = dict(
        st.session_state.get(adjustment_key, {}) or {}
    )

    # Preserve the existing behavior: if the underlying With Tax value changed,
    # begin from the new correct calculated tax total.
    if int(adjustment_state.get("base_tax_total", -1) or -1) != tax_total:
        adjustment_state = {
            "base_tax_total": tax_total,
            "mode": "none",
            "value": 0.0,
            "final_amount": tax_total,
        }
        st.session_state[adjustment_key] = adjustment_state

    current_mode = str(adjustment_state.get("mode", "none") or "none")
    current_value = float(adjustment_state.get("value", 0.0) or 0.0)
    final_customer_amount = int(
        adjustment_state.get("final_amount", tax_total) or 0
    )

    st.caption(f"Calculated With Tax: ₹{tax_total:,}")

    mode_options = ["Fixed Amount", "Percentage Reduction"]
    default_mode = (
        "Percentage Reduction"
        if current_mode == "percentage"
        else "Fixed Amount"
    )

    adjustment_mode = st.radio(
        "Adjustment Type",
        mode_options,
        index=mode_options.index(default_mode),
        horizontal=True,
        key=f"price_adjustment_mode_{safe_worksheet_id}",
    )

    if adjustment_mode == "Fixed Amount":
        fixed_default = (
            float(final_customer_amount)
            if current_mode == "fixed"
            else float(tax_total)
        )

        fixed_amount = st.number_input(
            "Final Customer Amount (₹)",
            min_value=0.0,
            value=fixed_default,
            step=100.0,
            format="%.0f",
            key=f"price_adjustment_fixed_{safe_worksheet_id}",
            help="Example: change ₹24,489 to ₹25,000 or ₹20,000.",
        )

        if st.button(
            "Apply Fixed Amount",
            use_container_width=True,
            key=f"apply_price_fixed_{safe_worksheet_id}",
        ):
            final_customer_amount = max(
                0,
                int(round(float(fixed_amount))),
            )
            st.session_state[adjustment_key] = {
                "base_tax_total": tax_total,
                "mode": "fixed",
                "value": float(final_customer_amount),
                "final_amount": int(final_customer_amount),
            }
            st.rerun()

    else:
        percentage_default = (
            float(current_value)
            if current_mode == "percentage"
            else 0.0
        )

        percentage_value = st.number_input(
            "Reduction Percentage (%)",
            min_value=0.0,
            max_value=100.0,
            value=percentage_default,
            step=1.0,
            format="%.2f",
            key=f"price_adjustment_percentage_{safe_worksheet_id}",
            help="Example: enter 3 for 3% reduction or 4 for 4% reduction.",
        )

        percentage_preview = max(
            0,
            int(
                round(
                    float(tax_total)
                    * (1.0 - (float(percentage_value) / 100.0))
                )
            ),
        )
        st.caption(
            f"Final amount after {float(percentage_value):g}% reduction: "
            f"₹{percentage_preview:,}"
        )

        if st.button(
            "Apply Percentage",
            use_container_width=True,
            key=f"apply_price_percentage_{safe_worksheet_id}",
        ):
            percentage_value = max(
                0.0,
                min(100.0, float(percentage_value)),
            )
            final_customer_amount = max(
                0,
                int(
                    round(
                        float(tax_total)
                        * (1.0 - (percentage_value / 100.0))
                    )
                ),
            )
            st.session_state[adjustment_key] = {
                "base_tax_total": tax_total,
                "mode": "percentage",
                "value": float(percentage_value),
                "final_amount": int(final_customer_amount),
            }
            st.rerun()

    if current_mode != "none":
        if st.button(
            "Reset Adjustment",
            use_container_width=True,
            key=f"reset_price_adjustment_{safe_worksheet_id}",
        ):
            st.session_state[adjustment_key] = {
                "base_tax_total": tax_total,
                "mode": "none",
                "value": 0.0,
                "final_amount": tax_total,
            }
            st.rerun()


def _render_price_details_page(
    selected_names: list[str] | tuple[str, ...] | None,
    worksheet_id: int | None = None,
    page_title: str = "Price Details",
) -> None:
    """Render the existing Price Details page plus final-customer-price editing.

    The existing UNIT COST / WITHOUT GST / WITH TAX calculations are unchanged.
    The new adjustment applies only AFTER the calculated With Tax total.
    """
    names = [
        str(name or "").strip()
        for name in list(selected_names or [])
        if str(name or "").strip()
    ]
    counts = Counter(names)

    # Preserve the existing selected-component order while removing duplicates.
    ordered_names: list[str] = []
    seen_names: set[str] = set()
    for name in names:
        if name not in seen_names:
            ordered_names.append(name)
            seen_names.add(name)

    # EXISTING calculation - do not change.
    unit_total, tax_total = calculate_selected_component_price(names)

    # ---------------------------------------------------------------------
    # NEW FEATURE ONLY:
    # Persist a final-customer-price adjustment per Worksheet.
    #
    # The 18% With Tax value remains the original calculated value.
    # This adjustment is applied only after tax_total has been calculated.
    # ---------------------------------------------------------------------
    safe_worksheet_id = int(worksheet_id or 0)
    adjustment_key = f"price_details_adjustment_{safe_worksheet_id}"

    adjustment_state = dict(
        st.session_state.get(adjustment_key, {}) or {}
    )

    # If the underlying calculated With Tax total changes because components
    # changed, start the customer adjustment from the new correct tax total.
    if int(adjustment_state.get("base_tax_total", -1) or -1) != int(tax_total):
        adjustment_state = {
            "base_tax_total": int(tax_total),
            "mode": "none",
            "value": 0.0,
            "final_amount": int(tax_total),
        }
        st.session_state[adjustment_key] = adjustment_state

    current_mode = str(adjustment_state.get("mode", "none") or "none")
    current_value = float(adjustment_state.get("value", 0.0) or 0.0)
    final_customer_amount = int(
        adjustment_state.get("final_amount", tax_total) or 0
    )

    # Price Edit trigger only. The edit controls now open in a modal dialog
    # instead of the previous dropdown/popover.
    with st.container(key=f"price_edit_control_{safe_worksheet_id}"):
        if st.button(
            "✎ Edit Final Amount",
            key=f"open_price_adjustment_modal_{safe_worksheet_id}",
            use_container_width=False,
        ):
            _show_price_adjustment_dialog(
                safe_worksheet_id,
                int(tax_total),
            )

    # Re-read after any normal navigation rerun so the chosen value persists.
    adjustment_state = dict(
        st.session_state.get(adjustment_key, {}) or {}
    )
    current_mode = str(adjustment_state.get("mode", "none") or "none")
    current_value = float(adjustment_state.get("value", 0.0) or 0.0)
    final_customer_amount = int(
        adjustment_state.get("final_amount", tax_total) or 0
    )

    rows_html: list[str] = []
    serial_no = 1

    for component_name in ordered_names:
        quantity = max(0, int(counts.get(component_name, 0)))
        if quantity <= 0:
            continue

        price_source = APP_COMPONENT_PRICE_SOURCE.get(
            component_name,
            component_name,
        )
        price_row = COMPONENT_PRICE_LIST.get(price_source)

        # Price Details must show only components present in the supplied
        # price sheets. Base worksheet items such as Sump / Bore Well / OHT Tank
        # are therefore not displayed here because no supplied price row exists.
        if not price_row:
            continue

        display_name = PRICE_DETAILS_DISPLAY_NAME.get(price_source)
        if not display_name:
            continue

        safe_component = (
            display_name
            .replace("&", "&amp;")
            .replace("<", "&lt;")
            .replace(">", "&gt;")
            .replace('"', "&quot;")
            .replace("'", "&#39;")
        )

        # EXISTING row calculations - unchanged.
        unit_cost = int(price_row["unit_cost"])
        with_tax_each = int(price_row["with_tax"])
        without_gst_total = unit_cost * quantity
        with_tax_total = with_tax_each * quantity

        unit_cost_text = f"₹{unit_cost:,}"
        without_gst_text = f"₹{without_gst_total:,}"
        with_tax_text = f"₹{with_tax_total:,}"

        rows_html.append(
            "<tr>"
            f"<td>{serial_no}</td>"
            f"<td class='rts-price-component-name'>{safe_component}</td>"
            f"<td>{quantity}</td>"
            f"<td>{unit_cost_text}</td>"
            f"<td>{without_gst_text}</td>"
            f"<td>{with_tax_text}</td>"
            "</tr>"
        )
        serial_no += 1

    if rows_html:
        body_html = "".join(rows_html)
    else:
        body_html = (
            "<tr>"
            "<td colspan='6' class='rts-price-empty'>"
            "No component price details are available."
            "</td>"
            "</tr>"
        )

    # Adjustment description is display-only and does not alter tax_total.
    if current_mode == "fixed":
        adjustment_label = "Fixed Amount"
    elif current_mode == "percentage":
        adjustment_label = f"{current_value:g}% Reduction"
    else:
        adjustment_label = "No Adjustment"

    safe_page_title = (
        str(page_title or "Price Details")
        .replace("&", "&amp;")
        .replace("<", "&lt;")
        .replace(">", "&gt;")
        .replace('"', "&quot;")
        .replace("'", "&#39;")
    )

    price_html = f"""<div class="rts-price-page"><div class="rts-price-shell"><div class="rts-price-header"><div class="rts-price-title">{safe_page_title}</div><div class="rts-price-accent"></div></div><div class="rts-price-table-wrap"><table class="rts-price-table"><thead><tr><th>S.No</th><th>Component</th><th>Qty</th><th>Unit Cost</th><th>Without GST</th><th>With Tax</th></tr></thead><tbody>{body_html}</tbody></table></div><div class="rts-price-summary"><div class="rts-price-summary-item"><span>Total Price</span><strong>₹{unit_total:,}</strong></div><div class="rts-price-summary-item"><span>Total With Tax</span><strong>₹{tax_total:,}</strong></div></div></div></div>"""

    st.markdown(
        price_html,
        unsafe_allow_html=True,
    )

    if current_mode != "none":
        st.caption(
            f"Final price adjustment: {adjustment_label}. "
            f"Original With Tax remains ₹{int(tax_total):,}."
        )



def _price_details_export_font(size: int, bold: bool = False):
    try:
        return renderers_module.load_font(int(size), bool(bold))
    except Exception:
        try:
            return ImageFont.truetype("DejaVuSans-Bold.ttf" if bold else "DejaVuSans.ttf", int(size))
        except Exception:
            return ImageFont.load_default()


def _fit_price_export_text(
    draw: ImageDraw.ImageDraw,
    text: str,
    font,
    max_width: int,
) -> str:
    text = str(text or "")
    try:
        if draw.textbbox((0, 0), text, font=font)[2] <= max_width:
            return text
    except Exception:
        return text

    ellipsis = "..."
    shortened = text
    while shortened:
        shortened = shortened[:-1]
        candidate = shortened.rstrip() + ellipsis
        try:
            if draw.textbbox((0, 0), candidate, font=font)[2] <= max_width:
                return candidate
        except Exception:
            return candidate
    return ellipsis


@st.cache_data(max_entries=128, show_spinner=False)
def _price_details_export_png_cached(
    selected_names_key: tuple[str, ...],
    page_title: str,
) -> bytes:
    """Render one worksheet-specific Price Details page for PPT export only.

    Existing pricing values/calculations are reused exactly; this function changes
    no pricing logic or on-screen Price Details behavior.
    """
    names = [
        str(name or "").strip()
        for name in list(selected_names_key or ())
        if str(name or "").strip()
    ]
    counts = Counter(names)

    ordered_names: list[str] = []
    seen_names: set[str] = set()
    for name in names:
        if name not in seen_names:
            ordered_names.append(name)
            seen_names.add(name)

    unit_total, tax_total = calculate_selected_component_price(names)

    rows: list[tuple[str, int, int, int, int]] = []
    for component_name in ordered_names:
        quantity = max(0, int(counts.get(component_name, 0)))
        if quantity <= 0:
            continue

        price_source = APP_COMPONENT_PRICE_SOURCE.get(
            component_name,
            component_name,
        )
        price_row = COMPONENT_PRICE_LIST.get(price_source)
        if not price_row:
            continue

        display_name = PRICE_DETAILS_DISPLAY_NAME.get(price_source)
        if not display_name:
            continue

        unit_cost = int(price_row["unit_cost"])
        with_tax_each = int(price_row["with_tax"])
        rows.append(
            (
                str(display_name),
                quantity,
                unit_cost,
                unit_cost * quantity,
                with_tax_each * quantity,
            )
        )

    width, height = 1600, 900
    image = Image.new("RGB", (width, height), "#f6f9fd")
    draw = ImageDraw.Draw(image)

    # Existing Price Details visual language only; this is export rendering.
    shell_left, shell_top = 55, 45
    shell_right, shell_bottom = width - 55, height - 45
    draw.rounded_rectangle(
        (shell_left, shell_top, shell_right, shell_bottom),
        radius=26,
        fill="#ffffff",
        outline="#d8e4f2",
        width=2,
    )

    title_font = _price_details_export_font(34, True)
    header_font = _price_details_export_font(20, True)
    body_font = _price_details_export_font(18, False)
    body_bold = _price_details_export_font(18, True)
    total_label_font = _price_details_export_font(19, False)
    total_value_font = _price_details_export_font(24, True)

    title = str(page_title or "Price Details")
    title_box = draw.textbbox((0, 0), title, font=title_font)
    title_width = title_box[2] - title_box[0]
    draw.text(
        ((width - title_width) / 2, 76),
        title,
        font=title_font,
        fill="#0b3f82",
    )
    draw.rounded_rectangle(
        (width / 2 - 48, 124, width / 2 + 48, 130),
        radius=3,
        fill="#1187ba",
    )

    table_left = 90
    table_right = width - 90
    table_top = 165
    summary_height = 105
    table_bottom = shell_bottom - summary_height - 35
    table_width = table_right - table_left

    columns = [
        ("S.No", 0.07),
        ("Component", 0.35),
        ("Qty", 0.09),
        ("Unit Cost", 0.16),
        ("Without GST", 0.16),
        ("With Tax", 0.17),
    ]

    x_positions = [table_left]
    for _label, fraction in columns:
        x_positions.append(x_positions[-1] + int(table_width * fraction))
    x_positions[-1] = table_right

    row_count = max(1, len(rows))
    header_height = 48
    available_rows_height = max(160, table_bottom - table_top - header_height)
    row_height = max(25, min(44, available_rows_height // row_count))

    # Header.
    draw.rounded_rectangle(
        (table_left, table_top, table_right, table_top + header_height),
        radius=8,
        fill="#0b4f94",
    )

    for index, (label, _fraction) in enumerate(columns):
        x0, x1 = x_positions[index], x_positions[index + 1]
        box = draw.textbbox((0, 0), label, font=header_font)
        text_w = box[2] - box[0]
        text_h = box[3] - box[1]
        draw.text(
            (x0 + (x1 - x0 - text_w) / 2, table_top + (header_height - text_h) / 2 - 2),
            label,
            font=header_font,
            fill="#ffffff",
        )

    current_y = table_top + header_height

    if rows:
        for serial_no, row in enumerate(rows, start=1):
            if current_y + row_height > table_bottom + 1:
                break

            fill = "#ffffff" if serial_no % 2 else "#f7faff"
            draw.rectangle(
                (table_left, current_y, table_right, current_y + row_height),
                fill=fill,
                outline="#dfe8f2",
                width=1,
            )

            component, quantity, unit_cost, without_gst, with_tax = row
            values = [
                str(serial_no),
                component,
                str(quantity),
                f"₹{unit_cost:,}",
                f"₹{without_gst:,}",
                f"₹{with_tax:,}",
            ]

            for index, value in enumerate(values):
                x0, x1 = x_positions[index], x_positions[index + 1]
                cell_font = body_bold if index == 1 else body_font
                fitted = _fit_price_export_text(
                    draw,
                    value,
                    cell_font,
                    max(20, x1 - x0 - 20),
                )
                box = draw.textbbox((0, 0), fitted, font=cell_font)
                text_h = box[3] - box[1]

                if index == 1:
                    text_x = x0 + 10
                else:
                    text_w = box[2] - box[0]
                    text_x = x0 + (x1 - x0 - text_w) / 2

                draw.text(
                    (text_x, current_y + (row_height - text_h) / 2 - 1),
                    fitted,
                    font=cell_font,
                    fill="#183a63",
                )

            current_y += row_height
    else:
        empty_text = "No component price details are available."
        empty_font = _price_details_export_font(20, False)
        box = draw.textbbox((0, 0), empty_text, font=empty_font)
        draw.text(
            (
                (width - (box[2] - box[0])) / 2,
                table_top + header_height + 60,
            ),
            empty_text,
            font=empty_font,
            fill="#60748e",
        )

    # Summary cards: existing visible totals only.
    summary_top = shell_bottom - summary_height
    card_gap = 24
    card_width = 360
    total_cards_width = (card_width * 2) + card_gap
    start_x = (width - total_cards_width) // 2

    summary_items = [
        ("Total Price", unit_total),
        ("Total With Tax", tax_total),
    ]

    for index, (label, value) in enumerate(summary_items):
        x0 = start_x + index * (card_width + card_gap)
        x1 = x0 + card_width
        draw.rounded_rectangle(
            (x0, summary_top, x1, summary_top + 72),
            radius=14,
            fill="#f7fbff",
            outline="#cfe0f3",
            width=2,
        )
        draw.text(
            (x0 + 20, summary_top + 13),
            label,
            font=total_label_font,
            fill="#526b86",
        )
        value_text = f"₹{int(value):,}"
        value_box = draw.textbbox((0, 0), value_text, font=total_value_font)
        draw.text(
            (x1 - 20 - (value_box[2] - value_box[0]), summary_top + 36),
            value_text,
            font=total_value_font,
            fill="#0b4f94",
        )

    buffer = io.BytesIO()
    image.save(buffer, format="PNG", optimize=False, compress_level=3)
    return buffer.getvalue()


def _price_details_export_png_for_worksheet(
    worksheet_id: int,
    worksheet_number: int,
) -> bytes:
    components_for_price = _price_components_for_worksheet(
        int(worksheet_id)
    )
    return _price_details_export_png_cached(
        tuple(components_for_price),
        f"Price Details {int(worksheet_number)}",
    )


def _worksheet_flow_meter_asset(component_name: str) -> Path | None:
    """Resolve only the three uploaded flow-meter images for Worksheet rendering.

    This does not change renderer rules for any other component.  It searches the
    existing assets/component_images folder and supports normal or double file
    extensions while keeping each flow-meter type linked to its own image.
    """
    component_name = str(component_name or "").strip()
    aliases = {
        "Ultrasonic Flow Meter": (
            "ultrasonic flow meter",
            "ultrasonic_flow_meter",
            "ultrasonic-flow-meter",
            "ultrasonic flowmeter",
            "ultrasonicflowmeter",
        ),
        "Flush Flow Meter": (
            "flush flow meter",
            "flush_flow_meter",
            "flush-flow-meter",
            "flush flowmeter",
            "flushflowmeter",
        ),
        "Electromagnetic Flow Meter": (
            "electromagnetic flow meter",
            "electromagnetic_flow_meter",
            "electromagnetic-flow-meter",
            "electromagnetic flowmeter",
            "electromagneticflowmeter",
            "magnetic flow meter",
            "magnetic_flow_meter",
        ),
    }

    accepted_aliases = aliases.get(component_name)
    if not accepted_aliases:
        return None

    image_dir = ROOT_DIR / "assets" / "component_images"
    if not image_dir.is_dir():
        return None

    def normalize_name(path: Path) -> str:
        name = path.name.lower().strip()
        # Remove one or more common image extensions, including *.png.png.
        while True:
            stem, suffix = os.path.splitext(name)
            if suffix.lower() in {".png", ".jpg", ".jpeg", ".webp", ".bmp"}:
                name = stem
            else:
                break
        return re.sub(r"[^a-z0-9]+", " ", name).strip()

    normalized_aliases = {
        re.sub(r"[^a-z0-9]+", " ", alias.lower()).strip()
        for alias in accepted_aliases
    }

    valid_suffixes = {".png", ".jpg", ".jpeg", ".webp", ".bmp"}
    for candidate in sorted(image_dir.iterdir()):
        if not candidate.is_file():
            continue

        # A double extension such as .png.png still has a valid final suffix.
        if candidate.suffix.lower() not in valid_suffixes:
            continue

        if normalize_name(candidate) in normalized_aliases:
            return candidate

    return None


@st.cache_data(max_entries=256, show_spinner=False)
def _worksheet_component_sprite_b64(
    path_text: str,
    mtime_ns: int,
    file_size: int,
) -> str:
    """Return a fully visible Worksheet sprite with file-version caching.

    Keep the original component image unchanged, but add a small transparent
    safety margin around it before it is placed inside the existing component
    box. This preserves the original component image scale/appearance while
    keeping component position, box size, routing, arrows and interactions
    unchanged.
    """
    del mtime_ns, file_size
    with Image.open(path_text) as source_asset:
        asset_rgba = source_asset.convert("RGBA")
        alpha = asset_rgba.getchannel("A")
        bbox = alpha.getbbox()
        if bbox:
            asset_rgba = asset_rgba.crop(bbox)

        width, height = asset_rgba.size
        if width > 0 and height > 0:
            padding = max(4, int(round(min(width, height) * 0.03)))
            padded_asset = Image.new(
                "RGBA",
                (width + (padding * 2), height + (padding * 2)),
                (255, 255, 255, 0),
            )
            padded_asset.alpha_composite(asset_rgba, (padding, padding))
            asset_rgba = padded_asset

        sprite_buffer = io.BytesIO()
        asset_rgba.save(sprite_buffer, format="PNG")
        return base64.b64encode(sprite_buffer.getvalue()).decode("ascii")

@st.cache_data(max_entries=512, show_spinner=False)
def _worksheet_remove_embedded_component_label(image_b64: str) -> str:
    """Remove only the later/renderer blue caption strip from a sprite.

    The original Worksheet component-name label is rendered separately by the
    frontend SVG layer. This helper preserves the sprite dimensions, component
    image, box, position and interaction geometry while making only a detected
    renderer-style blue caption strip transparent.
    """
    encoded = str(image_b64 or "").strip()
    if not encoded:
        return encoded

    try:
        raw = base64.b64decode(encoded, validate=True)
        with Image.open(io.BytesIO(raw)) as source_image:
            image = source_image.convert("RGBA")

        width, height = image.size
        if width < 12 or height < 12:
            return encoded

        pixels = image.load()
        scan_start = max(0, int(height * 0.45))
        minimum_blue_ratio = 0.42
        minimum_run = max(2, int(round(height * 0.025)))
        run_start = None
        run_length = 0
        label_top = None

        for y in range(scan_start, height):
            blue_pixels = 0
            for x in range(width):
                red, green, blue, alpha = pixels[x, y]
                if (
                    alpha >= 96
                    and blue >= 145
                    and red <= 95
                    and 35 <= green <= 175
                    and blue >= red + 80
                    and blue >= green + 45
                ):
                    blue_pixels += 1

            if blue_pixels / max(1, width) >= minimum_blue_ratio:
                if run_start is None:
                    run_start = y
                    run_length = 1
                else:
                    run_length += 1
                if run_length >= minimum_run:
                    label_top = run_start
                    break
            else:
                run_start = None
                run_length = 0

        if label_top is None:
            return encoded

        label_top = max(
            scan_start,
            label_top - max(1, int(round(height * 0.018))),
        )
        ImageDraw.Draw(image).rectangle(
            (0, label_top, width, height),
            fill=(0, 0, 0, 0),
        )

        buffer = io.BytesIO()
        image.save(buffer, format="PNG", optimize=False, compress_level=3)
        return base64.b64encode(buffer.getvalue()).decode("ascii")
    except Exception:
        return encoded




@st.cache_data(max_entries=512, show_spinner=False)
def _worksheet_remove_component_border_box(image_b64: str) -> str:
    """Remove only the renderer's surrounding component card/border.

    This runs only when the pale renderer card border is detected near the
    outside of a sprite. It flood-clears only card/background pixels connected
    to an outer edge, leaving component artwork and all live labels untouched.
    """
    encoded = str(image_b64 or "").strip()
    if not encoded:
        return encoded

    try:
        raw = base64.b64decode(encoded, validate=True)
        with Image.open(io.BytesIO(raw)) as source_image:
            image = source_image.convert("RGBA")

        width, height = image.size
        if width < 12 or height < 12:
            return encoded

        pixels = image.load()
        ring = max(2, min(18, int(round(min(width, height) * 0.08))))
        border_hits = 0
        ring_samples = 0

        def _is_renderer_border(r: int, g: int, b: int, a: int) -> bool:
            return (
                a >= 40
                and 175 <= r <= 235
                and 195 <= g <= 245
                and 220 <= b <= 255
                and b >= r + 10
                and b >= g + 3
            )

        for y in range(height):
            for x in range(width):
                if not (
                    x < ring
                    or x >= width - ring
                    or y < ring
                    or y >= height - ring
                ):
                    continue

                ring_samples += 1
                r, g, b, a = pixels[x, y]
                if _is_renderer_border(r, g, b, a):
                    border_hits += 1

        minimum_hits = max(10, int(round(ring_samples * 0.0015)))
        if border_hits < minimum_hits:
            return encoded

        def _is_outer_card_pixel(r: int, g: int, b: int, a: int) -> bool:
            if a <= 6:
                return True
            if _is_renderer_border(r, g, b, a):
                return True
            if r >= 238 and g >= 238 and b >= 238:
                return True
            if (
                205 <= r <= 245
                and 215 <= g <= 250
                and 228 <= b <= 255
                and b >= r + 3
            ):
                return True
            return False

        visited = bytearray(width * height)
        stack: list[tuple[int, int]] = []

        def _queue_if_background(x: int, y: int) -> None:
            index = y * width + x
            if visited[index]:
                return

            r, g, b, a = pixels[x, y]
            if not _is_outer_card_pixel(r, g, b, a):
                return

            visited[index] = 1
            stack.append((x, y))

        for x in range(width):
            _queue_if_background(x, 0)
            _queue_if_background(x, height - 1)

        for y in range(height):
            _queue_if_background(0, y)
            _queue_if_background(width - 1, y)

        while stack:
            x, y = stack.pop()
            pixels[x, y] = (0, 0, 0, 0)

            if x > 0:
                _queue_if_background(x - 1, y)
            if x + 1 < width:
                _queue_if_background(x + 1, y)
            if y > 0:
                _queue_if_background(x, y - 1)
            if y + 1 < height:
                _queue_if_background(x, y + 1)

        buffer = io.BytesIO()
        image.save(
            buffer,
            format="PNG",
            optimize=False,
            compress_level=3,
        )
        return base64.b64encode(buffer.getvalue()).decode("ascii")

    except Exception:
        return encoded


_CATALOG_NAMES_LONGEST_FIRST = tuple(
    sorted(
        (item.name for item in COMPONENT_CATALOG),
        key=len,
        reverse=True,
    )
)
_CATALOG_NAME_SET = frozenset(_CATALOG_NAMES_LONGEST_FIRST)


@lru_cache(maxsize=512)
def _component_name_from_label(label: str) -> str | None:
    """Resolve a catalog component name once per rendered label text."""
    label = str(label or "").strip()
    if not label:
        return None
    for name in _CATALOG_NAMES_LONGEST_FIRST:
        if label == name or label.startswith(f"{name} "):
            return name
    return None


def _component_name_from_diagram_node(node) -> str | None:
    """Resolve a rendered selection-mode node back to its catalog component name.

    Repeated selection-mode nodes are labelled ``Component 1``, ``Component 2``,
    etc.  Longest-name-first matching avoids prefix collisions while keeping the
    existing diagram/model format unchanged.
    """
    return _component_name_from_label(
        str(getattr(node, "label", "") or "")
    )



def _worksheet_component_count_adjustments_key(worksheet_id: int) -> str:
    """Session key for component +/- changes made directly on the Worksheet."""
    return f"_worksheet_component_count_adjustments_{int(worksheet_id)}"


def _worksheet_component_count_adjustments(worksheet_id: int) -> dict[str, int]:
    """Return only valid, non-zero Worksheet component count adjustments."""
    raw = st.session_state.get(
        _worksheet_component_count_adjustments_key(worksheet_id),
        {},
    ) or {}

    result: dict[str, int] = {}
    if not isinstance(raw, dict):
        return result

    for raw_name, raw_delta in raw.items():
        name = str(raw_name or "").strip()
        if name not in _CATALOG_NAME_SET:
            continue
        try:
            delta = int(raw_delta)
        except (TypeError, ValueError):
            continue
        if delta:
            result[name] = delta

    return result


def _change_worksheet_component_count_adjustment(
    worksheet_id: int,
    component_name: str,
    delta: int,
) -> None:
    """Change only the Worksheet +/- count override for one component type."""
    component_name = str(component_name or "").strip()
    if component_name not in _CATALOG_NAME_SET:
        return

    adjustments = _worksheet_component_count_adjustments(worksheet_id)
    next_value = int(adjustments.get(component_name, 0)) + int(delta)

    if next_value:
        adjustments[component_name] = next_value
    else:
        adjustments.pop(component_name, None)

    st.session_state[
        _worksheet_component_count_adjustments_key(worksheet_id)
    ] = adjustments


def _apply_worksheet_component_count_adjustments(
    worksheet_id: int,
    component_names: list[str],
) -> tuple[list[str], dict[str, int]]:
    """Apply only user-requested Worksheet +/- changes to generated components.

    Existing automatic component rules run first. This helper then applies the
    user's explicit hover-icon add/delete count, so Streamlit reruns cannot undo
    that direct Worksheet action.
    """
    adjusted = list(component_names or [])
    adjustments = _worksheet_component_count_adjustments(worksheet_id)

    for component_name, delta in adjustments.items():
        if delta > 0:
            adjusted.extend([component_name] * int(delta))
            continue

        remove_count = min(
            abs(int(delta)),
            adjusted.count(component_name),
        )
        for _ in range(remove_count):
            # Remove the final matching occurrence. Existing builder behavior
            # already re-numbers repeated instances after a quantity change.
            for index in range(len(adjusted) - 1, -1, -1):
                if adjusted[index] == component_name:
                    adjusted.pop(index)
                    break

    return adjusted, adjustments


def _add_component_instance_from_worksheet(
    active_worksheet_id: int,
    component_name: str,
) -> bool:
    """Handle the hover '+' action without changing any component rules."""
    component_name = str(component_name or "").strip()
    if component_name not in _CATALOG_NAME_SET:
        return False

    if not _duplicate_component_instance(active_worksheet_id, component_name):
        return False

    if component_name in set(MANUAL_BASE_COMPONENTS):
        # The compact quantity widget has already retained its previous widget
        # value. Rotate only that widget generation so the just-added Sump /
        # Bore Well / OHT quantity is not immediately written back to the old
        # value during this Streamlit rerun.
        compact_generation_key = (
            f"component_compact_generation_{int(active_worksheet_id)}"
        )
        st.session_state[compact_generation_key] = int(
            st.session_state.get(compact_generation_key, 0) or 0
        ) + 1
    else:
        # Non-manual components can be regenerated automatically from the same
        # existing trained/wireless rules. Record only the user's extra instance
        # so the automatic baseline remains completely unchanged.
        _change_worksheet_component_count_adjustment(
            active_worksheet_id,
            component_name,
            +1,
        )

    # Force only the existing diagram generation gate to see this Worksheet
    # component change even when the compact manual selection itself is unchanged.
    st.session_state.pop("processed_hash", None)
    persist_active_worksheet_state()
    return True


def _delete_component_instance_from_worksheet(
    active_worksheet_id: int,
    component_name: str,
    instance_id: str,
    diagram,
) -> bool:
    """Handle the hover Delete action and keep it stable across reruns."""
    component_name = str(component_name or "").strip()
    instance_id = str(instance_id or "").strip()

    if (
        component_name not in _CATALOG_NAME_SET
        or not instance_id
        or diagram is None
    ):
        return False

    # The compact left panel intentionally rebuilds selected_components from
    # Sump/Bore/OHT plus explicit requirements. On a later rerun an automatic
    # visible component can therefore be present in the diagram but absent from
    # selected_components. Rehydrate only the current rendered component names
    # for this delete operation so the existing exact-instance delete function
    # can perform its normal connection/settings cleanup.
    selected_now = list(st.session_state.get("selected_components", []) or [])
    if component_name not in selected_now:
        diagram_selected = []
        for node in (getattr(diagram, "nodes", []) or []):
            resolved_name = _component_name_from_diagram_node(node)
            if resolved_name:
                diagram_selected.append(resolved_name)

        if component_name in diagram_selected:
            st.session_state["selected_components"] = diagram_selected

    before_requirements = set(
        _sanitize_requirement_components(
            st.session_state.get("selected_requirement_components", []) or []
        )
    )

    if not _delete_component_instance(
        active_worksheet_id,
        component_name,
        instance_id,
        diagram,
    ):
        return False

    after_requirements = set(
        _sanitize_requirement_components(
            st.session_state.get("selected_requirement_components", []) or []
        )
    )

    if component_name not in set(MANUAL_BASE_COMPONENTS):
        # If deleting the last explicitly requested 2A component removed that
        # requirement itself, the existing requirement removal is sufficient.
        # Otherwise record one direct Worksheet deletion so trained/wireless
        # auto-generation cannot immediately put the clicked component back.
        requirement_was_removed = (
            component_name in before_requirements
            and component_name not in after_requirements
        )
        if not requirement_was_removed:
            _change_worksheet_component_count_adjustment(
                active_worksheet_id,
                component_name,
                -1,
            )

    st.session_state.pop("processed_hash", None)
    persist_active_worksheet_state()
    return True


def _duplicate_component_instance(active_worksheet_id: int, component_name: str) -> bool:
    """Append exactly one independent instance to the active worksheet.

    This is deliberately state-only: it does not navigate, replace the worksheet,
    open an editor, or alter the renderer/connection rules.  The existing selected
    component list remains the single source of truth, so the normal diagram and
    2A builders automatically receive the new instance on the next rerun.
    """
    component_name = str(component_name or "").strip()
    if component_name not in _CATALOG_NAME_SET:
        return False

    selected = list(st.session_state.get("selected_components", []) or [])

    # Preserve all already-selected connection rows and their transport settings.
    # component_catalog.py uses stable numbered instance IDs from the first instance
    # onward (for example sump_1, sump_2, ...), therefore appending an instance does
    # not change the identity of any existing component or existing connection.
    old_required_ids = list(st.session_state.get("selected_connections", []) or [])
    old_transport = dict(st.session_state.get("connection_transport_settings", {}) or {})

    selected.append(component_name)
    st.session_state["selected_components"] = selected
    st.session_state["_manual_component_selection_changed"] = True

    new_options = allowed_connection_options(selected)
    new_option_ids = {option.id for option in new_options}
    st.session_state["selected_connections"] = [
        connection_id
        for connection_id in old_required_ids
        if connection_id in new_option_ids
    ]
    st.session_state["connection_transport_settings"] = {
        connection_id: _sanitize_connection_transport_setting(config)
        for connection_id, config in old_transport.items()
        if connection_id in new_option_ids
    }

    # st.data_editor retains prior widget state. Rotate only the component editor
    # key so Qty immediately reflects the extra instance while every other widget
    # and worksheet state remains untouched.
    generation_key = f"component_editor_generation_{active_worksheet_id}"
    st.session_state[generation_key] = int(st.session_state.get(generation_key, 0)) + 1

    # Performance-only flag:
    # Adding one component is a normal Worksheet action. The diagram itself must
    # still regenerate, but the expensive combined-PPT rebuild is deferred until
    # the user explicitly requests PPT Edit/Download.
    st.session_state[
        f"_fast_worksheet_component_change_{int(active_worksheet_id)}"
    ] = True

    persist_active_worksheet_state()
    return True


def _add_direct_component_instance(
    active_worksheet_id: int,
    component_name: str,
) -> None:
    """Add one instance from the compact component button without changing its logic."""
    if not _duplicate_component_instance(active_worksheet_id, component_name):
        return

    # Rotate only the compact quantity widgets so their defaults immediately
    # reflect the newly added instance. This is the same refresh previously
    # performed inside the direct-button click branch.
    compact_generation_key = f"component_compact_generation_{active_worksheet_id}"
    st.session_state[compact_generation_key] = int(
        st.session_state.get(compact_generation_key, 0) or 0
    ) + 1


def _decrement_direct_component_instance(
    active_worksheet_id: int,
    component_name: str,
) -> None:
    """Remove only the last instance of one manual base component."""
    component_name = str(component_name or "").strip()
    selected = list(st.session_state.get("selected_components", []) or [])
    matching_positions = [
        index for index, name in enumerate(selected) if name == component_name
    ]
    if not component_name or not matching_positions:
        return

    selected.pop(matching_positions[-1])
    st.session_state["selected_components"] = selected
    st.session_state["_manual_component_selection_changed"] = True

    valid_options = allowed_connection_options(selected)
    valid_connection_ids = {option.id for option in valid_options}
    st.session_state["selected_connections"] = [
        connection_id
        for connection_id in list(st.session_state.get("selected_connections", []) or [])
        if connection_id in valid_connection_ids
    ]
    st.session_state["connection_transport_settings"] = {
        connection_id: _sanitize_connection_transport_setting(config)
        for connection_id, config in dict(
            st.session_state.get("connection_transport_settings", {}) or {}
        ).items()
        if connection_id in valid_connection_ids
    }

    flow_data = inline_flow_meter_placement_options(selected)
    valid_meter_ids = {
        str(item.get("id", "") or "")
        for item in list(flow_data.get("meters", []) or [])
        if str(item.get("id", "") or "")
    }
    st.session_state["inline_flow_meter_settings"] = {
        meter_id: _sanitize_inline_flow_meter_setting(config)
        for meter_id, config in dict(
            st.session_state.get("inline_flow_meter_settings", {}) or {}
        ).items()
        if meter_id in valid_meter_ids
    }

    compact_generation_key = f"component_compact_generation_{active_worksheet_id}"
    st.session_state[compact_generation_key] = int(
        st.session_state.get(compact_generation_key, 0) or 0
    ) + 1
    connection_generation_key = f"connection_picker_generation_{active_worksheet_id}"
    st.session_state[connection_generation_key] = int(
        st.session_state.get(connection_generation_key, 0) or 0
    ) + 1
    st.session_state[f"_fast_worksheet_component_change_{int(active_worksheet_id)}"] = True
    persist_active_worksheet_state()


def _remove_compact_selected_connection(
    active_worksheet_id: int,
    connection_id: str,
) -> None:
    """Remove one connection from the existing selected-connections list."""
    connection_id = str(connection_id or "").strip()
    if not connection_id:
        return
    selected_connections = list(st.session_state.get("selected_connections", []) or [])
    updated_connections = [
        item for item in selected_connections if str(item) != connection_id
    ]
    if updated_connections == selected_connections:
        return
    st.session_state["selected_connections"] = updated_connections
    generation_key = f"connection_picker_generation_{active_worksheet_id}"
    st.session_state[generation_key] = int(
        st.session_state.get(generation_key, 0) or 0
    ) + 1
    st.session_state[f"_fast_worksheet_component_change_{int(active_worksheet_id)}"] = True
    persist_active_worksheet_state()


def _remove_direct_component_type(
    active_worksheet_id: int,
    component_name: str,
) -> None:
    """Remove one selected manual component type from its compact button.

    The compact button represents the component type while the existing Qty
    control represents its instance count, so removing from the button clears all
    instances of that type. Existing relationship, routing and renderer rules are
    not changed; only now-invalid saved connection/flow settings are discarded.
    """
    component_name = str(component_name or "").strip()
    selected = list(st.session_state.get("selected_components", []) or [])
    if not component_name or component_name not in selected:
        return

    selected = [name for name in selected if name != component_name]
    st.session_state["selected_components"] = selected
    st.session_state["_manual_component_selection_changed"] = True

    # Keep the existing requirement list consistent if a component type is ever
    # shared with the requirement selector in a future catalog revision.
    requirement_components = _sanitize_requirement_components(
        st.session_state.get("selected_requirement_components", []) or []
    )
    if component_name in requirement_components:
        st.session_state["selected_requirement_components"] = [
            name for name in requirement_components if name != component_name
        ]

    # Preserve every still-valid connection and transport choice exactly as the
    # existing component-delete path does.
    valid_options = allowed_connection_options(selected)
    valid_connection_ids = {option.id for option in valid_options}

    st.session_state["selected_connections"] = [
        connection_id
        for connection_id in list(
            st.session_state.get("selected_connections", []) or []
        )
        if connection_id in valid_connection_ids
    ]
    st.session_state["connection_transport_settings"] = {
        connection_id: _sanitize_connection_transport_setting(config)
        for connection_id, config in dict(
            st.session_state.get("connection_transport_settings", {}) or {}
        ).items()
        if connection_id in valid_connection_ids
    }

    flow_data = inline_flow_meter_placement_options(selected)
    valid_meter_ids = {
        str(item.get("id", "") or "")
        for item in list(flow_data.get("meters", []) or [])
        if str(item.get("id", "") or "")
    }
    st.session_state["inline_flow_meter_settings"] = {
        meter_id: _sanitize_inline_flow_meter_setting(config)
        for meter_id, config in dict(
            st.session_state.get("inline_flow_meter_settings", {}) or {}
        ).items()
        if meter_id in valid_meter_ids
    }

    # Refresh only the compact selector and 2A widget keys affected by this
    # removal. No other UI/session keys are touched.
    compact_generation_key = f"component_compact_generation_{active_worksheet_id}"
    st.session_state[compact_generation_key] = int(
        st.session_state.get(compact_generation_key, 0) or 0
    ) + 1

    connection_generation_key = (
        f"connection_picker_generation_{active_worksheet_id}"
    )
    st.session_state[connection_generation_key] = int(
        st.session_state.get(connection_generation_key, 0) or 0
    ) + 1

    st.session_state.pop(
        f"pending_component_connection_source_{active_worksheet_id}",
        None,
    )

    # Preserve the existing fast Worksheet regeneration/PPT deferral behavior.
    st.session_state[
        f"_fast_worksheet_component_change_{int(active_worksheet_id)}"
    ] = True

    persist_active_worksheet_state()


def _delete_component_instance(
    active_worksheet_id: int,
    component_name: str,
    instance_id: str,
    diagram,
) -> bool:
    """Delete exactly one rendered component instance from the active worksheet.

    The selected component list remains the source of truth.  The rendered node ID
    is used only to identify which occurrence of a repeated component (for example
    Sump 1 vs Sump 2) was clicked.  Other component instances are preserved.
    """
    component_name = str(component_name or "").strip()
    instance_id = str(instance_id or "").strip()
    selected = list(st.session_state.get("selected_components", []) or [])

    if not component_name or component_name not in selected:
        return False

    # Resolve the clicked rendered node to the matching occurrence of this
    # component type.  Diagram node order follows the same instance order used by
    # the component builder, so deleting Sump 2 removes only the second Sump.
    same_component_node_ids = []
    for node in (getattr(diagram, "nodes", []) or []):
        if _component_name_from_diagram_node(node) == component_name:
            same_component_node_ids.append(str(getattr(node, "id", "") or ""))

    occurrence_index = 0
    if instance_id in same_component_node_ids:
        occurrence_index = same_component_node_ids.index(instance_id)

    selected_positions = [
        index for index, name in enumerate(selected) if name == component_name
    ]
    if not selected_positions:
        return False

    if occurrence_index >= len(selected_positions):
        occurrence_index = len(selected_positions) - 1

    selected.pop(selected_positions[occurrence_index])
    st.session_state["selected_components"] = selected

    # If this component came from the default 2A requirement/control list, remove
    # that requirement only when its final instance is deleted.  This prevents a
    # deleted VCT/flow-meter/valve/etc. from being silently re-added on the next
    # Streamlit rerun.
    requirement_components = _sanitize_requirement_components(
        st.session_state.get("selected_requirement_components", []) or []
    )
    if component_name in requirement_components and component_name not in selected:
        requirement_components = [
            name for name in requirement_components if name != component_name
        ]
        st.session_state["selected_requirement_components"] = requirement_components

    # Keep only connection intents that are still valid after the exact component
    # instance is removed. This prevents orphaned lines while leaving unrelated
    # component connections untouched.
    valid_options = allowed_connection_options(selected)
    valid_connection_ids = {option.id for option in valid_options}

    st.session_state["selected_connections"] = [
        connection_id
        for connection_id in list(
            st.session_state.get("selected_connections", []) or []
        )
        if connection_id in valid_connection_ids
    ]

    st.session_state["connection_transport_settings"] = {
        connection_id: _sanitize_connection_transport_setting(config)
        for connection_id, config in dict(
            st.session_state.get("connection_transport_settings", {}) or {}
        ).items()
        if connection_id in valid_connection_ids
    }

    # Remove only stale inline-flow-meter settings if the deleted instance changes
    # the available meter instances.
    flow_data = inline_flow_meter_placement_options(selected)
    valid_meter_ids = {
        str(item.get("id", "") or "")
        for item in list(flow_data.get("meters", []) or [])
        if str(item.get("id", "") or "")
    }
    st.session_state["inline_flow_meter_settings"] = {
        meter_id: _sanitize_inline_flow_meter_setting(config)
        for meter_id, config in dict(
            st.session_state.get("inline_flow_meter_settings", {}) or {}
        ).items()
        if meter_id in valid_meter_ids
    }

    # The compact left-side component widgets were already rendered during this
    # Streamlit run. Rotate only their keys on the next rerun so their defaults
    # reflect the new exact quantity instead of restoring the previous widget value.
    compact_generation_key = f"component_compact_generation_{active_worksheet_id}"
    st.session_state[compact_generation_key] = int(
        st.session_state.get(compact_generation_key, 0) or 0
    ) + 1

    # The connection picker must likewise rebuild from the remaining exact
    # instances if deleting this component removed any connection candidates.
    connection_generation_key = (
        f"connection_picker_generation_{active_worksheet_id}"
    )
    st.session_state[connection_generation_key] = int(
        st.session_state.get(connection_generation_key, 0) or 0
    ) + 1

    pending_key = f"pending_component_connection_source_{active_worksheet_id}"
    if str(st.session_state.get(pending_key, "") or "") == instance_id:
        st.session_state.pop(pending_key, None)

    # Performance-only flag:
    # Deleting one component is a normal Worksheet action. Keep the existing
    # topology cleanup exactly as above, but defer the expensive PPT rebuild
    # until PPT is explicitly requested.
    st.session_state[
        f"_fast_worksheet_component_change_{int(active_worksheet_id)}"
    ] = True

    persist_active_worksheet_state()
    return True


def _apply_connection_delete_state(worksheet_id: int, edge_id: str, diagram) -> bool:
    """Remove one connection before any same-rerun diagram generation occurs."""
    edge_id = str(edge_id or "").strip()
    if not edge_id or diagram is None or not hasattr(diagram, "edges"):
        return False

    valid_edge_ids = {
        str(getattr(edge, "id", "") or "")
        for edge in (getattr(diagram, "edges", []) or [])
    }
    if edge_id not in valid_edge_ids:
        return False

    diagram.edges = [
        edge
        for edge in list(getattr(diagram, "edges", []) or [])
        if str(getattr(edge, "id", "") or "") != edge_id
    ]

    option_id = edge_id.removeprefix("edge__")
    st.session_state["selected_connections"] = [
        connection_id
        for connection_id in list(
            st.session_state.get("selected_connections", []) or []
        )
        if str(connection_id) not in {edge_id, option_id}
    ]

    deleted_ids = {
        str(value)
        for value in st.session_state.get(
            _deleted_connection_ids_key(worksheet_id), []
        )
        or []
    }
    deleted_ids.update({edge_id, option_id})
    st.session_state[_deleted_connection_ids_key(worksheet_id)] = sorted(
        deleted_ids
    )

    transport_settings = dict(
        st.session_state.get("connection_transport_settings", {}) or {}
    )
    transport_settings.pop(option_id, None)
    transport_settings.pop(edge_id, None)
    st.session_state["connection_transport_settings"] = transport_settings

    overrides_key = _manual_connection_overrides_key(worksheet_id)
    route_overrides = dict(st.session_state.get(overrides_key, {}) or {})
    route_overrides.pop(edge_id, None)
    st.session_state[overrides_key] = route_overrides
    st.session_state.pop(_manual_edit_png_key(worksheet_id), None)
    persist_active_worksheet_state()
    _mark_worksheet_render_sync_pending(worksheet_id)
    _mark_ppt_sync_pending(worksheet_id)
    return True


def _consume_pending_normal_surface_component_action(worksheet_id: int) -> bool:
    """Apply Worksheet +/- events before the expensive page/render pipeline.

    The keyed custom-component value is available in widget/session state at the
    start of the rerun triggered by the component. Processing Add/Delete here
    lets the existing controls, connection rules and generation pipeline see the
    new component state in this SAME run.

    This removes the previous second full rerun without changing component,
    connection, routing, arrow, layout or automatic-requirement rules.
    """
    worksheet_id = int(worksheet_id)
    surface_key = f"diagram_normal_surface_{worksheet_id}_inline"
    event = st.session_state.get(surface_key)
    if not isinstance(event, dict):
        return False

    event_type = str(event.get("type", "") or "")
    if event_type not in {
        "component_add",
        "component_delete",
        "connection_delete",
    }:
        return False

    event_id = str(event.get("event_id", "") or "")
    if not event_id:
        return False

    last_key = f"normal_surface_last_event_{worksheet_id}_inline"
    if st.session_state.get(last_key) == event_id:
        return False

    # Mark before the normal Worksheet component is mounted later in this run,
    # so the same event is not processed again at the original call site.
    st.session_state[last_key] = event_id

    if event_type == "connection_delete":
        return _apply_connection_delete_state(
            worksheet_id,
            str(event.get("edge_id", "") or ""),
            st.session_state.get("diagram"),
        )

    if event_type == "component_add":
        component_name = str(event.get("component", "") or "").strip()
        return bool(
            component_name
            and _add_component_instance_from_worksheet(
                worksheet_id,
                component_name,
            )
        )

    component_name = str(event.get("component", "") or "").strip()
    instance_id = str(event.get("instance_id", "") or "").strip()
    diagram = st.session_state.get("diagram")
    return bool(
        component_name
        and instance_id
        and diagram is not None
        and _delete_component_instance_from_worksheet(
            worksheet_id,
            component_name,
            instance_id,
            diagram,
        )
    )


def _connection_history_key(worksheet_id: int) -> str:
    return f"manual_connection_history_{int(worksheet_id)}"


def _connection_history_index_key(worksheet_id: int) -> str:
    return f"manual_connection_history_index_{int(worksheet_id)}"


def _clone_connection_overrides(value) -> dict:
    # The override structure contains only JSON-safe lists/dicts/numbers/strings.
    return json.loads(json.dumps(dict(value or {})))


def _ensure_connection_history(worksheet_id: int, overrides: dict) -> None:
    history_key = _connection_history_key(worksheet_id)
    index_key = _connection_history_index_key(worksheet_id)
    history = st.session_state.get(history_key)
    if not isinstance(history, list) or not history:
        st.session_state[history_key] = [_clone_connection_overrides(overrides)]
        st.session_state[index_key] = 0


def _push_connection_history(worksheet_id: int, overrides: dict) -> None:
    history_key = _connection_history_key(worksheet_id)
    index_key = _connection_history_index_key(worksheet_id)
    _ensure_connection_history(worksheet_id, st.session_state.get(_manual_connection_overrides_key(worksheet_id), {}) or {})
    history = list(st.session_state.get(history_key, []) or [])
    index = int(st.session_state.get(index_key, len(history) - 1))
    history = history[: index + 1]
    snapshot = _clone_connection_overrides(overrides)
    if not history or history[-1] != snapshot:
        history.append(snapshot)
    # Bound memory while still providing a useful editing history.
    if len(history) > 100:
        history = history[-100:]
    st.session_state[history_key] = history
    st.session_state[index_key] = len(history) - 1


def _connection_history_step(worksheet_id: int, delta: int) -> dict | None:
    history_key = _connection_history_key(worksheet_id)
    index_key = _connection_history_index_key(worksheet_id)
    history = list(st.session_state.get(history_key, []) or [])
    if not history:
        return None
    index = int(st.session_state.get(index_key, len(history) - 1))
    new_index = max(0, min(len(history) - 1, index + int(delta)))
    if new_index == index:
        return None
    st.session_state[index_key] = new_index
    return _clone_connection_overrides(history[new_index])


def _commit_connection_visual_state(diagram, worksheet_id: int, overrides: dict) -> None:
    """Render and persist only the visual connection override state."""
    overrides = _clone_connection_overrides(overrides)
    st.session_state[_manual_connection_overrides_key(worksheet_id)] = overrides

    final_png = create_preview_png(
        diagram=diagram,
        assets_dir=ASSETS_DIR,
        manual_route_overrides=overrides,
        manual_component_overrides=st.session_state.get(
            _manual_component_overrides_key(worksheet_id), {}
        ) or {},
    )
    st.session_state["preview_png"] = final_png
    st.session_state["pdf_bytes"] = png_to_pdf(final_png)
    st.session_state.pop(_manual_edit_png_key(worksheet_id), None)
    if "worksheets" in st.session_state:
        persist_active_worksheet_state()
    add_diagram_to_ppt_session(int(worksheet_id), final_png)




def _editor_history_key(worksheet_id: int) -> str:
    return f"manual_editor_history_{int(worksheet_id)}"


def _editor_history_index_key(worksheet_id: int) -> str:
    return f"manual_editor_history_index_{int(worksheet_id)}"


def _editor_snapshot(worksheet_id: int, routes: dict | None = None, components: dict | None = None) -> dict:
    if routes is None:
        routes = st.session_state.get(_manual_connection_overrides_key(worksheet_id), {}) or {}
    if components is None:
        components = st.session_state.get(_manual_component_overrides_key(worksheet_id), {}) or {}
    return {
        "routes": json.loads(json.dumps(dict(routes or {}))),
        "components": json.loads(json.dumps(dict(components or {}))),
    }


def _ensure_editor_history(worksheet_id: int) -> None:
    hk = _editor_history_key(worksheet_id)
    ik = _editor_history_index_key(worksheet_id)
    history = st.session_state.get(hk)
    if not isinstance(history, list) or not history:
        st.session_state[hk] = [_editor_snapshot(worksheet_id)]
        st.session_state[ik] = 0


def _push_editor_history(worksheet_id: int, routes: dict, components: dict) -> None:
    _ensure_editor_history(worksheet_id)
    hk = _editor_history_key(worksheet_id)
    ik = _editor_history_index_key(worksheet_id)
    history = list(st.session_state.get(hk, []) or [])
    index = int(st.session_state.get(ik, len(history) - 1))
    history = history[: index + 1]
    snap = _editor_snapshot(worksheet_id, routes, components)
    if not history or history[-1] != snap:
        history.append(snap)
    if len(history) > 100:
        history = history[-100:]
    st.session_state[hk] = history
    st.session_state[ik] = len(history) - 1


def _step_editor_history(worksheet_id: int, delta: int) -> dict | None:
    _ensure_editor_history(worksheet_id)
    hk = _editor_history_key(worksheet_id)
    ik = _editor_history_index_key(worksheet_id)
    history = list(st.session_state.get(hk, []) or [])
    index = int(st.session_state.get(ik, len(history) - 1))
    new_index = max(0, min(len(history) - 1, index + int(delta)))
    if new_index == index:
        return None
    st.session_state[ik] = new_index
    return json.loads(json.dumps(history[new_index]))


def _commit_editor_visual_state(diagram, worksheet_id: int, routes: dict, components: dict) -> None:
    st.session_state[_manual_component_overrides_key(worksheet_id)] = json.loads(json.dumps(dict(components or {})))
    st.session_state[_manual_connection_overrides_key(worksheet_id)] = json.loads(json.dumps(dict(routes or {})))
    final_png = create_preview_png(
        diagram=diagram,
        assets_dir=ASSETS_DIR,
        manual_route_overrides=routes,
        manual_component_overrides=components,
    )
    st.session_state["preview_png"] = final_png
    st.session_state["pdf_bytes"] = png_to_pdf(final_png)
    st.session_state.pop(_manual_edit_png_key(worksheet_id), None)
    if "worksheets" in st.session_state:
        persist_active_worksheet_state()
    add_diagram_to_ppt_session(int(worksheet_id), final_png)


def _worksheet_render_bundle_key(
    diagram,
    worksheet_id: int,
    route_overrides: dict,
    component_overrides: dict,
) -> str:
    """Build a cheap key for deterministic Worksheet renderer intermediates."""
    try:
        route_signature = json.dumps(
            route_overrides,
            sort_keys=True,
            separators=(",", ":"),
            default=str,
        )
    except Exception:
        route_signature = repr(route_overrides)
    try:
        component_signature = json.dumps(
            component_overrides,
            sort_keys=True,
            separators=(",", ":"),
            default=str,
        )
    except Exception:
        component_signature = repr(component_overrides)

    return hashlib.sha256(
        (
            f"{int(worksheet_id)}|{id(diagram)}|"
            f"{st.session_state.get('processed_hash', '')}|"
            f"{route_signature}|{component_signature}"
        ).encode("utf-8")
    ).hexdigest()


def _lightweight_component_sprites_from_geometry(diagram, geometry: dict) -> list[dict]:
    """Build normal-Worksheet sprite metadata without rasterizing the diagram.

    The normal Worksheet immediately replaces each known component's sprite bytes
    with the exact component asset already used by the current UI. Building a full
    component-only PNG and cropping it once per component was therefore duplicate
    work on the normal path. This helper keeps the same instance ids, labels and
    geometry boxes, and the original renderer is still used as a fallback only when
    a component asset cannot be resolved.
    """
    hidden = set(geometry.get("hidden_components", []) or [])
    box_map = dict(geometry.get("boxes", {}) or {})
    node_by_id = {
        str(getattr(node, "id", "") or ""): node
        for node in (getattr(diagram, "nodes", []) or [])
    }

    sprites: list[dict] = []
    for node_id, raw_box in box_map.items():
        node_id = str(node_id or "")
        node = node_by_id.get(node_id)
        if node is None or node_id in hidden:
            continue
        if str(getattr(node, "node_type", "") or "") == "junction":
            continue
        if not isinstance(raw_box, (list, tuple)) or len(raw_box) != 4:
            continue
        try:
            box = [float(value) for value in raw_box]
        except (TypeError, ValueError):
            continue
        sprites.append({
            "instance_id": node_id,
            "title": str(getattr(node, "label", node_id) or node_id),
            "box": box,
            "image_b64": "",
        })
    return sprites


def _worksheet_name_header_png(
    source_png: bytes,
    worksheet_name: str,
) -> bytes:
    """Display the current worksheet name in the existing top-left header title.

    This changes only the text line currently occupied by
    "Agentic Sketch-to-PPT". The existing blue header, subtitle, status pill,
    center diagram title, component layout and all interaction logic stay intact.
    """
    worksheet_name = str(worksheet_name or "").strip()
    if not worksheet_name:
        return source_png

    try:
        with Image.open(io.BytesIO(source_png)) as source_image:
            canvas = source_image.convert("RGB")
            draw = ImageDraw.Draw(canvas)
            width, _height = canvas.size

            header_fill = (7, 60, 120)
            title_x = 86
            title_y = 56

            # Clear only the existing first-line brand title area.
            # The subtitle at y=112 and every other header element are untouched.
            clear_right = min(max(title_x + 650, 980), max(title_x + 650, width - 430))
            draw.rectangle(
                (70, 22, clear_right, 88),
                fill=header_fill,
            )

            font_size = 42
            max_title_width = max(300, clear_right - title_x - 18)
            font = renderers_module.load_font(font_size, True)

            # Keep the same existing title style. Only shrink unusually long
            # worksheet names enough to remain inside the same header area.
            while font_size > 22:
                try:
                    bbox = draw.textbbox(
                        (0, 0),
                        worksheet_name,
                        font=font,
                    )
                    text_width = max(0, int(bbox[2] - bbox[0]))
                except Exception:
                    text_width = 0

                if text_width <= max_title_width:
                    break

                font_size -= 2
                font = renderers_module.load_font(font_size, True)

            draw.text(
                (title_x, title_y),
                worksheet_name,
                anchor="lm",
                fill=(255, 255, 255),
                font=font,
            )

            output_buffer = io.BytesIO()
            canvas.save(
                output_buffer,
                format="PNG",
                optimize=False,
                compress_level=3,
            )
            return output_buffer.getvalue()
    except Exception:
        # Preserve the current Worksheet exactly if display-only text drawing
        # cannot be applied for any environment/font reason.
        return source_png


def _get_cached_worksheet_render_bundle(
    diagram,
    worksheet_id: int,
    route_overrides: dict,
    component_overrides: dict,
):
    """Reuse geometry/base/sprite work across unrelated Streamlit reruns.

    These renderer calls are deterministic for the same diagram and manual
    overrides, but are among the most expensive operations on every interaction.
    Only one current bundle per worksheet is retained, preventing unbounded memory
    growth while keeping all existing rendered output identical.
    """
    state_key = f"_worksheet_render_bundle_cache_{int(worksheet_id)}"
    cache_key = _worksheet_render_bundle_key(
        diagram,
        worksheet_id,
        route_overrides,
        component_overrides,
    )
    cached = st.session_state.get(state_key)
    if isinstance(cached, dict) and cached.get("key") == cache_key:
        return (
            cached["geometry"],
            cached["base_png"],
            cached.get("base_b64")
            or base64.b64encode(cached["base_png"]).decode("ascii"),
            [dict(item) for item in cached["components"]],
        )

    geometry = get_preview_route_geometry(
        diagram,
        manual_route_overrides=route_overrides,
        manual_component_overrides=component_overrides,
    )
    base_png = create_editor_base_png(
        diagram=diagram,
        assets_dir=ASSETS_DIR,
        manual_route_overrides=route_overrides,
        manual_component_overrides=component_overrides,
    )
    # Performance only: normal Worksheet rendering uses exact component assets
    # below, so avoid the duplicate full component-only raster pass here.
    # The original renderer remains the fallback for any unresolved asset.
    component_sprites = _lightweight_component_sprites_from_geometry(
        diagram,
        geometry,
    )

    base_b64 = base64.b64encode(base_png).decode("ascii")
    st.session_state[state_key] = {
        "key": cache_key,
        "geometry": geometry,
        "base_png": base_png,
        "base_b64": base_b64,
        "components": [dict(item) for item in component_sprites],
    }
    return geometry, base_png, base_b64, component_sprites


def _blank_worksheet_structure_source_diagram():
    """Return a diagram only as a structural renderer source.

    The returned diagram is never stored into the new worksheet and none of its
    components/routes are rendered. It is used only so the existing Worksheet
    renderer can produce the exact same base structure/layout/design.
    """
    # Prefer an already-generated worksheet so the blank surface follows the
    # exact currently working Worksheet renderer/template.
    for sheet in st.session_state.get("worksheets", []) or []:
        source_diagram = sheet.get("diagram")
        if source_diagram is not None:
            return source_diagram

    # Fresh-session fallback: build one temporary cached diagram only to obtain
    # the existing renderer's structural background. This does not change any
    # worksheet/component state and the temporary component is never displayed.
    try:
        return _cached_build_selected_component_diagram(
            ("Sump",),
            tuple(),
            "{}",
            "{}",
            _component_catalog_cache_version(),
        )
    except Exception as exc:
        log_app_error("Blank Worksheet structure source", exc)
        return None


@guarded_ui(
    "Blank Worksheet rendering",
    action="rendering the blank worksheet structure",
)
def _render_blank_worksheet_structure(worksheet_id: int) -> bool:
    """Render the existing Worksheet structure with zero components/routes."""
    worksheet_id = int(worksheet_id)
    source_diagram = _blank_worksheet_structure_source_diagram()
    if source_diagram is None:
        return False

    # Reuse the exact existing Worksheet base renderer. Routes/components from
    # the structural source are intentionally ignored below.
    geometry, base_png, _base_b64, _source_components = (
        _get_cached_worksheet_render_bundle(
            source_diagram,
            worksheet_id,
            {},
            {},
        )
    )

    active_sheet = get_active_worksheet()
    worksheet_display_name = str(
        active_sheet.get(
            "name",
            f"Worksheet {worksheet_id}",
        )
        or f"Worksheet {worksheet_id}"
    ).strip()

    base_png = _worksheet_name_header_png(
        base_png,
        worksheet_display_name,
    )
    base_b64 = base64.b64encode(base_png).decode("ascii")

    canvas_width = float(geometry.get("width", 1.0) or 1.0)
    canvas_height = float(geometry.get("height", 1.0) or 1.0)

    render_revision = hashlib.sha256(
        (
            f"blank-worksheet-structure-v1|"
            f"{worksheet_id}|"
            f"{worksheet_display_name}|"
            f"{canvas_width:.8f}|{canvas_height:.8f}"
        ).encode("utf-8")
    ).hexdigest()

    # Same custom Worksheet surface, same dimensions, same working area.
    # Only live component/route layers are empty for the new worksheet.
    _direct_connection_editor(
        image_b64=base_b64,
        canvas_width=canvas_width,
        canvas_height=canvas_height,
        routes=[],
        hotspots=[],
        components=[],
        background_contains_components=False,
        edit_mode=False,
        drag_only=True,
        fit_screen=True,
        fixed_screen_height=550,
        expanded=False,
        initial_selected_edge=None,
        pending_connection_source_id=None,
        worksheet_title=str(
            renderers_module.get_display_title(
                source_diagram
            )
        ),
        render_revision=render_revision,
        local_draft_key=(
            f"worksheet_motion_v46_{worksheet_id}_inline"
        ),
        key=(
            f"diagram_normal_surface_{worksheet_id}_inline"
        ),
        default=None,
    )
    return True


@guarded_ui("Worksheet rendering", action="rendering the worksheet")
def _render_normal_diagram_preview(preview_png: bytes, diagram, worksheet_id: int, *, expanded: bool = False) -> None:
    """Normal worksheet view: hovering a component shows +; only + duplicates it."""
    if diagram is None:
        return
    route_overrides = dict(
        st.session_state.get(_manual_connection_overrides_key(worksheet_id), {}) or {}
    )
    component_overrides = dict(
        st.session_state.get(_manual_component_overrides_key(worksheet_id), {}) or {}
    )
    geometry, normal_base_png, normal_base_b64, normal_components = _get_cached_worksheet_render_bundle(
        diagram,
        worksheet_id,
        route_overrides,
        component_overrides,
    )

    active_sheet = get_active_worksheet()
    worksheet_display_name = str(
        active_sheet.get("name", f"Worksheet {worksheet_id}") or f"Worksheet {worksheet_id}"
    ).strip()
    normal_base_png = _worksheet_name_header_png(
        normal_base_png,
        worksheet_display_name,
    )
    normal_base_b64 = base64.b64encode(normal_base_png).decode("ascii")

    canvas_width = float(geometry.get("width", 1.0) or 1.0)
    canvas_height = float(geometry.get("height", 1.0) or 1.0)
    hidden = set(geometry.get("hidden_components", []) or [])
    box_map = dict(geometry.get("boxes", {}) or {})

    # Worksheet component-image visibility fix only.
    #
    # The optimized lightweight bundle normally supplies every selected
    # component box. If a current visible node is missing from that bundle,
    # recover only the missing sprite/box using the application's existing
    # component-sprite renderer. This preserves the current layout, routing,
    # component relationships and interactions while preventing a blank
    # Worksheet component layer.
    visible_node_ids = {
        str(getattr(node, "id", "") or "")
        for node in (getattr(diagram, "nodes", []) or [])
        if (
            str(getattr(node, "id", "") or "")
            and str(getattr(node, "id", "") or "") not in hidden
            and str(getattr(node, "node_type", "") or "") != "junction"
        )
    }

    normal_component_ids = {
        str(item.get("instance_id", "") or "")
        for item in list(normal_components or [])
        if isinstance(item, dict)
    }

    for item in list(normal_components or []):
        if not isinstance(item, dict):
            continue
        override = component_overrides.get(str(item.get("instance_id", "") or ""), {})
        if isinstance(override, dict) and str(override.get("title", "") or "").strip():
            item["title"] = str(override["title"]).strip()

    def _valid_component_box(value) -> bool:
        if not isinstance(value, (list, tuple)) or len(value) != 4:
            return False
        try:
            x, y, width, height = [float(v) for v in value]
        except (TypeError, ValueError):
            return False
        return width > 0 and height > 0

    missing_component_ids = {
        node_id
        for node_id in visible_node_ids
        if (
            node_id not in normal_component_ids
            or not _valid_component_box(box_map.get(node_id))
        )
    }

    if missing_component_ids:
        try:
            full_component_sprites = create_editor_component_sprites(
                diagram=diagram,
                assets_dir=ASSETS_DIR,
                manual_route_overrides=route_overrides,
                manual_component_overrides=component_overrides,
            )
        except Exception as exc:
            log_app_error("Worksheet component image recovery", exc)
            full_component_sprites = []

        full_sprite_by_id = {
            str(item.get("instance_id", "") or ""): dict(item)
            for item in list(full_component_sprites or [])
            if isinstance(item, dict)
            and str(item.get("instance_id", "") or "") in visible_node_ids
        }

        normal_component_by_id = {
            str(item.get("instance_id", "") or ""): item
            for item in list(normal_components or [])
            if isinstance(item, dict)
            and str(item.get("instance_id", "") or "")
        }

        for instance_id in missing_component_ids:
            recovered = full_sprite_by_id.get(instance_id)
            if not recovered:
                continue

            recovered_box = recovered.get("box")
            if _valid_component_box(recovered_box):
                box_map[instance_id] = [
                    float(value) for value in recovered_box
                ]

            existing = normal_component_by_id.get(instance_id)
            if existing is None:
                normal_components.append(recovered)
                normal_component_by_id[instance_id] = recovered
            else:
                if not str(existing.get("image_b64", "") or ""):
                    existing["image_b64"] = str(
                        recovered.get("image_b64", "") or ""
                    )
                if not _valid_component_box(existing.get("box")) and _valid_component_box(
                    recovered_box
                ):
                    existing["box"] = [
                        float(value) for value in recovered_box
                    ]
                if "image_fit" in recovered:
                    existing["image_fit"] = recovered["image_fit"]

    saved_editor_state = st.session_state.get("editor_saved_state") or {}
    if isinstance(saved_editor_state, dict):
        for item in list(saved_editor_state.get("components", []) or []):
            if not isinstance(item, dict):
                continue
            node_id = str(item.get("instance_id", "") or "")
            raw_box = item.get("box")
            if node_id and isinstance(raw_box, (list, tuple)) and len(raw_box) == 4:
                try:
                    box_map[node_id] = [float(v) for v in raw_box]
                except Exception:
                    pass
            if node_id and bool(item.get("hidden", False)):
                hidden.add(node_id)
    hotspots = []
    for node in (getattr(diagram, "nodes", []) or []):
        node_id = str(getattr(node, "id", "") or "")
        if node_id in hidden or getattr(node, "node_type", "") == "junction":
            continue
        component_name = _component_name_from_diagram_node(node)
        box = box_map.get(node_id)
        if not component_name or not box or len(box) != 4:
            continue
        x, y, w, h = [float(v) for v in box]
        hotspots.append({
            "component": component_name, "instance_id": node_id,
            "title": str(getattr(node, "label", component_name) or component_name),
            "left": x, "top": y, "width": w, "height": h,
        })
    view_key = "expanded" if expanded else "inline"
    # Worksheet drag/drop uses the same renderer geometry and exact component
    # sprites as the existing professional editor, but exposes ONLY component
    # movement in the normal Worksheet. Existing click-to-connect, + duplicate,
    # delete, rendering, export and Edit Mode behavior remain unchanged.
    normal_routes = []
    for edge_id, route in dict(geometry.get("routes", {}) or {}).items():
        if not isinstance(route, dict):
            continue
        # Keep the existing engineering relationship classification unchanged:
        # renderer-dotted routes are unit/communication links; all other routes
        # are water links. Wireless selection must not convert a water pipe into
        # a unit-to-unit dotted line.
        route_is_dotted = bool(route.get("dotted", False))

        # Fixed visual standard only:
        # water connection = blue solid; unit-to-unit = black dotted.
        worksheet_route_color = "#000000" if route_is_dotted else "#123DBD"

        normal_routes.append(
            {
                "edge_id": str(edge_id),
                "points": route.get("points", []),
                "original_points": route.get("original_points", route.get("points", [])),
                "color": worksheet_route_color,
                "dotted": route_is_dotted,
                "direction": route.get("edge_direction", "source_to_target"),
                "original_direction": route.get(
                    "original_edge_direction",
                    route.get("edge_direction", "source_to_target"),
                ),
                "source": str(route.get("source", "") or ""),
                "target": str(route.get("target", "") or ""),
                "hidden": bool(route.get("hidden", False)),
                "arrow_control": (
                    route_overrides
                    .get(str(edge_id), {})
                    .get("arrow_control")
                ),
            }
        )

    node_labels = {
        str(getattr(node, "id", "") or ""): str(
            getattr(node, "label", "") or getattr(node, "id", "") or ""
        )
        for node in (getattr(diagram, "nodes", []) or [])
    }
    saved_components = []
    if isinstance(saved_editor_state, dict):
        saved_components = list(saved_editor_state.get("components", []) or [])
    pinned_ids = {
        str(item.get("instance_id", "") or "")
        for item in saved_components
        if isinstance(item, dict)
        and isinstance(item.get("box"), (list, tuple))
        and len(item.get("box")) == 4
    }
    pinned_ids.update(
        str(node_id)
        for node_id, override in component_overrides.items()
        if isinstance(override, dict) and isinstance(override.get("box"), (list, tuple))
    )
    manual_edge_ids = {
        str(edge_id)
        for edge_id, override in route_overrides.items()
        if isinstance(override, dict) and override.get("points")
    }
    apply_worksheet_graph(
        normal_routes,
        box_map,
        canvas_width,
        canvas_height,
        node_labels,
        pinned_ids,
        manual_edge_ids,
    )
    for hotspot in hotspots:
        instance_id = str(hotspot.get("instance_id", "") or "")
        placed = box_map.get(instance_id)
        if not isinstance(placed, (list, tuple)) or len(placed) != 4:
            continue
        hotspot["left"], hotspot["top"], hotspot["width"], hotspot["height"] = placed

    # Wireless visual marker only. The Wi-Fi symbol follows the user's explicit
    # Wireless mode selection only. Automatic and Wired must never display it,
    # even if an older/generated edge still carries wireless metadata.
    wireless_component_names = {"Master", "Transmitter", "Repeater"}
    current_wireless_settings = dict(
        st.session_state.get("connection_transport_settings", {}) or {}
    )
    wireless_mode_selected = any(
        normalize_connection_mode(dict(config or {}).get("mode", "automatic"))
        == "wireless"
        for config in current_wireless_settings.values()
    )
    wireless_active_for_worksheet = wireless_mode_selected
    wireless_device_ids = {
        str(getattr(node, "id", "") or "")
        for node in (getattr(diagram, "nodes", []) or [])
        if _component_name_from_diagram_node(node) in wireless_component_names
    } if wireless_active_for_worksheet else set()

    # Worksheet component-image visibility fix only.
    # Use the actual component asset directly whenever available. This avoids
    # blank/white sprite crops while preserving the current Worksheet size,
    # component box, position, routing and all interaction behavior.
    node_by_id = {
        str(getattr(node, "id", "") or ""): node
        for node in (getattr(diagram, "nodes", []) or [])
    }
    for item in normal_components:
        instance_id = str(item.get("instance_id", "") or "")
        node = node_by_id.get(instance_id)
        if node is None:
            continue

        component_name = _component_name_from_diagram_node(node)

        # The three flow-meter types have separate user-uploaded images in
        # assets/component_images.  Resolve those exact files first for the
        # Worksheet only; every other component keeps the existing renderer path.
        asset_path = _worksheet_flow_meter_asset(component_name)

        if asset_path is None:
            try:
                asset_path = node_component_asset_path(ASSETS_DIR, node)
            except Exception as exc:
                log_app_error(
                    f"Worksheet component asset lookup: {instance_id}",
                    exc,
                )
                asset_path = None

        if asset_path is None:
            try:
                asset_path = component_asset_path(
                    ASSETS_DIR,
                    str(getattr(node, "node_type", "") or ""),
                )
            except Exception as exc:
                log_app_error(
                    f"Worksheet fallback component asset lookup: {instance_id}",
                    exc,
                )
                asset_path = None

        if asset_path is None or not Path(asset_path).exists():
            continue

        try:
            asset_stat = Path(asset_path).stat()
            item["wireless"] = instance_id in wireless_device_ids
            item["image_b64"] = _worksheet_component_sprite_b64(
                str(Path(asset_path).resolve()),
                int(asset_stat.st_mtime_ns),
                int(asset_stat.st_size),
            )
            item["image_fit"] = "contain"
            # Internal-only flag: this is a real component asset, not a
            # renderer fallback card. Never run renderer-caption cleanup on it.
            item["_worksheet_direct_asset"] = True
        except Exception as exc:
            log_app_error(f"Worksheet component sprite image: {instance_id}", exc)

    # Preserve the exact previous fallback behavior for any component whose direct
    # asset cannot be resolved. Only in that uncommon case do the expensive
    # component-only render/crop pass that used to run for every Worksheet update.
    component_name_by_id = {
        str(getattr(node, "id", "") or ""): (
            _component_name_from_diagram_node(node) or ""
        )
        for node in (getattr(diagram, "nodes", []) or [])
    }

    unresolved_ids = {
        str(item.get("instance_id", "") or "")
        for item in normal_components
        if not str(item.get("image_b64", "") or "")
    }

    # Original component label style only.
    # Use renderer fallback sprites only when the direct component image could
    # not be resolved. Do not force any component to use an embedded caption.
    if unresolved_ids:
        fallback_sprites = create_editor_component_sprites(
            diagram=diagram,
            assets_dir=ASSETS_DIR,
            manual_route_overrides=route_overrides,
            manual_component_overrides=component_overrides,
        )
        fallback_by_id = {
            str(item.get("instance_id", "") or ""): item
            for item in list(fallback_sprites or [])
            if isinstance(item, dict)
        }
        for item in normal_components:
            instance_id = str(item.get("instance_id", "") or "")
            if instance_id not in unresolved_ids:
                continue
            fallback = fallback_by_id.get(instance_id)
            if not fallback:
                continue
            item["image_b64"] = str(fallback.get("image_b64", "") or "")
            item["_worksheet_direct_asset"] = False
            if "image_fit" in fallback:
                item["image_fit"] = fallback["image_fit"]

    # Restore the exact original component-label presentation for every
    # component: remove only any embedded blue renderer caption so the existing
    # live SVG label is the single visible label.
    for item in normal_components:
        image_b64 = str(item.get("image_b64", "") or "")
        is_direct_asset = bool(item.pop("_worksheet_direct_asset", False))

        if image_b64:
            if is_direct_asset:
                # Keep the real component image pixel-for-pixel intact.
                item["image_b64"] = image_b64
            else:
                # Existing fallback behavior only: renderer-generated sprites
                # may contain the old embedded caption/card border.
                image_b64 = _worksheet_remove_embedded_component_label(
                    image_b64
                )
                item["image_b64"] = _worksheet_remove_component_border_box(
                    image_b64
                )

        item.pop("use_embedded_label", None)

    # Worksheet drag/drop fix only.
    # Guarantee one valid draggable payload for every visible selected component.
    # Use the exact current renderer geometry box instead of depending on sprite
    # metadata, which can be absent even though the component is visible.
    draggable_by_id = {}

    for item in normal_components:
        instance_id = str(item.get("instance_id", "") or "")
        if not instance_id or instance_id in hidden:
            continue

        current_box = box_map.get(instance_id)
        if not isinstance(current_box, (list, tuple)) or len(current_box) != 4:
            continue

        try:
            normalized_box = [float(value) for value in current_box]
        except (TypeError, ValueError):
            continue

        if normalized_box[2] <= 0 or normalized_box[3] <= 0:
            continue

        item["box"] = normalized_box
        item["component"] = component_name_by_id.get(instance_id, "")
        item["hidden"] = False
        item["wireless"] = instance_id in wireless_device_ids
        draggable_by_id[instance_id] = item

    # If the sprite builder omitted a visible component, still create its drag
    # target from the already-known hotspot/geometry. The visible image stays in
    # the current Worksheet preview; only the interaction target is added.
    for hotspot in hotspots:
        instance_id = str(hotspot.get("instance_id", "") or "")
        if not instance_id or instance_id in draggable_by_id:
            continue

        try:
            fallback_box = [
                float(hotspot.get("left", 0.0)),
                float(hotspot.get("top", 0.0)),
                float(hotspot.get("width", 0.0)),
                float(hotspot.get("height", 0.0)),
            ]
        except (TypeError, ValueError):
            continue

        if fallback_box[2] <= 0 or fallback_box[3] <= 0:
            continue

        draggable_by_id[instance_id] = {
            "instance_id": instance_id,
            "component": str(hotspot.get("component", "") or ""),
            "title": str(hotspot.get("title", "") or ""),
            "box": fallback_box,
            "hidden": False,
            "image_b64": "",
            "image_fit": "contain",
            "wireless": instance_id in wireless_device_ids,
        }

    normal_components = list(draggable_by_id.values())

    # Frontend performance only: tell the existing custom component when its
    # actual visual payload is unchanged.  This lets it preserve the already
    # mounted Worksheet DOM during unrelated Streamlit reruns instead of decoding
    # the same background and rebuilding every route/component again.
    pending_source_id = st.session_state.get(
        f"pending_component_connection_source_{worksheet_id}"
    )
    try:
        saved_editor_signature = hashlib.sha256(
            json.dumps(
                saved_editor_state,
                sort_keys=True,
                separators=(",", ":"),
                default=str,
            ).encode("utf-8")
        ).hexdigest()
    except Exception:
        saved_editor_signature = hashlib.sha256(
            repr(saved_editor_state).encode("utf-8")
        ).hexdigest()

    lls_asset_revision = ""
    try:
        lls_asset_path = _manual_asset_for_component("Linear Level Sensor (LLS)")
        if lls_asset_path is not None and Path(lls_asset_path).is_file():
            lls_asset_stat = Path(lls_asset_path).stat()
            lls_asset_revision = (
                f"{Path(lls_asset_path).name}:"
                f"{int(lls_asset_stat.st_mtime_ns)}:"
                f"{int(lls_asset_stat.st_size)}"
            )
    except Exception:
        lls_asset_revision = ""

    normal_render_revision = hashlib.sha256(
        (
            f"component-visibility-protected-v4|"
            f"{_worksheet_render_bundle_key(diagram, worksheet_id, route_overrides, component_overrides)}|"
            f"{view_key}|{pending_source_id or ''}|{int(wireless_active_for_worksheet)}|"
            f"{worksheet_display_name}|{lls_asset_revision}|"
            f"{canvas_width:.8f}|{canvas_height:.8f}|{saved_editor_signature}"
        ).encode("utf-8")
    ).hexdigest()

    event = _direct_connection_editor(
        # Drag/drop uses a component-free background. Components and routes are
        # separate live layers, so the actual visible component moves with the
        # pointer instead of remaining baked into the background image.
        image_b64=normal_base_b64,
        canvas_width=canvas_width,
        canvas_height=canvas_height,
        routes=normal_routes,
        hotspots=hotspots,
        components=normal_components,
        background_contains_components=False,
        edit_mode=False,
        drag_only=True,
        # Keep the existing Zoom In dialog, but also fit the complete diagram
        # inside the enlarged Worksheet viewport so no selected component image
        # is clipped or pushed outside the visible zoomed area.
        fit_screen=True,
        fixed_screen_height=550 if not bool(expanded) else 620,
        # The Streamlit dialog already provides the Zoom In/expanded UI.
        # Keep the editor surface in its normal coordinate mode inside that larger
        # viewport so component images, labels and routes are not shifted/clipped.
        expanded=False,
        initial_selected_edge=None,
        pending_connection_source_id=pending_source_id,
        worksheet_title=str(renderers_module.get_display_title(diagram)),
        render_revision=normal_render_revision,
        local_draft_key=f"worksheet_motion_v46_{worksheet_id}_{view_key}",
        key=f"diagram_normal_surface_{worksheet_id}_{view_key}",
        default=None,
    )
    if not isinstance(event, dict):
        return
    event_id = str(event.get("event_id", "") or "")
    last_key = f"normal_surface_last_event_{worksheet_id}_{view_key}"
    if not event_id or st.session_state.get(last_key) == event_id:
        return
    st.session_state[last_key] = event_id

    event_type = str(event.get("type", "") or "")

    if event_type == "connection_delete":
        edge_id = str(event.get("edge_id", "") or "").strip()
        valid_edge_ids = {
            str(getattr(edge, "id", "") or "")
            for edge in (getattr(diagram, "edges", []) or [])
        }
        if edge_id in valid_edge_ids:
            # Remove the exact edge from the current worksheet diagram first.
            # The live renderer and delayed rerenders must no longer have this
            # connection in their source graph; a visual hidden override alone
            # can be discarded by the normal generation path.
            if diagram is not None and hasattr(diagram, "edges"):
                diagram.edges = [
                    edge
                    for edge in list(getattr(diagram, "edges", []) or [])
                    if str(getattr(edge, "id", "") or "") != edge_id
                ]

            overrides_key = _manual_connection_overrides_key(worksheet_id)
            route_overrides = dict(
                st.session_state.get(overrides_key, {}) or {}
            )
            route_overrides.pop(edge_id, None)
            st.session_state[overrides_key] = route_overrides

            # Remove the logical selection as well as hiding the current visual
            # route. Otherwise the next worksheet render regenerates the same
            # selected connection from the catalog before the visual override is
            # reapplied. A future manual click can add this connection again.
            option_id = edge_id.removeprefix("edge__")
            selected_connections = list(
                st.session_state.get("selected_connections", []) or []
            )
            st.session_state["selected_connections"] = [
                connection_id
                for connection_id in selected_connections
                if str(connection_id) not in {edge_id, option_id}
            ]
            deleted_ids = {
                str(value)
                for value in st.session_state.get(
                    _deleted_connection_ids_key(worksheet_id), []
                )
                or []
            }
            deleted_ids.update({edge_id, option_id})
            st.session_state[_deleted_connection_ids_key(worksheet_id)] = sorted(
                deleted_ids
            )
            transport_settings = dict(
                st.session_state.get("connection_transport_settings", {}) or {}
            )
            transport_settings.pop(option_id, None)
            transport_settings.pop(edge_id, None)
            st.session_state["connection_transport_settings"] = transport_settings

            # Performance only: the browser already applied the visual delete.
            # Persist the same override and defer export-quality raster/PDF/PPT
            # materialization until an explicit Download/PPT operation requires it.
            st.session_state.pop(_manual_edit_png_key(worksheet_id), None)
            persist_active_worksheet_state()
            _mark_worksheet_render_sync_pending(worksheet_id)
            _mark_ppt_sync_pending(worksheet_id)
        return

    if event_type == "connection_route_move":
        edge_id = str(event.get("edge_id", "") or "").strip()
        raw_points = event.get("points")
        valid_edge_ids = {
            str(getattr(edge, "id", "") or "")
            for edge in (getattr(diagram, "edges", []) or [])
        }

        if (
            edge_id in valid_edge_ids
            and isinstance(raw_points, (list, tuple))
            and len(raw_points) >= 2
        ):
            try:
                moved_points = [
                    [float(point[0]), float(point[1])]
                    for point in raw_points
                    if isinstance(point, (list, tuple)) and len(point) >= 2
                ]
            except (TypeError, ValueError):
                moved_points = []

            if len(moved_points) >= 2:
                overrides_key = _manual_connection_overrides_key(worksheet_id)
                route_overrides = dict(
                    st.session_state.get(overrides_key, {}) or {}
                )
                existing_route = dict(route_overrides.get(edge_id, {}) or {})
                existing_route["points"] = moved_points
                existing_route["mode"] = "manual_drag"

                if "arrow_control" in event:
                    raw_arrow_control = event.get("arrow_control")
                    if (
                        isinstance(raw_arrow_control, (list, tuple))
                        and len(raw_arrow_control) >= 2
                    ):
                        try:
                            existing_route["arrow_control"] = [
                                float(raw_arrow_control[0]),
                                float(raw_arrow_control[1]),
                            ]
                        except (TypeError, ValueError):
                            pass
                    elif raw_arrow_control is None:
                        existing_route.pop("arrow_control", None)

                route_overrides[edge_id] = existing_route
                st.session_state[overrides_key] = route_overrides

                # Performance only: pointer movement is already rendered in the
                # custom Worksheet. Persist the exact dropped route and postpone
                # raster/PDF/PPT work until Download/PPT explicitly requires it.
                st.session_state.pop(_manual_edit_png_key(worksheet_id), None)
                persist_active_worksheet_state()
                _mark_worksheet_render_sync_pending(worksheet_id)
                _mark_ppt_sync_pending(worksheet_id)
        return

    if event_type == "component_move":
        instance_id = str(event.get("instance_id", "") or "").strip()
        raw_box = event.get("box")
        valid_node_ids = {
            str(getattr(node, "id", "") or "")
            for node in (getattr(diagram, "nodes", []) or [])
        }
        if (
            instance_id in valid_node_ids
            and isinstance(raw_box, (list, tuple))
            and len(raw_box) == 4
        ):
            try:
                moved_box = [float(value) for value in raw_box]
            except (TypeError, ValueError):
                moved_box = []

            if (
                len(moved_box) == 4
                and moved_box[2] > 0
                and moved_box[3] > 0
            ):
                component_overrides = dict(
                    st.session_state.get(
                        _manual_component_overrides_key(worksheet_id), {}
                    )
                    or {}
                )
                existing = dict(component_overrides.get(instance_id, {}) or {})
                existing["box"] = moved_box
                existing.pop("hidden", None)
                component_overrides[instance_id] = existing
                st.session_state[
                    _manual_component_overrides_key(worksheet_id)
                ] = component_overrides

                # Performance only: retain the exact saved component override
                # and defer export-quality bytes. The live Worksheet continues to
                # use this same component geometry and existing connection logic.
                st.session_state.pop(_manual_edit_png_key(worksheet_id), None)
                persist_active_worksheet_state()
                _mark_worksheet_render_sync_pending(worksheet_id)
                _mark_ppt_sync_pending(worksheet_id)
        return

    if event_type == "component_label_edit":
        instance_id = str(event.get("instance_id", "") or "").strip()
        title = str(event.get("title", "") or "").strip()
        valid_node_ids = {
            str(getattr(node, "id", "") or "")
            for node in (getattr(diagram, "nodes", []) or [])
        }
        if instance_id in valid_node_ids and title:
            component_overrides = dict(
                st.session_state.get(
                    _manual_component_overrides_key(worksheet_id), {}
                )
                or {}
            )
            existing = dict(component_overrides.get(instance_id, {}) or {})
            existing["title"] = title
            component_overrides[instance_id] = existing
            st.session_state[_manual_component_overrides_key(worksheet_id)] = component_overrides
            st.session_state.pop(_manual_edit_png_key(worksheet_id), None)
            persist_active_worksheet_state()
            _mark_worksheet_render_sync_pending(worksheet_id)
            _mark_ppt_sync_pending(worksheet_id)
        return

    if event_type == "component_add":
        # Compatibility fallback only. Use the same Worksheet +/- state handler
        # as the normal early-consume path.
        component_name = str(event.get("component", "") or "").strip()
        if component_name and _add_component_instance_from_worksheet(
            worksheet_id,
            component_name,
        ):
            st.rerun()
        return

    if event_type == "component_delete":
        # Compatibility fallback only; current normal flow is handled earlier.
        component_name = str(event.get("component", "") or "").strip()
        instance_id = str(event.get("instance_id", "") or "").strip()
        if component_name and instance_id and _delete_component_instance_from_worksheet(
            worksheet_id,
            component_name,
            instance_id,
            diagram,
        ):
            st.rerun()
        return

    if event_type == "component_select":
        clicked_id = str(event.get("instance_id", "") or "").strip()
        if not clicked_id:
            return

        pending_key = f"pending_component_connection_source_{worksheet_id}"
        first_id = str(st.session_state.get(pending_key, "") or "").strip()

        # First click/touch: remember the exact rendered component instance.
        # This state lives in Streamlit rather than only in JavaScript, so the
        # selection survives component rerenders and works reliably for mouse,
        # touch and pen input.
        if not first_id:
            st.session_state[pending_key] = clicked_id
            # The component event itself is already the current Streamlit run.
            # Store the pending selection without starting a second rerun.
            return

        # Clicking the same component again cancels the pending connection.
        if first_id == clicked_id:
            st.session_state.pop(pending_key, None)
            # Cancel locally/server-side without a second unnecessary rerun.
            return

        selected_names = list(st.session_state.get("selected_components", []) or [])
        matching_option = next(
            (
                option
                for option in allowed_connection_options(selected_names)
                if {str(option.source_id), str(option.target_id)} == {first_id, clicked_id}
            ),
            None,
        )

        # The second click starts a fresh pair even when these two components do
        # not have an allowed engineering relationship. Existing 2A rules remain
        # unchanged.
        if matching_option is None:
            st.session_state[pending_key] = clicked_id
            # Keep the next pending endpoint without an extra rerun.
            return

        deleted_ids = {
            str(value)
            for value in st.session_state.get(
                _deleted_connection_ids_key(worksheet_id), []
            )
            or []
        }
        deleted_ids.difference_update(
            {str(matching_option.id), f"edge__{matching_option.id}"}
        )
        st.session_state[_deleted_connection_ids_key(worksheet_id)] = sorted(
            deleted_ids
        )

        # If this exact automatically-generated relationship was manually deleted,
        # choosing the same two components recreates only that connection.  Remove
        # only its hidden visual override; all other routes/components remain intact.
        route_overrides_key = _manual_connection_overrides_key(worksheet_id)
        route_overrides = dict(
            st.session_state.get(route_overrides_key, {}) or {}
        )
        matching_diagram_edge_id = next(
            (
                str(getattr(edge, "id", "") or "")
                for edge in (getattr(diagram, "edges", []) or [])
                if {
                    str(getattr(edge, "source", "") or ""),
                    str(getattr(edge, "target", "") or ""),
                } == {first_id, clicked_id}
            ),
            "",
        )
        matching_diagram_edge_id = matching_diagram_edge_id or (
            f"edge__{matching_option.id}"
        )
        hidden_route = dict(
            route_overrides.get(matching_diagram_edge_id, {}) or {}
        ) if matching_diagram_edge_id else {}
        if matching_diagram_edge_id and bool(hidden_route.get("hidden", False)):
            hidden_route.pop("hidden", None)
            if hidden_route:
                route_overrides[matching_diagram_edge_id] = hidden_route
            else:
                route_overrides.pop(matching_diagram_edge_id, None)
            st.session_state[route_overrides_key] = route_overrides

            # Performance only: restoring an existing route changes only its
            # saved visual override. Defer PNG/PDF/PPT generation until requested.
            st.session_state.pop(_manual_edit_png_key(worksheet_id), None)
            st.session_state.pop(pending_key, None)
            persist_active_worksheet_state()
            _mark_worksheet_render_sync_pending(worksheet_id)
            _mark_ppt_sync_pending(worksheet_id)
            st.rerun()
            return

        selected_ids = list(st.session_state.get("selected_connections", []) or [])
        if matching_option.id not in selected_ids:
            selected_ids.append(matching_option.id)
            st.session_state["selected_connections"] = selected_ids

            transport_settings = dict(
                st.session_state.get("connection_transport_settings", {}) or {}
            )
            transport_settings.setdefault(
                matching_option.id,
                _default_connection_transport_setting(),
            )
            st.session_state["connection_transport_settings"] = transport_settings

            # 2A was rendered earlier in this Streamlit run. Rotate only that
            # widget key so the persisted connection becomes its new default.
            generation_key = f"connection_picker_generation_{worksheet_id}"
            st.session_state[generation_key] = int(
                st.session_state.get(generation_key, 0) or 0
            ) + 1

        st.session_state.pop(pending_key, None)
        persist_active_worksheet_state()
        st.rerun()


@guarded_ui("Worksheet edit rendering", action="opening the diagram editor")
def _render_clickable_diagram_preview(preview_png: bytes, diagram, worksheet_id: int, *, expanded: bool = False) -> None:
    """Professional manual editor. Automatic routing remains the immutable baseline."""
    if diagram is None:
        return

    overrides_key = _manual_connection_overrides_key(worksheet_id)
    component_overrides_key = _manual_component_overrides_key(worksheet_id)
    overrides = dict(st.session_state.get(overrides_key, {}) or {})
    component_overrides = dict(st.session_state.get(component_overrides_key, {}) or {})
    _ensure_editor_history(worksheet_id)

    geometry = get_preview_route_geometry(
        diagram,
        manual_route_overrides=overrides,
        manual_component_overrides=component_overrides,
    )
    canvas_width = float(geometry.get("width", 1.0) or 1.0)
    canvas_height = float(geometry.get("height", 1.0) or 1.0)
    route_map = dict(geometry.get("routes", {}) or {})
    box_map = dict(geometry.get("boxes", {}) or {})
    labels = _connection_label_lookup(diagram)

    routes = []
    for edge_id, route in route_map.items():
        if not isinstance(route, dict):
            continue
        source = str(route.get("source", "") or "")
        target = str(route.get("target", "") or "")
        route_is_dotted = bool(route.get("dotted", False))
        routes.append({
            "edge_id": str(edge_id),
            "label": labels.get(str(edge_id), str(route.get("label", edge_id) or edge_id)),
            "points": route.get("points", []),
            "original_points": route.get("original_points", route.get("points", [])),
            "color": "#000000" if route_is_dotted else "#123DBD",
            "dotted": route_is_dotted,
            "direction": route.get("edge_direction", "source_to_target"),
            "original_direction": route.get("original_edge_direction", route.get("edge_direction", "source_to_target")),
            "hidden": bool(route.get("hidden", False)),
            "source": source,
            "target": target,
            "source_box": box_map.get(source),
            "target_box": box_map.get(target),
            "custom": bool(route.get("custom", False)),
        })

    view_key = "expanded" if expanded else "inline"
    component_key = f"professional_diagram_editor_{worksheet_id}_{view_key}"
    editor_base_png = create_editor_base_png(
        diagram=diagram,
        assets_dir=ASSETS_DIR,
        manual_route_overrides=overrides,
        manual_component_overrides=component_overrides,
    )
    active_sheet = get_active_worksheet()
    worksheet_display_name = str(
        active_sheet.get("name", f"Worksheet {worksheet_id}") or f"Worksheet {worksheet_id}"
    ).strip()
    editor_base_png = _worksheet_name_header_png(
        editor_base_png,
        worksheet_display_name,
    )

    component_sprites = create_editor_component_sprites(
        diagram=diagram,
        assets_dir=ASSETS_DIR,
        manual_route_overrides=overrides,
        manual_component_overrides=component_overrides,
    )

    for item in component_sprites:
        image_b64 = str(item.get("image_b64", "") or "")
        if image_b64:
            image_b64 = _worksheet_remove_embedded_component_label(
                image_b64
            )
            item["image_b64"] = _worksheet_remove_component_border_box(
                image_b64
            )
        item.pop("use_embedded_label", None)

    event = _direct_connection_editor(
        image_b64=base64.b64encode(editor_base_png).decode("ascii"),
        canvas_width=canvas_width,
        canvas_height=canvas_height,
        routes=routes,
        hotspots=[],
        components=component_sprites,
        editor_state=st.session_state.get("editor_saved_state"),
        edit_mode=True,
        expanded=bool(expanded),
        key=component_key,
        default=None,
    )
    if not isinstance(event, dict):
        return

    event_id = str(event.get("event_id", "") or "")
    if not event_id:
        return
    last_event_key = f"professional_editor_last_event_{worksheet_id}_{view_key}"
    if st.session_state.get(last_event_key) == event_id:
        return
    st.session_state[last_event_key] = event_id
    event_type = str(event.get("type", "") or "")

    # The professional editor is now a draft session. Mouse edits stay entirely
    # inside the frontend; Streamlit receives one complete snapshot only when the
    # user presses Save. This prevents every drag/waypoint operation from rerunning
    # the app and returning the user to the Worksheet.
    if event_type != "save_editor":
        return

    image_b64 = str(event.get("image_b64", "") or "")
    if not image_b64:
        return
    try:
        saved_png = base64.b64decode(image_b64, validate=True)
    except Exception:
        return

    saved_routes = list(event.get("routes", []) or [])
    saved_components = list(event.get("components", []) or [])
    saved_state = {
        "routes": saved_routes,
        "components": saved_components,
        "canvas_width": float(event.get("canvas_width", canvas_width) or canvas_width),
        "canvas_height": float(event.get("canvas_height", canvas_height) or canvas_height),
    }

    st.session_state["editor_saved_state"] = saved_state
    st.session_state["preview_png"] = saved_png
    st.session_state["pdf_bytes"] = png_to_pdf(saved_png)
    st.session_state.pop(_worksheet_render_sync_pending_key(worksheet_id), None)
    st.session_state.pop(_manual_edit_png_key(worksheet_id), None)
    if "worksheets" in st.session_state:
        persist_active_worksheet_state()

    # Keep the existing combined-PPT workflow in sync with the exact image the
    # user saved from Edit Mode. The fixed template/session behavior is unchanged.
    add_diagram_to_ppt_session(int(worksheet_id), saved_png)
    st.toast("Edited diagram saved to Worksheet", icon="✅")

@st.dialog("Worksheet Preview", width="large")
@guarded_ui("Worksheet preview dialog", action="opening the worksheet preview")
def _show_expanded_worksheet(preview_png: bytes, diagram, worksheet_id: int) -> None:
    """Show the same worksheet in a larger in-page dialog without navigation."""
    # Position-only adjustment for Worksheet Preview.
    # Target the actual Streamlit dialog element in the parent page so only this
    # modal moves upward. Dialog size, Worksheet size and all functionality stay unchanged.
    components.html(
        """
        <script>
        (() => {
          function moveWorksheetPreviewUp() {
            let doc;
            try {
              doc = window.parent.document;
            } catch (e) {
              return;
            }

            const dialogs = Array.from(doc.querySelectorAll('div[role="dialog"]'));
            for (const dialog of dialogs) {
              const text = (dialog.textContent || '').trim();
              if (!text.includes('Worksheet Preview')) continue;
              dialog.style.setProperty('transform', 'translateY(-42px)', 'important');
              break;
            }
          }

          moveWorksheetPreviewUp();
          requestAnimationFrame(moveWorksheetPreviewUp);
          setTimeout(moveWorksheetPreviewUp, 60);
          setTimeout(moveWorksheetPreviewUp, 180);
        })();
        </script>
        """,
        height=0,
        width=0,
    )
    _render_normal_diagram_preview(
        preview_png,
        diagram,
        worksheet_id,
        expanded=True,
    )


