def _manual_connection_source_key(worksheet_id: int) -> str:
    return f"manual_connection_source_hash_{int(worksheet_id)}"


def _connection_label_lookup(diagram) -> dict[str, str]:
    node_labels = {
        str(node.id): str(getattr(node, "label", node.id))
        for node in (getattr(diagram, "nodes", []) or [])
    }
    labels = {}
    for edge in (getattr(diagram, "edges", []) or []):
        source = node_labels.get(str(edge.source), str(edge.source))
        target = node_labels.get(str(edge.target), str(edge.target))
        labels[str(edge.id)] = f"{source} → {target}"
    return labels


def _orthogonal_manual_route(
    start: tuple[float, float],
    end: tuple[float, float],
    *,
    mode: str,
    x_percent: float,
    y_percent: float,
    canvas_width: float,
    canvas_height: float,
) -> list[list[float]]:
    """Build a manual orthogonal path while keeping the original endpoints."""
    sx, sy = start
    ex, ey = end
    x = max(0.0, min(canvas_width, canvas_width * float(x_percent) / 100.0))
    y = max(0.0, min(canvas_height, canvas_height * float(y_percent) / 100.0))

    if mode == "Horizontal lane":
        points = [(sx, sy), (sx, y), (ex, y), (ex, ey)]
    elif mode == "Vertical lane":
        points = [(sx, sy), (x, sy), (x, ey), (ex, ey)]
    elif mode == "Custom bend":
        # Two adjustable corridor coordinates make a clean 4/5-segment
        # orthogonal route without touching component positions or ports.
        points = [(sx, sy), (x, sy), (x, y), (ex, y), (ex, ey)]
    else:
        points = [(sx, sy), (ex, sy), (ex, ey)]

    compressed = []
    for point in points:
        if not compressed or point != compressed[-1]:
            compressed.append(point)
    return [[float(px), float(py)] for px, py in compressed]


def _render_diagram_with_connection_overrides(diagram, worksheet_id: int) -> bytes:
    overrides = dict(
        st.session_state.get(_manual_connection_overrides_key(worksheet_id), {}) or {}
    )
    return create_preview_png(
        diagram=diagram,
        assets_dir=ASSETS_DIR,
        manual_route_overrides=overrides,
    )


@st.dialog("Edit Connection Lines", width="large")
@guarded_ui("Connection editor", action="editing connection lines")
def _show_manual_connection_editor(diagram, worksheet_id: int) -> None:
    """Manually redraw one visible connection without changing components/router."""
    if diagram is None or not list(getattr(diagram, "edges", []) or []):
        st.info("No connection lines are available to edit.")
        return

    geometry = get_preview_route_geometry(diagram)
    route_map = dict(geometry.get("routes", {}) or {})
    edge_ids = [str(edge.id) for edge in diagram.edges if str(edge.id) in route_map]
    if not edge_ids:
        st.info("No rendered connection lines are available to edit.")
        return

    labels = _connection_label_lookup(diagram)
    selected_edge_id = st.selectbox(
        "Connection",
        edge_ids,
        format_func=lambda edge_id: labels.get(edge_id, edge_id),
        key=f"manual_connection_select_{worksheet_id}",
    )

    current_route = route_map[selected_edge_id]["points"]
    start = tuple(current_route[0])
    end = tuple(current_route[-1])
    canvas_width = float(geometry.get("width", 1.0) or 1.0)
    canvas_height = float(geometry.get("height", 1.0) or 1.0)

    overrides_key = _manual_connection_overrides_key(worksheet_id)
    saved_overrides = dict(st.session_state.get(overrides_key, {}) or {})
    saved = dict(saved_overrides.get(selected_edge_id, {}) or {})

    default_mode = str(saved.get("mode", "Vertical lane"))
    if default_mode not in {"Vertical lane", "Horizontal lane", "Custom bend"}:
        default_mode = "Vertical lane"

    saved_points = list(saved.get("points", []) or [])
    if len(saved_points) >= 3:
        mid_x = sum(float(p[0]) for p in saved_points[1:-1]) / max(1, len(saved_points) - 2)
        mid_y = sum(float(p[1]) for p in saved_points[1:-1]) / max(1, len(saved_points) - 2)
    else:
        mid_x = (start[0] + end[0]) / 2.0
        mid_y = (start[1] + end[1]) / 2.0

    default_x = int(round(max(0.0, min(100.0, 100.0 * mid_x / canvas_width))))
    default_y = int(round(max(0.0, min(100.0, 100.0 * mid_y / canvas_height))))

    left, right = st.columns(2, gap="small")
    with left:
        mode = st.selectbox(
            "Redraw style",
            ["Vertical lane", "Horizontal lane", "Custom bend"],
            index=["Vertical lane", "Horizontal lane", "Custom bend"].index(default_mode),
            key=f"manual_connection_mode_{worksheet_id}_{selected_edge_id}",
            help="Only the selected line is redrawn. Existing component ports remain fixed.",
        )
        x_percent = st.slider(
            "Move connection left / right",
            0,
            100,
            default_x,
            1,
            key=f"manual_connection_x_{worksheet_id}_{selected_edge_id}",
        )
    with right:
        y_percent = st.slider(
            "Move connection up / down",
            0,
            100,
            default_y,
            1,
            key=f"manual_connection_y_{worksheet_id}_{selected_edge_id}",
        )
        st.caption("Source and destination ports are locked. Only the line path is editable.")

    preview_points = _orthogonal_manual_route(
        start,
        end,
        mode=mode,
        x_percent=x_percent,
        y_percent=y_percent,
        canvas_width=canvas_width,
        canvas_height=canvas_height,
    )

    temporary_overrides = dict(saved_overrides)
    temporary_overrides[selected_edge_id] = {
        "mode": mode,
        "points": preview_points,
    }
    edited_preview = create_preview_png(
        diagram=diagram,
        assets_dir=ASSETS_DIR,
        manual_route_overrides=temporary_overrides,
    )
    st.image(edited_preview, caption="Manual connection preview", use_container_width=True)

    apply_col, reset_col, reset_all_col = st.columns(3, gap="small")
    with apply_col:
        if st.button(
            "Apply Connection Edit",
            type="primary",
            use_container_width=True,
            key=f"apply_connection_edit_{worksheet_id}_{selected_edge_id}",
        ):
            saved_overrides[selected_edge_id] = {
                "mode": mode,
                "points": preview_points,
            }
            st.session_state[overrides_key] = saved_overrides
            final_png = create_preview_png(
                diagram=diagram,
                assets_dir=ASSETS_DIR,
                manual_route_overrides=saved_overrides,
            )
            st.session_state["preview_png"] = final_png
            st.session_state["pdf_bytes"] = png_to_pdf(final_png)
            st.session_state.pop(_manual_edit_png_key(worksheet_id), None)
            if "worksheets" in st.session_state:
                persist_active_worksheet_state()
            add_diagram_to_ppt_session(int(worksheet_id), final_png)
            st.rerun()

    with reset_col:
        if st.button(
            "Reset This Line",
            use_container_width=True,
            key=f"reset_connection_edit_{worksheet_id}_{selected_edge_id}",
        ):
            saved_overrides.pop(selected_edge_id, None)
            st.session_state[overrides_key] = saved_overrides
            final_png = create_preview_png(
                diagram=diagram,
                assets_dir=ASSETS_DIR,
                manual_route_overrides=saved_overrides,
            )
            st.session_state["preview_png"] = final_png
            st.session_state["pdf_bytes"] = png_to_pdf(final_png)
            st.session_state.pop(_manual_edit_png_key(worksheet_id), None)
            if "worksheets" in st.session_state:
                persist_active_worksheet_state()
            add_diagram_to_ppt_session(int(worksheet_id), final_png)
            st.rerun()

    with reset_all_col:
        if st.button(
            "Reset All Lines",
            use_container_width=True,
            key=f"reset_all_connection_edits_{worksheet_id}",
        ):
            st.session_state.pop(overrides_key, None)
            final_png = create_preview_png(diagram=diagram, assets_dir=ASSETS_DIR)
            st.session_state["preview_png"] = final_png
            st.session_state["pdf_bytes"] = png_to_pdf(final_png)
            st.session_state.pop(_manual_edit_png_key(worksheet_id), None)
            if "worksheets" in st.session_state:
                persist_active_worksheet_state()
            add_diagram_to_ppt_session(int(worksheet_id), final_png)
            st.rerun()


def _apply_manual_diagram_image_edit(
    preview_png: bytes,
    *,
    rotation: int = 0,
    scale_percent: int = 100,
    offset_x_percent: int = 0,
    offset_y_percent: int = 0,
    crop_left_percent: int = 0,
    crop_right_percent: int = 0,
    crop_top_percent: int = 0,
    crop_bottom_percent: int = 0,
) -> bytes:
    """Create a non-destructive manually adjusted PNG for PPT use only.

    The original renderer output is never modified. With all default values this
    function returns the exact original PNG bytes.
    """
    if (
        int(rotation) % 360 == 0
        and int(scale_percent) == 100
        and int(offset_x_percent) == 0
        and int(offset_y_percent) == 0
        and int(crop_left_percent) == 0
        and int(crop_right_percent) == 0
        and int(crop_top_percent) == 0
        and int(crop_bottom_percent) == 0
    ):
        return preview_png

    source = Image.open(io.BytesIO(preview_png)).convert("RGBA")
    canvas_w, canvas_h = source.size

    left = int(round(canvas_w * max(0, min(40, int(crop_left_percent))) / 100.0))
    right = int(round(canvas_w * max(0, min(40, int(crop_right_percent))) / 100.0))
    top = int(round(canvas_h * max(0, min(40, int(crop_top_percent))) / 100.0))
    bottom = int(round(canvas_h * max(0, min(40, int(crop_bottom_percent))) / 100.0))

    x1 = min(left, max(0, canvas_w - 2))
    y1 = min(top, max(0, canvas_h - 2))
    x2 = max(x1 + 1, canvas_w - right)
    y2 = max(y1 + 1, canvas_h - bottom)
    edited = source.crop((x1, y1, x2, y2))

    angle = int(rotation) % 360
    if angle:
        edited = edited.rotate(-angle, expand=True, resample=Image.Resampling.BICUBIC)

    scale = max(0.25, min(2.0, float(scale_percent) / 100.0))
    fit_scale = min(canvas_w / max(edited.width, 1), canvas_h / max(edited.height, 1))
    target_scale = fit_scale * scale
    target_w = max(1, int(round(edited.width * target_scale)))
    target_h = max(1, int(round(edited.height * target_scale)))
    edited = edited.resize((target_w, target_h), Image.Resampling.LANCZOS)

    canvas = Image.new("RGBA", (canvas_w, canvas_h), (255, 255, 255, 255))
    offset_x = int(round(canvas_w * max(-40, min(40, int(offset_x_percent))) / 100.0))
    offset_y = int(round(canvas_h * max(-40, min(40, int(offset_y_percent))) / 100.0))
    paste_x = (canvas_w - target_w) // 2 + offset_x
    paste_y = (canvas_h - target_h) // 2 + offset_y
    canvas.alpha_composite(edited, (paste_x, paste_y))

    output = io.BytesIO()
    canvas.convert("RGB").save(output, format="PNG", optimize=True)
    return output.getvalue()


@st.dialog("Edit Generated Diagram", width="large")
def _show_manual_diagram_editor(preview_png: bytes, worksheet_id: int) -> None:
    """Edit only the image copy that is inserted into the combined PPT."""
    source_hash = hashlib.sha256(preview_png).hexdigest()
    source_key = _manual_edit_signature_key(worksheet_id)
    edited_key = _manual_edit_png_key(worksheet_id)

    # A newly generated diagram starts with fresh edit controls automatically.
    if st.session_state.get(source_key) != source_hash:
        st.session_state[source_key] = source_hash
        st.session_state.pop(edited_key, None)
        for suffix in (
            "rotation", "scale", "offset_x", "offset_y",
            "crop_left", "crop_right", "crop_top", "crop_bottom",
        ):
            st.session_state.pop(f"diagram_edit_{suffix}_{worksheet_id}", None)

    st.caption("Manual edits are non-destructive and are applied only to the PPT copy of this diagram.")

    control_left, control_right = st.columns(2, gap="small")
    with control_left:
        rotation = st.selectbox(
            "Rotation",
            [0, 90, 180, 270],
            format_func=lambda value: f"{value}°",
            key=f"diagram_edit_rotation_{worksheet_id}",
        )
        scale_percent = st.slider(
            "Scale", 50, 150, 100, 5,
            key=f"diagram_edit_scale_{worksheet_id}",
        )
        offset_x_percent = st.slider(
            "Move left / right", -30, 30, 0, 1,
            key=f"diagram_edit_offset_x_{worksheet_id}",
        )
        offset_y_percent = st.slider(
            "Move up / down", -30, 30, 0, 1,
            key=f"diagram_edit_offset_y_{worksheet_id}",
        )

    with control_right:
        crop_left_percent = st.slider(
            "Crop left", 0, 25, 0, 1,
            key=f"diagram_edit_crop_left_{worksheet_id}",
        )
        crop_right_percent = st.slider(
            "Crop right", 0, 25, 0, 1,
            key=f"diagram_edit_crop_right_{worksheet_id}",
        )
        crop_top_percent = st.slider(
            "Crop top", 0, 25, 0, 1,
            key=f"diagram_edit_crop_top_{worksheet_id}",
        )
        crop_bottom_percent = st.slider(
            "Crop bottom", 0, 25, 0, 1,
            key=f"diagram_edit_crop_bottom_{worksheet_id}",
        )

    edited_png = _apply_manual_diagram_image_edit(
        preview_png,
        rotation=rotation,
        scale_percent=scale_percent,
        offset_x_percent=offset_x_percent,
        offset_y_percent=offset_y_percent,
        crop_left_percent=crop_left_percent,
        crop_right_percent=crop_right_percent,
        crop_top_percent=crop_top_percent,
        crop_bottom_percent=crop_bottom_percent,
    )

    st.image(edited_png, caption="PPT image preview", use_container_width=True)

    apply_col, reset_col = st.columns(2, gap="small")
    with apply_col:
        if st.button(
            "Apply to PPT",
            key=f"apply_manual_diagram_edit_{worksheet_id}",
            type="primary",
            use_container_width=True,
        ):
            st.session_state[edited_key] = edited_png
            st.session_state[source_key] = source_hash
            add_diagram_to_ppt_session(int(worksheet_id), edited_png)
            st.rerun()

    with reset_col:
        if st.button(
            "Reset to Generated Image",
            key=f"reset_manual_diagram_edit_{worksheet_id}",
            use_container_width=True,
        ):
            st.session_state.pop(edited_key, None)
            add_diagram_to_ppt_session(int(worksheet_id), preview_png)
            for suffix in (
                "rotation", "scale", "offset_x", "offset_y",
                "crop_left", "crop_right", "crop_top", "crop_bottom",
            ):
                st.session_state.pop(f"diagram_edit_{suffix}_{worksheet_id}", None)
            st.rerun()


def _default_connection_transport_setting() -> dict:
    return {
        "mode": "automatic",
        "distance_km": 0.0,
        "significant_interference": False,
    }


def _sanitize_connection_transport_setting(raw: dict | None) -> dict:
    raw = dict(raw or {})
    mode = normalize_connection_mode(raw.get("mode", "automatic"))
    try:
        distance = max(0.0, float(raw.get("distance_km", 0.0) or 0.0))
    except (TypeError, ValueError):
        distance = 0.0
    return {
        "mode": mode,
        "distance_km": distance,
        "significant_interference": bool(raw.get("significant_interference", False)),
    }


def _active_connection_transport_key(worksheet_id: int) -> str:
    """Keep only the user's latest transport choice for future connections."""
    return f"active_connection_transport_{int(worksheet_id)}"


def _active_connection_transport_setting(
    worksheet_id: int,
    existing_settings: dict[str, dict] | None = None,
) -> dict:
    """Return the connection setting inherited by newly available relationships.

    Existing per-connection settings remain untouched.  This value is only the
    default for a connection candidate that did not exist before a new component
    or component instance was added.
    """
    state_key = _active_connection_transport_key(worksheet_id)
    saved = st.session_state.get(state_key)
    if isinstance(saved, dict):
        return _sanitize_connection_transport_setting(saved)

    # Backward-compatible initialization for worksheets created before this
    # functionality existed: infer a meaningful already-selected mode/distance,
    # otherwise retain the original Automatic/0 km default.
    for config in dict(existing_settings or {}).values():
        sanitized = _sanitize_connection_transport_setting(config)
        if (
            sanitized["mode"] != "automatic"
            or float(sanitized["distance_km"]) > 0.0
            or bool(sanitized["significant_interference"])
        ):
            st.session_state[state_key] = dict(sanitized)
            return sanitized

    default = _default_connection_transport_setting()
    st.session_state[state_key] = dict(default)
    return default


def build_connection_intent_df(
    selected_names: list[str],
    selected_connection_ids: list[str] | None = None,
    transport_settings: dict[str, dict] | None = None,
) -> tuple[pd.DataFrame, list]:
    """Build Allowed-vs-Required rows plus per-connection Wired/Wireless settings."""
    try:
        options = allowed_connection_options(selected_names)
    except Exception as exc:
        log_app_error("Build connection intent options", exc)
        show_friendly_error("loading the available connections")
        return pd.DataFrame(), []
    selected_set = set(selected_connection_ids or [])
    settings = dict(transport_settings or {})
    rows = []
    for index, option in enumerate(options, start=1):
        config = _sanitize_connection_transport_setting(
            settings.get(option.id, _default_connection_transport_setting())
        )
        resolved = resolve_connection_medium(
            config["mode"],
            config["distance_km"],
            config["significant_interference"],
        )
        rows.append(
            {
                "Connect": option.id in selected_set,
                "#": index,
                "From": option.source_label,
                "Direction": option.direction_label,
                "To": option.target_label,
                "Connection": option.connection_label,
                "Connection Type": config["mode"].title(),
                "Distance (km)": config["distance_km"],
                "Significant Interference": config["significant_interference"],
                "Resolved Type": resolved.title(),
                "Connection ID": option.id,
            }
        )
    return pd.DataFrame(rows), options


def connection_state_from_table(edited_table: pd.DataFrame) -> tuple[list[str], dict[str, dict]]:
    """Return explicit connection intent plus sanitized Wired/Wireless configuration."""
    selected: list[str] = []
    settings: dict[str, dict] = {}
    for _, row in edited_table.iterrows():
        connection_id = str(row.get("Connection ID", "")).strip()
        if not connection_id:
            continue
        if bool(row.get("Connect", False)):
            selected.append(connection_id)
        config = _sanitize_connection_transport_setting(
            {
                "mode": row.get("Connection Type", "Automatic"),
                "distance_km": row.get("Distance (km)", 0.0),
                "significant_interference": row.get("Significant Interference", False),
            }
        )
        settings[connection_id] = config
    return selected, settings


def _sanitize_inline_flow_meter_setting(raw: dict | None) -> dict:
    raw = dict(raw or {})
    placement = str(raw.get("placement", "automatic") or "automatic").strip().lower()
    if placement not in {"automatic", "source_side", "destination_side"}:
        placement = "automatic"
    attach_id = str(raw.get("attach_id", "") or "").strip()
    return {"placement": placement, "attach_id": attach_id}


def build_inline_flow_meter_df(
    selected_names: list[str],
    settings: dict[str, dict] | None = None,
) -> tuple[pd.DataFrame, dict[str, str], set[str]]:
    """Build placement controls for selected process auto-inline flow meters."""
    try:
        option_data = inline_flow_meter_placement_options(selected_names)
    except Exception as exc:
        log_app_error("Inline flow meter placement options", exc)
        show_friendly_error("loading flow meter placement options")
        return pd.DataFrame(), {"Automatic": ""}, set()
    current = dict(settings or {})
    anchor_label_to_id = {"Automatic": ""}
    for row in option_data.get("sources", []):
        anchor_label_to_id[f"Source: {row['label']}"] = row["id"]
    for row in option_data.get("tanks", []):
        anchor_label_to_id[f"Tank: {row['label']}"] = row["id"]
    id_to_anchor_label = {value: key for key, value in anchor_label_to_id.items() if value}

    rows = []
    valid_ids: set[str] = set()
    for index, meter in enumerate(option_data.get("meters", []), start=1):
        meter_id = meter["id"]
        valid_ids.add(meter_id)
        config = _sanitize_inline_flow_meter_setting(current.get(meter_id, {}))
        display_mode = {
            "automatic": "Automatic",
            "source_side": "Sump / Source Side",
            "destination_side": "OHT / Tank Side",
        }[config["placement"]]
        rows.append(
            {
                "#": index,
                "Flow Meter": meter["label"],
                "Placement": display_mode,
                "Attach To": id_to_anchor_label.get(config["attach_id"], "Automatic"),
                "Meter ID": meter_id,
            }
        )
    return pd.DataFrame(rows), anchor_label_to_id, valid_ids


def inline_flow_meter_state_from_table(
    edited_table: pd.DataFrame,
    anchor_label_to_id: dict[str, str],
) -> dict[str, dict]:
    placement_map = {
        "Automatic": "automatic",
        "Sump / Source Side": "source_side",
        "OHT / Tank Side": "destination_side",
    }
    settings: dict[str, dict] = {}
    for _, row in edited_table.iterrows():
        meter_id = str(row.get("Meter ID", "")).strip()
        if not meter_id:
            continue
        placement = placement_map.get(str(row.get("Placement", "Automatic")), "automatic")
        attach_label = str(row.get("Attach To", "Automatic"))
        settings[meter_id] = {
            "placement": placement,
            "attach_id": anchor_label_to_id.get(attach_label, ""),
        }
    return settings


def active_ppt_template_path() -> Path:
    """Return the project-fixed PPT template path."""
    return DEFAULT_PPT_TEMPLATE_PATH


def ppt_template_signature_for_hashing() -> str:
    """Return a signature for fixed-template PPT session inputs only."""
    return fixed_template_signature(
        DEFAULT_PPT_TEMPLATE_PATH,
        PPT_TEMPLATE_CONFIG_PATH,
    )


def _ppt_session_diagram_id(worksheet_id: int) -> str:
    return f"worksheet_{int(worksheet_id)}"


def _ordered_ppt_session_diagrams() -> list[tuple[str, bytes]]:
    """Return worksheet diagrams in the current worksheet order."""
    diagrams = st.session_state.get("ppt_session_diagrams", {}) or {}

    worksheet_order = [
        _ppt_session_diagram_id(int(sheet["id"]))
        for sheet in st.session_state.get("worksheets", []) or []
    ]

    # Backward-compatible fallback before worksheet state exists.
    if not worksheet_order:
        worksheet_order = list(
            st.session_state.get("ppt_session_order", []) or []
        )

    result: list[tuple[str, bytes]] = []
    for diagram_id in worksheet_order:
        data = diagrams.get(diagram_id)
        if not data:
            continue
        png = data.get("png") if isinstance(data, dict) else None
        if png:
            result.append((str(diagram_id), png))
    return result


def _ppt_price_pages_for_diagrams(
    diagrams: list[tuple[str, bytes]],
) -> dict[str, bytes]:
    """Build one Price Details page for each worksheet diagram in the same order."""
    worksheet_number_by_id = {
        int(sheet["id"]): worksheet_number
        for worksheet_number, sheet in enumerate(
            st.session_state.get("worksheets", []) or [],
            start=1,
        )
    }

    result: dict[str, bytes] = {}
    for diagram_id, _diagram_png in diagrams:
        match = re.fullmatch(r"worksheet_(\d+)", str(diagram_id))
        if not match:
            continue

        worksheet_id = int(match.group(1))
        worksheet_number = int(
            worksheet_number_by_id.get(worksheet_id, worksheet_id)
        )
        result[str(diagram_id)] = (
            _price_details_export_png_for_worksheet(
                worksheet_id,
                worksheet_number,
            )
        )

    return result


def _write_current_ppt_session_file(pptx_bytes: bytes | None = None) -> None:
    """Persist only the session output; the fixed template is never overwritten.

    Windows can temporarily lock ``final_diagram.pptx`` while it is open in
    PowerPoint, Explorer Preview, antivirus scanning, or another Streamlit
    rerun. Use a unique temporary file and retry the atomic replace briefly.
    If the destination remains locked, keep the current in-memory PPT session
    unchanged and skip the disk replacement instead of crashing the app.
    """
    data = pptx_bytes if pptx_bytes is not None else st.session_state.get("pptx_bytes")
    if not data:
        return

    PPT_SESSION_OUTPUT_DIR.mkdir(parents=True, exist_ok=True)

    temp_path: Path | None = None

    try:
        # A unique temp file prevents two Streamlit reruns from writing to the
        # same ``final_diagram.tmp.pptx`` at the same time.
        with tempfile.NamedTemporaryFile(
            mode="wb",
            prefix="final_diagram_",
            suffix=".tmp.pptx",
            dir=PPT_SESSION_OUTPUT_DIR,
            delete=False,
        ) as temp_file:
            temp_file.write(data)
            temp_file.flush()
            try:
                os.fsync(temp_file.fileno())
            except OSError:
                pass
            temp_path = Path(temp_file.name)

        last_error: PermissionError | None = None

        # Windows may release a PowerPoint/Explorer file lock a fraction of a
        # second after the previous operation. Retry only the replace step.
        for attempt in range(8):
            try:
                os.replace(str(temp_path), str(PPT_SESSION_OUTPUT_PATH))
                temp_path = None
                last_error = None
                break
            except PermissionError as exc:
                last_error = exc
                time.sleep(0.10 * (attempt + 1))

        if last_error is not None:
            # Do not break the Streamlit application merely because the desktop
            # PPT is open/locked. The newest PPT bytes remain in session state
            # and are still used by the existing Download PPT workflow.
            try:
                log_app_error("Write current PPT session file", last_error)
            except Exception:
                pass
            return

        try:
            st.session_state["ppt_session_file_mtime_ns"] = (
                PPT_SESSION_OUTPUT_PATH.stat().st_mtime_ns
            )
        except OSError:
            pass

    finally:
        # Remove an unused unique temp file after a failed/locked replacement.
        if temp_path is not None:
            try:
                temp_path.unlink(missing_ok=True)
            except OSError:
                pass


def _saved_worksheet_ppt_safe_stem(worksheet_id: int, worksheet_name: str) -> str:
    """Return one stable, filesystem-safe PPT stem for a worksheet."""
    worksheet_id = int(worksheet_id)
    cleaned_name = re.sub(
        r"[^A-Za-z0-9._ -]+",
        "_",
        str(worksheet_name or "").strip(),
    )
    cleaned_name = re.sub(r"\s+", "_", cleaned_name).strip(" ._")
    if not cleaned_name:
        cleaned_name = f"Worksheet_{worksheet_id}"
    return f"worksheet_{worksheet_id:03d}_{cleaned_name}"[:120]


def _saved_worksheet_ppt_sidecar_path(ppt_path: Path) -> Path:
    return ppt_path.with_name(
        f"{ppt_path.stem}{SAVED_WORKSHEET_PPT_STATE_SUFFIX}"
    )


def _saved_complete_project_ppt_safe_stem() -> str:
    """Return one stable filename stem for the complete current project."""
    project_name = str(
        st.session_state.get("welcome_page_display_name", "") or ""
    ).strip()
    cleaned_name = re.sub(
        r"[^A-Za-z0-9._ -]+",
        "_",
        project_name,
    )
    cleaned_name = re.sub(r"\s+", "_", cleaned_name).strip(" ._")
    if not cleaned_name:
        cleaned_name = "Complete_Project"
    return f"project_{cleaned_name}"[:120]


def _saved_ppt_is_complete_project(ppt_path: Path) -> bool:
    """Return True only for a valid complete-project library record."""
    state_path = _saved_worksheet_ppt_sidecar_path(ppt_path)
    if not ppt_path.is_file() or not state_path.is_file():
        return False

    try:
        with state_path.open("rb") as state_file:
            payload = pickle.load(state_file)
    except Exception:
        return False

    if not isinstance(payload, dict):
        return False
    if str(payload.get("kind", "") or "") != "complete_project":
        return False

    project_snapshot = payload.get("project")
    if not isinstance(project_snapshot, dict):
        return False

    saved_worksheets = project_snapshot.get("worksheets")
    saved_project_pages = project_snapshot.get("project_pages")
    if not isinstance(saved_worksheets, list) or not saved_worksheets:
        return False
    if not isinstance(saved_project_pages, list):
        return False

    return len(saved_project_pages) == 1 + (2 * len(saved_worksheets))


def _clear_saved_project_selection(
    worksheet_id: int,
    *,
    reset_loaded_state: bool = False,
    force_reset: bool = False,
) -> None:
    """Clear the active saved project and its loaded in-memory worksheet state."""
    selector_key = f"saved_worksheet_ppt_selector_{int(worksheet_id)}"
    if not force_reset and st.session_state.get(selector_key) not in (None, ""):
        st.session_state.pop("_saved_project_delete_target", None)
        return

    if not reset_loaded_state:
        st.session_state["_saved_project_selection_cleared_event"] = True
        return

    existing_ids: list[int] = []
    for sheet in list(st.session_state.get("worksheets", []) or []):
        try:
            existing_ids.append(int(sheet.get("id")))
        except (TypeError, ValueError):
            continue

    for current_id in existing_ids:
        for state_key in _saved_project_auxiliary_state_keys(current_id):
            st.session_state.pop(state_key, None)
        st.session_state.pop(
            f"_worksheet_render_bundle_cache_{current_id}",
            None,
        )

    for state_key in (
        "_pending_saved_project_restore",
        "_pending_worksheet_selector",
        "_pending_deleted_worksheet_ids",
        "_worksheet_dropdown_last_event",
        "worksheet_dropdown_double_click_rename",
        "_worksheet_page_flow_navigation_target",
        "_saved_project_selection_cleared_event",
        "_saved_project_delete_target",
        "_saved_ppt_load_message",
        "ppt_session_base_bytes",
        "ppt_session_diagrams",
        "ppt_session_order",
        "ppt_session_template_signature",
        "ppt_session_pptx_bytes",
        "pptx_bytes",
    ):
        st.session_state.pop(state_key, None)

    blank_worksheet = _new_worksheet(1, 1)
    st.session_state["worksheets"] = [blank_worksheet]
    st.session_state["active_worksheet_id"] = 1
    st.session_state["next_worksheet_id"] = 2
    st.session_state["worksheet_selector"] = 1
    st.session_state["selected_components"] = []
    st.session_state["selected_requirement_components"] = []
    st.session_state["selected_connections"] = []
    st.session_state["connection_transport_settings"] = {}
    st.session_state["inline_flow_meter_settings"] = {}
    st.session_state["_pending_welcome_page_display_name_reset"] = True
    st.session_state[_WORKSHEET_PAGE_FLOW_KEY] = _worksheet_page_flow_token(
        "worksheet", 1
    )
    st.session_state["_worksheet_page_flow_last_active_id"] = 1
    st.session_state["_reset_saved_worksheet_ppt_selector"] = True
    st.session_state.pop("_saved_project_delete_target", None)


def _saved_worksheet_ppt_files() -> list[Path]:
    """List saved project records newest first, with legacy fallback only."""
    if not SAVED_WORKSHEET_PPT_DIR.exists():
        return []

    files: list[Path] = []
    for ppt_path in SAVED_WORKSHEET_PPT_DIR.glob("*.pptx"):
        if not ppt_path.is_file():
            continue
        # Only expose files that also have the app-owned editable state sidecar.
        if not _saved_worksheet_ppt_sidecar_path(ppt_path).exists():
            continue
        files.append(ppt_path)

    def _mtime(path: Path) -> int:
        try:
            return int(path.stat().st_mtime_ns)
        except OSError:
            return 0

    files = sorted(files, key=_mtime, reverse=True)

    # Complete-project saves are authoritative.  Once at least one exists, do
    # not mix the older worksheet-only records into the same reopen workflow;
    # otherwise a user can accidentally reload worksheet_001_* and see only one
    # worksheet even though the project save itself contains the full section.
    project_files = [
        ppt_path
        for ppt_path in files
        if _saved_ppt_is_complete_project(ppt_path)
    ]
    return project_files if project_files else files


def _delete_saved_worksheet_ppt(ppt_filename: str) -> tuple[bool, str]:
    """Delete exactly one saved project PPT and its editable-state sidecar."""
    filename = Path(str(ppt_filename or "")).name
    if not filename or Path(filename).suffix.lower() != ".pptx":
        return False, "No saved project was selected."

    ppt_path = SAVED_WORKSHEET_PPT_DIR / filename
    state_path = _saved_worksheet_ppt_sidecar_path(ppt_path)

    if not ppt_path.is_file() and not state_path.is_file():
        return False, "The selected saved project is no longer available."

    try:
        # A saved-project record consists only of these two app-owned files.
        # Delete both and leave every other saved-project record untouched.
        ppt_path.unlink(missing_ok=True)
        state_path.unlink(missing_ok=True)
    except Exception as exc:
        log_app_error("Delete saved project PPT", exc)
        return False, "Could not delete the selected saved project."

    if ppt_path.exists() or state_path.exists():
        return False, "Could not completely delete the selected saved project."

    return True, f"Deleted {filename}"


def _saved_project_auxiliary_state_keys(worksheet_id: int) -> tuple[str, ...]:
    """Return worksheet-scoped state that must survive a complete project save."""
    worksheet_id = int(worksheet_id)
    return (
        _worksheet_component_count_adjustments_key(worksheet_id),
        _connection_history_key(worksheet_id),
        _connection_history_index_key(worksheet_id),
        _editor_history_key(worksheet_id),
        _editor_history_index_key(worksheet_id),
        _manual_edit_png_key(worksheet_id),
        _manual_edit_signature_key(worksheet_id),
        _manual_connection_overrides_key(worksheet_id),
        _deleted_connection_ids_key(worksheet_id),
        _manual_component_overrides_key(worksheet_id),
        _manual_connection_source_key(worksheet_id),
        _active_connection_transport_key(worksheet_id),
        _worksheet_render_sync_pending_key(worksheet_id),
        f"_ppt_sync_pending_{worksheet_id}",
        f"price_details_adjustment_{worksheet_id}",
        f"price_details_components_{worksheet_id}",
        f"_auto_wireless_components_{worksheet_id}",
        f"_auto_requested_connection_components_{worksheet_id}",
        f"_auto_trained_requirement_components_{worksheet_id}",
        f"pending_component_connection_source_{worksheet_id}",
        f"image_orientation_{worksheet_id}",
        f"sketch_upload_generation_{worksheet_id}",
    )


def _worksheet_snapshot_for_saved_ppt(worksheet_id: int) -> tuple[dict, dict]:
    """Capture one worksheet and its existing worksheet-scoped state."""
    worksheet_id = int(worksheet_id)
    source_sheet = None
    for sheet in list(st.session_state.get("worksheets", []) or []):
        if int(sheet.get("id", -1)) == worksheet_id:
            source_sheet = sheet
            break

    if source_sheet is None:
        source_sheet = _new_worksheet(worksheet_id, worksheet_id)

    try:
        snapshot = copy.deepcopy(source_sheet)
    except Exception:
        snapshot = dict(source_sheet)

    # The active worksheet still uses the application's existing legacy state
    # keys while it is being edited. Overlay those values into the snapshot so a
    # save always captures the exact current edit, even before another rerun.
    if int(st.session_state.get("active_worksheet_id", -1)) == worksheet_id:
        snapshot["selected_components"] = list(
            st.session_state.get("selected_components", []) or []
        )
        snapshot["selected_requirement_components"] = _sanitize_requirement_components(
            st.session_state.get("selected_requirement_components", []) or []
        )
        snapshot["selected_connections"] = list(
            st.session_state.get("selected_connections", []) or []
        )
        snapshot["connection_transport_settings"] = dict(
            st.session_state.get("connection_transport_settings", {}) or {}
        )
        snapshot["inline_flow_meter_settings"] = dict(
            st.session_state.get("inline_flow_meter_settings", {}) or {}
        )
        for output_key in WORKSHEET_OUTPUT_KEYS:
            snapshot[output_key] = st.session_state.get(output_key)

    auxiliary_state: dict = {}
    for state_key in _saved_project_auxiliary_state_keys(worksheet_id):
        if state_key not in st.session_state:
            continue
        try:
            auxiliary_state[state_key] = copy.deepcopy(st.session_state[state_key])
        except Exception:
            auxiliary_state[state_key] = st.session_state[state_key]

    return snapshot, auxiliary_state


def _project_snapshot_for_saved_ppt(active_worksheet_id: int) -> dict:
    """Capture the complete current project without changing any UI behavior."""
    active_worksheet_id = int(active_worksheet_id)

    if st.session_state.get("worksheets"):
        persist_active_worksheet_state()

    worksheet_snapshots: list[dict] = []
    all_auxiliary_state: dict = {}

    for source_sheet in list(st.session_state.get("worksheets", []) or []):
        try:
            worksheet_id = int(source_sheet.get("id"))
        except (TypeError, ValueError):
            continue

        worksheet_snapshot, worksheet_auxiliary_state = (
            _worksheet_snapshot_for_saved_ppt(worksheet_id)
        )
        worksheet_snapshots.append(worksheet_snapshot)
        all_auxiliary_state.update(worksheet_auxiliary_state)

    default_next_worksheet_id = (
        max(
            [
                int(sheet.get("id", 0) or 0)
                for sheet in worksheet_snapshots
            ]
            + [0]
        )
        + 1
    )

    saved_page_token = str(
        st.session_state.get(
            _WORKSHEET_PAGE_FLOW_KEY,
            _worksheet_page_flow_token(
                "worksheet",
                active_worksheet_id,
            ),
        )
        or ""
    ).strip().lower()

    saved_global_state = {
        "welcome_page_display_name": st.session_state.get(
            "welcome_page_display_name",
            "",
        ),
        "active_worksheet_id": active_worksheet_id,
        "next_worksheet_id": st.session_state.get(
            "next_worksheet_id",
            default_next_worksheet_id,
        ),
        _WORKSHEET_PAGE_FLOW_KEY: saved_page_token,
        "_worksheet_page_flow_last_active_id": st.session_state.get(
            "_worksheet_page_flow_last_active_id",
            active_worksheet_id,
        ),
    }

    # Save the complete page/sheet sequence explicitly instead of relying on the
    # currently active worksheet to recreate it later.  Price Details remains the
    # existing calculated page; only its worksheet-specific state is persisted.
    page_sequence: list[dict] = [
        {
            "token": "welcome",
            "page_type": "welcome",
            "worksheet_id": None,
        }
    ]
    price_details: dict[int, dict] = {}

    for worksheet_snapshot in worksheet_snapshots:
        worksheet_id = int(worksheet_snapshot.get("id"))
        worksheet_token = _worksheet_page_flow_token(
            "worksheet",
            worksheet_id,
        )
        price_token = _worksheet_page_flow_token(
            "price",
            worksheet_id,
        )

        page_sequence.append(
            {
                "token": worksheet_token,
                "page_type": "worksheet",
                "worksheet_id": worksheet_id,
            }
        )
        page_sequence.append(
            {
                "token": price_token,
                "page_type": "price",
                "worksheet_id": worksheet_id,
            }
        )

        price_components_key = f"price_details_components_{worksheet_id}"
        price_adjustment_key = f"price_details_adjustment_{worksheet_id}"

        if price_components_key in all_auxiliary_state:
            price_components = list(
                all_auxiliary_state.get(price_components_key, []) or []
            )
        else:
            price_components = list(
                worksheet_snapshot.get("selected_components", []) or []
            )

        price_adjustment = dict(
            all_auxiliary_state.get(price_adjustment_key, {}) or {}
        )

        price_details[worksheet_id] = {
            "components": price_components,
            "adjustment": price_adjustment,
        }

    # Store the complete project as actual ordered page records as well as the
    # existing worksheet collections.  Restore can therefore reconstruct the
    # exact section directly rather than inferring pages from the active sheet.
    complete_project_pages: list[dict] = [
        {
            "token": "welcome",
            "page_type": "welcome",
            "worksheet_id": None,
            "welcome_state": {
                "display_name": str(
                    saved_global_state.get("welcome_page_display_name", "") or ""
                ),
            },
        }
    ]
    for worksheet_snapshot in worksheet_snapshots:
        worksheet_id = int(worksheet_snapshot.get("id"))
        complete_project_pages.append(
            {
                "token": _worksheet_page_flow_token(
                    "worksheet",
                    worksheet_id,
                ),
                "page_type": "worksheet",
                "worksheet_id": worksheet_id,
                "worksheet": copy.deepcopy(worksheet_snapshot),
            }
        )
        complete_project_pages.append(
            {
                "token": _worksheet_page_flow_token(
                    "price",
                    worksheet_id,
                ),
                "page_type": "price",
                "worksheet_id": worksheet_id,
                "price_details": copy.deepcopy(
                    price_details.get(worksheet_id, {})
                ),
            }
        )

    try:
        worksheet_snapshots = copy.deepcopy(worksheet_snapshots)
    except Exception:
        pass
    try:
        all_auxiliary_state = copy.deepcopy(all_auxiliary_state)
    except Exception:
        pass
    try:
        saved_global_state = copy.deepcopy(saved_global_state)
    except Exception:
        pass
    try:
        page_sequence = copy.deepcopy(page_sequence)
    except Exception:
        pass
    try:
        price_details = copy.deepcopy(price_details)
    except Exception:
        pass

    return {
        "worksheets": worksheet_snapshots,
        # Authoritative worksheet creation/display order.
        "worksheet_order": [
            int(sheet.get("id"))
            for sheet in worksheet_snapshots
        ],
        "worksheet_count": len(worksheet_snapshots),
        # Authoritative full project page order:
        # Welcome -> Worksheet 1 -> Price 1 -> Worksheet 2 -> Price 2 -> ...
        "page_sequence": page_sequence,
        "page_count": len(page_sequence),
        # Exact ordered page records.  This is the authoritative complete-project
        # representation for new saves.
        "project_pages": complete_project_pages,
        # Explicit per-worksheet Price Details state.
        "price_details": price_details,
        "auxiliary_state": all_auxiliary_state,
        "global_state": saved_global_state,
    }


def _apply_pending_saved_project_restore_if_needed() -> None:
    """Restore a complete saved project before any worksheet widgets are built."""
    pending_restore = st.session_state.pop(
        "_pending_saved_project_restore",
        None,
    )
    if not isinstance(pending_restore, dict):
        return

    project_snapshot = pending_restore.get("project")
    if not isinstance(project_snapshot, dict):
        return

    # Version 5+ complete-project saves carry the actual ordered page records.
    # Prefer those records so every Worksheet and matching Price Details page is
    # restored from what was saved, not reconstructed from whichever sheet was
    # active when Save was clicked.
    saved_project_pages = project_snapshot.get("project_pages")
    saved_worksheets = project_snapshot.get("worksheets")
    if isinstance(saved_project_pages, list) and saved_project_pages:
        page_worksheets: list[dict] = []
        page_prices: dict[int, dict] = {}
        expected_price_for: int | None = None
        project_pages_valid = True
        welcome_seen = False

        for page_index, page_record in enumerate(saved_project_pages):
            if not isinstance(page_record, dict):
                project_pages_valid = False
                break

            page_type = str(
                page_record.get("page_type", "") or ""
            ).strip().lower()

            if page_index == 0:
                if page_type != "welcome":
                    project_pages_valid = False
                    break
                welcome_seen = True
                continue

            try:
                page_worksheet_id = int(
                    page_record.get("worksheet_id")
                )
            except (TypeError, ValueError):
                project_pages_valid = False
                break

            if page_type == "worksheet":
                if expected_price_for is not None:
                    project_pages_valid = False
                    break
                worksheet_state = page_record.get("worksheet")
                if not isinstance(worksheet_state, dict):
                    project_pages_valid = False
                    break
                worksheet_state = copy.deepcopy(worksheet_state)
                worksheet_state["id"] = page_worksheet_id
                page_worksheets.append(worksheet_state)
                expected_price_for = page_worksheet_id
                continue

            if page_type == "price":
                if expected_price_for != page_worksheet_id:
                    project_pages_valid = False
                    break
                price_state = page_record.get("price_details", {})
                if not isinstance(price_state, dict):
                    project_pages_valid = False
                    break
                page_prices[page_worksheet_id] = copy.deepcopy(
                    price_state
                )
                expected_price_for = None
                continue

            project_pages_valid = False
            break

        if (
            project_pages_valid
            and welcome_seen
            and expected_price_for is None
            and page_worksheets
            and len(page_prices) == len(page_worksheets)
            and len(saved_project_pages)
            == 1 + (2 * len(page_worksheets))
        ):
            saved_worksheets = page_worksheets
            # Make the page-record price data authoritative for this restore.
            project_snapshot["price_details"] = page_prices
            project_snapshot["worksheet_order"] = [
                int(sheet.get("id"))
                for sheet in page_worksheets
            ]
            project_snapshot["page_sequence"] = [
                {
                    "token": str(page.get("token", "") or ""),
                    "page_type": str(
                        page.get("page_type", "") or ""
                    ),
                    "worksheet_id": page.get("worksheet_id"),
                }
                for page in saved_project_pages
            ]

    if not isinstance(saved_worksheets, list) or not saved_worksheets:
        return

    try:
        restored_worksheets = copy.deepcopy(saved_worksheets)
    except Exception:
        restored_worksheets = list(saved_worksheets)

    restored_ids: list[int] = []
    worksheet_by_id: dict[int, dict] = {}
    for sheet in restored_worksheets:
        if not isinstance(sheet, dict):
            return
        try:
            worksheet_id = int(sheet.get("id"))
        except (TypeError, ValueError):
            return
        if worksheet_id in restored_ids:
            return
        restored_ids.append(worksheet_id)
        worksheet_by_id[worksheet_id] = sheet

    # Use the saved page manifest as the first authority for worksheet order.
    # A valid complete-project manifest is always:
    # Welcome -> Worksheet N -> Price N -> Worksheet N+1 -> Price N+1 -> ...
    saved_page_sequence = project_snapshot.get("page_sequence")
    page_order_ids: list[int] = []
    valid_saved_page_sequence = False
    if isinstance(saved_page_sequence, list) and saved_page_sequence:
        normalized_pages: list[tuple[str, int | None, str]] = []
        for page in saved_page_sequence:
            if not isinstance(page, dict):
                normalized_pages = []
                break
            page_type = str(page.get("page_type", "") or "").strip().lower()
            token = str(page.get("token", "") or "").strip().lower()
            raw_worksheet_id = page.get("worksheet_id")
            if page_type == "welcome":
                normalized_pages.append(("welcome", None, token or "welcome"))
                continue
            if page_type not in {"worksheet", "price"}:
                normalized_pages = []
                break
            try:
                page_worksheet_id = int(raw_worksheet_id)
            except (TypeError, ValueError):
                normalized_pages = []
                break
            normalized_pages.append((page_type, page_worksheet_id, token))

        expected_page_count = 1 + (2 * len(restored_ids))
        if (
            len(normalized_pages) == expected_page_count
            and normalized_pages[0][0] == "welcome"
        ):
            candidate_order: list[int] = []
            page_index = 1
            manifest_valid = True
            while page_index < len(normalized_pages):
                worksheet_page = normalized_pages[page_index]
                price_page = normalized_pages[page_index + 1]
                if (
                    worksheet_page[0] != "worksheet"
                    or price_page[0] != "price"
                    or worksheet_page[1] != price_page[1]
                ):
                    manifest_valid = False
                    break
                candidate_order.append(int(worksheet_page[1]))
                page_index += 2

            if (
                manifest_valid
                and len(candidate_order) == len(restored_ids)
                and len(set(candidate_order)) == len(candidate_order)
                and set(candidate_order) == set(restored_ids)
            ):
                page_order_ids = candidate_order
                valid_saved_page_sequence = True

    # Backward compatibility for earlier complete-project saves that did not yet
    # carry the explicit page manifest.
    if not page_order_ids:
        saved_order = project_snapshot.get("worksheet_order")
        if isinstance(saved_order, (list, tuple)) and saved_order:
            try:
                normalized_order = [int(value) for value in saved_order]
            except (TypeError, ValueError):
                normalized_order = []

            if (
                len(normalized_order) == len(restored_ids)
                and len(set(normalized_order)) == len(normalized_order)
                and set(normalized_order) == set(restored_ids)
            ):
                page_order_ids = normalized_order

    if not page_order_ids:
        page_order_ids = list(restored_ids)

    restored_worksheets = [
        worksheet_by_id[worksheet_id]
        for worksheet_id in page_order_ids
    ]
    restored_ids = list(page_order_ids)

    # Discard only pending navigation/delete events from the previously open
    # project. Without this, a queued selector action can immediately override the
    # restored project on the same rerun.
    st.session_state.pop("_pending_worksheet_selector", None)
    st.session_state.pop("_pending_deleted_worksheet_ids", None)
    st.session_state.pop("_worksheet_dropdown_last_event", None)
    st.session_state.pop("worksheet_dropdown_double_click_rename", None)

    existing_ids: list[int] = []
    for sheet in list(st.session_state.get("worksheets", []) or []):
        try:
            existing_ids.append(int(sheet.get("id")))
        except (TypeError, ValueError):
            continue

    # Remove only worksheet-scoped state belonging to the current/restored
    # project so stale data from the previously open project cannot leak in.
    for worksheet_id in set(existing_ids + restored_ids):
        for state_key in _saved_project_auxiliary_state_keys(worksheet_id):
            st.session_state.pop(state_key, None)

        st.session_state.pop(
            f"_worksheet_render_bundle_cache_{worksheet_id}",
            None,
        )
        st.session_state[
            f"connection_picker_generation_{worksheet_id}"
        ] = int(
            st.session_state.get(
                f"connection_picker_generation_{worksheet_id}",
                0,
            )
            or 0
        ) + 1

        for state_key in list(st.session_state.keys()):
            if str(state_key).startswith(
                f"required_connection_compact_{worksheet_id}_"
            ) or str(state_key).startswith(
                f"connection_config_target_{worksheet_id}_"
            ):
                st.session_state.pop(state_key, None)

    saved_auxiliary_state = project_snapshot.get(
        "auxiliary_state",
        {},
    )
    if isinstance(saved_auxiliary_state, dict):
        allowed_auxiliary_keys = {
            state_key
            for worksheet_id in restored_ids
            for state_key in _saved_project_auxiliary_state_keys(
                worksheet_id
            )
        }
        for state_key, state_value in saved_auxiliary_state.items():
            if state_key not in allowed_auxiliary_keys:
                continue
            try:
                st.session_state[state_key] = copy.deepcopy(state_value)
            except Exception:
                st.session_state[state_key] = state_value

    # Version 4+ snapshots store every Price Details page explicitly. Restore this
    # after the generic auxiliary state so each worksheet's pricing page is exact.
    saved_price_details = project_snapshot.get("price_details", {})
    if isinstance(saved_price_details, dict):
        for worksheet_id in restored_ids:
            price_state = (
                saved_price_details.get(worksheet_id)
                or saved_price_details.get(str(worksheet_id))
            )
            if not isinstance(price_state, dict):
                continue

            price_components_key = f"price_details_components_{worksheet_id}"
            price_adjustment_key = f"price_details_adjustment_{worksheet_id}"

            if "components" in price_state:
                try:
                    st.session_state[price_components_key] = copy.deepcopy(
                        list(price_state.get("components", []) or [])
                    )
                except Exception:
                    st.session_state[price_components_key] = list(
                        price_state.get("components", []) or []
                    )

            if "adjustment" in price_state:
                try:
                    st.session_state[price_adjustment_key] = copy.deepcopy(
                        dict(price_state.get("adjustment", {}) or {})
                    )
                except Exception:
                    st.session_state[price_adjustment_key] = dict(
                        price_state.get("adjustment", {}) or {}
                    )

    st.session_state["worksheets"] = restored_worksheets

    saved_global_state = project_snapshot.get("global_state", {})
    if not isinstance(saved_global_state, dict):
        saved_global_state = {}

    try:
        active_worksheet_id = int(
            saved_global_state.get(
                "active_worksheet_id",
                restored_ids[0],
            )
        )
    except (TypeError, ValueError):
        active_worksheet_id = restored_ids[0]

    if active_worksheet_id not in restored_ids:
        active_worksheet_id = restored_ids[0]

    try:
        next_worksheet_id = int(
            saved_global_state.get(
                "next_worksheet_id",
                max(restored_ids) + 1,
            )
        )
    except (TypeError, ValueError):
        next_worksheet_id = max(restored_ids) + 1

    next_worksheet_id = max(
        next_worksheet_id,
        max(restored_ids) + 1,
    )

    # Restore the saved page itself only if it still belongs to the complete page
    # manifest. This preserves Welcome/Worksheet/Price position without dropping
    # any page from the project.
    saved_page_token = str(
        saved_global_state.get(
            _WORKSHEET_PAGE_FLOW_KEY,
            "",
        )
        or ""
    ).strip().lower()

    valid_page_tokens = {"welcome"}
    for worksheet_id in restored_ids:
        valid_page_tokens.add(
            _worksheet_page_flow_token("worksheet", worksheet_id)
        )
        valid_page_tokens.add(
            _worksheet_page_flow_token("price", worksheet_id)
        )

    if saved_page_token not in valid_page_tokens:
        saved_page_token = _worksheet_page_flow_token(
            "worksheet",
            active_worksheet_id,
        )

    saved_page_type, saved_page_worksheet_id = (
        _parse_worksheet_page_flow_token(saved_page_token)
    )
    if (
        saved_page_type in {"worksheet", "price"}
        and saved_page_worksheet_id in restored_ids
    ):
        active_worksheet_id = int(saved_page_worksheet_id)

    st.session_state["active_worksheet_id"] = active_worksheet_id
    st.session_state["worksheet_selector"] = active_worksheet_id
    st.session_state["next_worksheet_id"] = next_worksheet_id
    st.session_state["welcome_page_display_name"] = str(
        saved_global_state.get(
            "welcome_page_display_name",
            "",
        )
        or ""
    )
    st.session_state[_WORKSHEET_PAGE_FLOW_KEY] = saved_page_token
    st.session_state[
        "_worksheet_page_flow_last_active_id"
    ] = active_worksheet_id

    saved_ppt_state = pending_restore.get("ppt_state", {})
    if isinstance(saved_ppt_state, dict):
        for state_key in (
            "ppt_session_base_bytes",
            "ppt_session_diagrams",
            "ppt_session_order",
            "ppt_session_template_signature",
        ):
            if state_key in saved_ppt_state:
                try:
                    st.session_state[state_key] = copy.deepcopy(
                        saved_ppt_state[state_key]
                    )
                except Exception:
                    st.session_state[state_key] = saved_ppt_state[state_key]

    ppt_bytes = bytes(pending_restore.get("ppt_bytes") or b"")
    if ppt_bytes:
        st.session_state["ppt_session_pptx_bytes"] = ppt_bytes
        st.session_state["pptx_bytes"] = ppt_bytes
        _write_current_ppt_session_file(ppt_bytes)

def _materialize_complete_project_ppt_for_save() -> bytes:
    """Build the saved PPT from every current worksheet in worksheet order.

    Normal worksheet editing intentionally defers expensive PNG/PPT work. Save is
    the explicit persistence boundary, so it must flush those deferred worksheet
    visuals before the library entry is written. This affects Save only.
    """
    if st.session_state.get("worksheets"):
        persist_active_worksheet_state()

    ensure_ppt_session_state()

    worksheets = list(st.session_state.get("worksheets", []) or [])
    complete_diagrams: dict[str, dict] = {}
    complete_order: list[str] = []

    active_worksheet_id = int(
        st.session_state.get("active_worksheet_id", 0) or 0
    )

    for sheet in worksheets:
        if not isinstance(sheet, dict):
            continue

        try:
            worksheet_id = int(sheet.get("id"))
        except (TypeError, ValueError):
            continue

        diagram = sheet.get("diagram")
        preview_png = sheet.get("preview_png")
        pending_render_key = _worksheet_render_sync_pending_key(worksheet_id)

        # Preserve an explicitly applied PPT image edit exactly as the existing
        # PPT workflow does. Otherwise materialize a deferred worksheet render
        # from that worksheet's own saved diagram/edit state.
        manual_ppt_png = st.session_state.get(
            _manual_edit_png_key(worksheet_id)
        )
        if manual_ppt_png:
            preview_png = manual_ppt_png
        elif (
            diagram is not None
            and (
                st.session_state.get(pending_render_key)
                or not preview_png
            )
        ):
            try:
                preview_png = create_preview_png(
                    diagram=diagram,
                    assets_dir=ASSETS_DIR,
                    manual_route_overrides=st.session_state.get(
                        _manual_connection_overrides_key(worksheet_id),
                        {},
                    )
                    or {},
                    manual_component_overrides=st.session_state.get(
                        _manual_component_overrides_key(worksheet_id),
                        {},
                    )
                    or {},
                )
            except Exception as exc:
                log_app_error(
                    f"Materialize worksheet {worksheet_id} for project save",
                    exc,
                )
                preview_png = sheet.get("preview_png")

            if preview_png:
                sheet["preview_png"] = preview_png
                try:
                    sheet["pdf_bytes"] = png_to_pdf(preview_png)
                except Exception as exc:
                    log_app_error(
                        f"Materialize worksheet {worksheet_id} PDF for project save",
                        exc,
                    )

                if worksheet_id == active_worksheet_id:
                    st.session_state["preview_png"] = preview_png
                    if sheet.get("pdf_bytes") is not None:
                        st.session_state["pdf_bytes"] = sheet.get("pdf_bytes")

        if not preview_png:
            continue

        try:
            preview_bytes = bytes(preview_png)
        except Exception:
            continue

        if not preview_bytes:
            continue

        diagram_id = _ppt_session_diagram_id(worksheet_id)
        complete_diagrams[diagram_id] = {
            "worksheet_id": worksheet_id,
            "png": preview_bytes,
            "hash": hashlib.sha256(preview_bytes).hexdigest(),
        }
        complete_order.append(diagram_id)

        # The deferred render/PPT flags have now been fully materialized by Save.
        st.session_state.pop(pending_render_key, None)
        st.session_state.pop(f"_ppt_sync_pending_{worksheet_id}", None)

    st.session_state["ppt_session_diagrams"] = complete_diagrams
    st.session_state["ppt_session_order"] = complete_order

    ordered_diagrams = [
        (
            diagram_id,
            complete_diagrams[diagram_id]["png"],
        )
        for diagram_id in complete_order
        if diagram_id in complete_diagrams
    ]

    base_bytes = st.session_state.get("ppt_session_base_bytes")
    if not base_bytes:
        base_bytes = initialize_combined_ppt_session(
            template_path=DEFAULT_PPT_TEMPLATE_PATH,
            config_path=PPT_TEMPLATE_CONFIG_PATH,
        )
        st.session_state["ppt_session_base_bytes"] = base_bytes

    combined = generate_combined_ppt_from_session(
        session_base_ppt=base_bytes,
        diagrams=ordered_diagrams,
        config_path=PPT_TEMPLATE_CONFIG_PATH,
        price_pages=_ppt_price_pages_for_diagrams(ordered_diagrams),
    )

    st.session_state["ppt_session_pptx_bytes"] = combined
    st.session_state["pptx_bytes"] = combined
    _write_current_ppt_session_file(combined)

    # Persist any worksheet preview/PDF that was materialized above before the
    # complete project snapshot is serialized into the library sidecar.
    if st.session_state.get("worksheets"):
        persist_active_worksheet_state()

    return bytes(combined or b"")


def _save_current_worksheet_ppt_to_library(
    worksheet_id: int,
    pptx_bytes: bytes | bytearray | None,
    *,
    project_snapshot: dict | None = None,
) -> Path | None:
    """Persist the PPT plus the complete project/session required to reopen it."""
    data = bytes(pptx_bytes or b"")
    if not data:
        return None

    worksheet_id = int(worksheet_id)
    if not isinstance(project_snapshot, dict):
        project_snapshot = _project_snapshot_for_saved_ppt(worksheet_id)

    worksheet_snapshot = next(
        (
            sheet
            for sheet in list(project_snapshot.get("worksheets", []) or [])
            if int(sheet.get("id", -1)) == worksheet_id
        ),
        None,
    )
    if not isinstance(worksheet_snapshot, dict):
        worksheet_snapshot, _ = _worksheet_snapshot_for_saved_ppt(
            worksheet_id
        )

    active_auxiliary_keys = set(
        _saved_project_auxiliary_state_keys(worksheet_id)
    )
    auxiliary_state = {
        state_key: state_value
        for state_key, state_value in dict(
            project_snapshot.get("auxiliary_state", {}) or {}
        ).items()
        if state_key in active_auxiliary_keys
    }

    worksheet_name = str(
        worksheet_snapshot.get("name") or f"Worksheet {worksheet_id}"
    ).strip()

    SAVED_WORKSHEET_PPT_DIR.mkdir(parents=True, exist_ok=True)
    stem = _saved_worksheet_ppt_safe_stem(worksheet_id, worksheet_name)
    ppt_path = SAVED_WORKSHEET_PPT_DIR / f"{stem}.pptx"
    state_path = _saved_worksheet_ppt_sidecar_path(ppt_path)

    # Keep one current library entry per worksheet ID.  If the worksheet was
    # renamed, remove only that worksheet's previous saved-library filename.
    id_prefix = f"worksheet_{worksheet_id:03d}_"
    for existing_ppt in SAVED_WORKSHEET_PPT_DIR.glob(f"{id_prefix}*.pptx"):
        if existing_ppt == ppt_path:
            continue
        try:
            existing_ppt.unlink(missing_ok=True)
            _saved_worksheet_ppt_sidecar_path(existing_ppt).unlink(missing_ok=True)
        except OSError:
            pass

    snapshot_payload = {
        "version": 4,
        # Keep the original single-worksheet fields for backward compatibility
        # with the existing saved-PPT workflow, while the project field is now
        # the authoritative complete-session snapshot.
        "worksheet": worksheet_snapshot,
        "auxiliary_state": auxiliary_state,
        "project": project_snapshot,
        "ppt_state": {
            "ppt_session_base_bytes": st.session_state.get(
                "ppt_session_base_bytes"
            ),
            "ppt_session_diagrams": st.session_state.get(
                "ppt_session_diagrams", {}
            ),
            "ppt_session_order": st.session_state.get(
                "ppt_session_order", []
            ),
            "ppt_session_template_signature": st.session_state.get(
                "ppt_session_template_signature"
            ),
        },
    }

    ppt_tmp: Path | None = None
    state_tmp: Path | None = None
    try:
        with tempfile.NamedTemporaryFile(
            mode="wb",
            prefix=f"{stem}_",
            suffix=".tmp.pptx",
            dir=SAVED_WORKSHEET_PPT_DIR,
            delete=False,
        ) as temp_ppt:
            temp_ppt.write(data)
            temp_ppt.flush()
            ppt_tmp = Path(temp_ppt.name)

        with tempfile.NamedTemporaryFile(
            mode="wb",
            prefix=f"{stem}_",
            suffix=".tmp.state",
            dir=SAVED_WORKSHEET_PPT_DIR,
            delete=False,
        ) as temp_state:
            pickle.dump(snapshot_payload, temp_state, protocol=pickle.HIGHEST_PROTOCOL)
            temp_state.flush()
            state_tmp = Path(temp_state.name)

        os.replace(str(ppt_tmp), str(ppt_path))
        ppt_tmp = None
        os.replace(str(state_tmp), str(state_path))
        state_tmp = None
        return ppt_path
    except Exception as exc:
        log_app_error("Save worksheet PPT library entry", exc)
        return None
    finally:
        for temp_path in (ppt_tmp, state_tmp):
            if temp_path is None:
                continue
            try:
                temp_path.unlink(missing_ok=True)
            except OSError:
                pass


def _save_complete_project_ppt_to_library(
    pptx_bytes: bytes | bytearray | None,
    preferred_worksheet_id: int,
) -> Path | None:
    """Save the entire current project as one authoritative library record."""
    data = bytes(pptx_bytes or b"")
    if not data:
        return None

    if st.session_state.get("worksheets"):
        persist_active_worksheet_state()

    worksheets = [
        sheet
        for sheet in list(st.session_state.get("worksheets", []) or [])
        if isinstance(sheet, dict)
    ]
    if not worksheets:
        return None

    preferred_worksheet_id = int(preferred_worksheet_id)
    actual_active_worksheet_id = int(
        st.session_state.get(
            "active_worksheet_id",
            preferred_worksheet_id,
        )
        or preferred_worksheet_id
    )

    # Capture the project once, after all worksheet state has been persisted.
    project_snapshot = _project_snapshot_for_saved_ppt(
        actual_active_worksheet_id
    )

    saved_worksheets = list(
        project_snapshot.get("worksheets", []) or []
    )
    project_pages = list(
        project_snapshot.get("project_pages", []) or []
    )

    # A complete project must contain exactly:
    # Welcome + (Worksheet + Price Details) for every worksheet.
    if (
        len(saved_worksheets) != len(worksheets)
        or len(project_pages) != 1 + (2 * len(worksheets))
    ):
        return None

    worksheet_ids: list[int] = []
    for sheet in saved_worksheets:
        try:
            worksheet_ids.append(int(sheet.get("id")))
        except (TypeError, ValueError):
            return None

    if len(worksheet_ids) != len(set(worksheet_ids)):
        return None

    SAVED_WORKSHEET_PPT_DIR.mkdir(parents=True, exist_ok=True)

    # Never replace an existing complete-project save.  Keep the original
    # project-name filename for the first save, then allocate a numbered
    # filename for every later save of the same project name.  This keeps all
    # existing project data intact and allows the saved-project library to grow
    # well beyond 500 entries without changing the existing selector/restore
    # workflow.
    base_stem = _saved_complete_project_ppt_safe_stem()
    stem = base_stem
    save_index = 1
    while True:
        ppt_path = SAVED_WORKSHEET_PPT_DIR / f"{stem}.pptx"
        state_path = _saved_worksheet_ppt_sidecar_path(ppt_path)
        if not ppt_path.exists() and not state_path.exists():
            break
        save_index += 1
        stem = f"{base_stem}_{save_index:03d}"

    snapshot_payload = {
        "version": 5,
        "kind": "complete_project",
        "worksheet": next(
            (
                sheet
                for sheet in saved_worksheets
                if int(sheet.get("id", -1))
                == actual_active_worksheet_id
            ),
            saved_worksheets[0],
        ),
        "project": project_snapshot,
        "ppt_state": {
            "ppt_session_base_bytes": st.session_state.get(
                "ppt_session_base_bytes"
            ),
            "ppt_session_diagrams": st.session_state.get(
                "ppt_session_diagrams", {}
            ),
            "ppt_session_order": st.session_state.get(
                "ppt_session_order", []
            ),
            "ppt_session_template_signature": st.session_state.get(
                "ppt_session_template_signature"
            ),
        },
    }

    ppt_tmp: Path | None = None
    state_tmp: Path | None = None
    try:
        with tempfile.NamedTemporaryFile(
            mode="wb",
            prefix=f"{stem}_",
            suffix=".tmp.pptx",
            dir=SAVED_WORKSHEET_PPT_DIR,
            delete=False,
        ) as temp_ppt:
            temp_ppt.write(data)
            temp_ppt.flush()
            ppt_tmp = Path(temp_ppt.name)

        with tempfile.NamedTemporaryFile(
            mode="wb",
            prefix=f"{stem}_",
            suffix=".tmp.state",
            dir=SAVED_WORKSHEET_PPT_DIR,
            delete=False,
        ) as temp_state:
            pickle.dump(
                snapshot_payload,
                temp_state,
                protocol=pickle.HIGHEST_PROTOCOL,
            )
            temp_state.flush()
            state_tmp = Path(temp_state.name)

        # Validate the sidecar before replacing the live saved project.
        with state_tmp.open("rb") as verify_state_file:
            verify_payload = pickle.load(verify_state_file)
        verify_project = (
            verify_payload.get("project", {})
            if isinstance(verify_payload, dict)
            else {}
        )
        verify_worksheets = list(
            verify_project.get("worksheets", []) or []
        )
        verify_pages = list(
            verify_project.get("project_pages", []) or []
        )
        if (
            len(verify_worksheets) != len(worksheets)
            or len(verify_pages) != 1 + (2 * len(worksheets))
        ):
            return None

        os.replace(str(ppt_tmp), str(ppt_path))
        ppt_tmp = None
        os.replace(str(state_tmp), str(state_path))
        state_tmp = None
        return ppt_path
    except Exception as exc:
        log_app_error("Save complete project PPT library entry", exc)
        return None
    finally:
        for temp_path in (ppt_tmp, state_tmp):
            if temp_path is None:
                continue
            try:
                temp_path.unlink(missing_ok=True)
            except OSError:
                pass


def _restore_saved_worksheet_ppt(ppt_filename: str) -> tuple[bool, str]:
    """Load one app-saved PPT and restore its worksheet for normal editing."""
    filename = Path(str(ppt_filename or "")).name
    if not filename:
        return False, "No saved PPT was selected."

    ppt_path = SAVED_WORKSHEET_PPT_DIR / filename
    state_path = _saved_worksheet_ppt_sidecar_path(ppt_path)

    # If a stale selector event still points to an older worksheet-only record
    # after a complete-project save was created, always reopen the authoritative
    # complete-project record instead.  The visible selector is also filtered by
    # _saved_worksheet_ppt_files(), so this path mainly protects the rerun in
    # which an old widget value is still present.
    if not _saved_ppt_is_complete_project(ppt_path):
        complete_project_files = [
            candidate
            for candidate in _saved_worksheet_ppt_files()
            if _saved_ppt_is_complete_project(candidate)
        ]
        if complete_project_files:
            ppt_path = complete_project_files[0]
            state_path = _saved_worksheet_ppt_sidecar_path(ppt_path)

    if not ppt_path.is_file() or not state_path.is_file():
        return False, "The selected saved PPT is no longer available."

    try:
        with state_path.open("rb") as state_file:
            payload = pickle.load(state_file)
        ppt_bytes = ppt_path.read_bytes()
    except Exception as exc:
        log_app_error("Load saved worksheet PPT", exc)
        return False, "Could not load the selected saved PPT."

    if not isinstance(payload, dict) or not ppt_bytes:
        return False, "The selected saved PPT is not valid."

    # Version 2 saves contain the complete project/session. Stage the restore and
    # apply it at the start of the next rerun, before any Streamlit widgets are
    # instantiated. This allows the Welcome Page and every worksheet to return
    # together without changing the existing selector/UI workflow.
    project_snapshot = payload.get("project")
    if isinstance(project_snapshot, dict):
        saved_worksheets = project_snapshot.get("worksheets")
        if isinstance(saved_worksheets, list) and saved_worksheets:
            restored_ids: list[int] = []
            valid_project = True
            for sheet in saved_worksheets:
                if not isinstance(sheet, dict):
                    valid_project = False
                    break
                try:
                    worksheet_id = int(sheet.get("id"))
                except (TypeError, ValueError):
                    valid_project = False
                    break
                if worksheet_id in restored_ids:
                    valid_project = False
                    break
                restored_ids.append(worksheet_id)

            if valid_project:
                try:
                    pending_project = copy.deepcopy(project_snapshot)
                except Exception:
                    pending_project = project_snapshot

                try:
                    pending_ppt_state = copy.deepcopy(
                        payload.get("ppt_state", {}) or {}
                    )
                except Exception:
                    pending_ppt_state = payload.get("ppt_state", {}) or {}

                st.session_state["_pending_saved_project_restore"] = {
                    "project": pending_project,
                    "ppt_state": pending_ppt_state,
                    "ppt_bytes": ppt_bytes,
                }

                # Do not apply the project here. This function is called from the
                # saved-PPT selectbox after the Welcome Page name widget has already
                # been instantiated in the current Streamlit run. The caller reruns
                # immediately; ensure_worksheet_state() applies this staged project
                # at the start of that next run, before any widget-owned session-state
                # keys (including welcome_page_display_name) are instantiated.
                return True, f"Loaded {ppt_path.name}"

    worksheet_snapshot = payload.get("worksheet")
    if not isinstance(worksheet_snapshot, dict):
        return False, "The selected PPT does not contain an editable worksheet snapshot."

    try:
        worksheet_snapshot = copy.deepcopy(worksheet_snapshot)
    except Exception:
        worksheet_snapshot = dict(worksheet_snapshot)

    try:
        worksheet_id = int(worksheet_snapshot.get("id"))
    except (TypeError, ValueError):
        return False, "The selected PPT has an invalid worksheet reference."

    # Preserve the current worksheet before explicitly switching to the saved one.
    if st.session_state.get("worksheets"):
        persist_active_worksheet_state()

    worksheets = list(st.session_state.get("worksheets", []) or [])
    replaced = False
    for index, existing_sheet in enumerate(worksheets):
        if int(existing_sheet.get("id", -1)) == worksheet_id:
            worksheets[index] = worksheet_snapshot
            replaced = True
            break
    if not replaced:
        worksheets.append(worksheet_snapshot)

    st.session_state["worksheets"] = worksheets
    st.session_state["next_worksheet_id"] = max(
        [int(sheet.get("id", 0) or 0) for sheet in worksheets] + [0]
    ) + 1

    # Clear only this worksheet's edit-side state, then restore the saved values.
    auxiliary_keys = (
        _worksheet_component_count_adjustments_key(worksheet_id),
        _connection_history_key(worksheet_id),
        _connection_history_index_key(worksheet_id),
        _editor_history_key(worksheet_id),
        _editor_history_index_key(worksheet_id),
        _manual_edit_png_key(worksheet_id),
        _manual_edit_signature_key(worksheet_id),
        _manual_connection_overrides_key(worksheet_id),
        _manual_component_overrides_key(worksheet_id),
        _manual_connection_source_key(worksheet_id),
        _active_connection_transport_key(worksheet_id),
        _worksheet_render_sync_pending_key(worksheet_id),
        f"_ppt_sync_pending_{worksheet_id}",
        f"price_details_adjustment_{worksheet_id}",
        f"price_details_components_{worksheet_id}",
    )
    for state_key in auxiliary_keys:
        st.session_state.pop(state_key, None)

    # Clear only this worksheet's derived render/widget caches so the restored
    # saved state is used immediately instead of any newer in-session widget or
    # geometry cache that happened to share the same worksheet ID.
    st.session_state.pop(
        f"_worksheet_render_bundle_cache_{worksheet_id}",
        None,
    )
    st.session_state[
        f"connection_picker_generation_{worksheet_id}"
    ] = int(
        st.session_state.get(
            f"connection_picker_generation_{worksheet_id}",
            0,
        )
        or 0
    ) + 1
    for state_key in list(st.session_state.keys()):
        if str(state_key).startswith(
            f"required_connection_compact_{worksheet_id}_"
        ) or str(state_key).startswith(
            f"connection_config_target_{worksheet_id}_"
        ):
            st.session_state.pop(state_key, None)

    saved_auxiliary_state = payload.get("auxiliary_state", {})
    if isinstance(saved_auxiliary_state, dict):
        for state_key, state_value in saved_auxiliary_state.items():
            if state_key in auxiliary_keys:
                st.session_state[state_key] = state_value

    saved_ppt_state = payload.get("ppt_state", {})
    if isinstance(saved_ppt_state, dict):
        for state_key in (
            "ppt_session_base_bytes",
            "ppt_session_diagrams",
            "ppt_session_order",
            "ppt_session_template_signature",
        ):
            if state_key in saved_ppt_state:
                st.session_state[state_key] = saved_ppt_state[state_key]

    # The selected library PPT becomes the active PPT bytes, while the existing
    # worksheet/edit machinery remains exactly the same after state restoration.
    st.session_state["ppt_session_pptx_bytes"] = ppt_bytes
    st.session_state["pptx_bytes"] = ppt_bytes
    st.session_state["active_worksheet_id"] = worksheet_id
    st.session_state["worksheet_selector"] = worksheet_id
    st.session_state[_WORKSHEET_PAGE_FLOW_KEY] = _worksheet_page_flow_token(
        "worksheet", worksheet_id
    )

    load_active_worksheet_state()
    _write_current_ppt_session_file(ppt_bytes)
    return True, f"Loaded {ppt_path.name}"


def _saved_ppt_download_data(
    worksheet_id: int,
    pptx_bytes: bytes | bytearray | None,
):
    """Return deferred download data that also records the PPT in the library."""
    worksheet_id = int(worksheet_id)
    data = bytes(pptx_bytes or b"")

    def _serve_saved_ppt() -> bytes:
        if data:
            _save_current_worksheet_ppt_to_library(worksheet_id, data)
        return data

    return _serve_saved_ppt


def _sync_external_ppt_edits_if_any() -> None:
    """Use edits saved from desktop PowerPoint as the current downloadable PPT."""
    if not PPT_SESSION_OUTPUT_PATH.exists():
        return
    try:
        current_mtime = PPT_SESSION_OUTPUT_PATH.stat().st_mtime_ns
    except OSError:
        return
    written_mtime = st.session_state.get("ppt_session_file_mtime_ns")
    if written_mtime is None or current_mtime <= int(written_mtime):
        return
    try:
        edited_bytes = PPT_SESSION_OUTPUT_PATH.read_bytes()
    except OSError:
        return
    if edited_bytes:
        st.session_state["pptx_bytes"] = edited_bytes
        st.session_state["ppt_session_pptx_bytes"] = edited_bytes
        st.session_state["ppt_session_file_mtime_ns"] = current_mtime
        active_worksheet_id = st.session_state.get("active_worksheet_id")
        if active_worksheet_id is not None:
            _save_current_worksheet_ppt_to_library(
                int(active_worksheet_id),
                edited_bytes,
            )


def ensure_ppt_session_state() -> None:
    """Initialize one combined PPT session from the fixed template.

    The original template is opened only when the PPT session is first created,
    explicitly reset, or its persistent placement configuration changes.
    Worksheet switching never creates or reloads a separate PPT.
    """
    signature = ppt_template_signature_for_hashing()
    current_signature = st.session_state.get("ppt_session_template_signature")
    needs_base = not st.session_state.get("ppt_session_base_bytes")
    template_changed = current_signature not in (None, signature)

    if needs_base or template_changed:
        existing_diagrams = dict(st.session_state.get("ppt_session_diagrams", {}) or {})
        existing_order = list(st.session_state.get("ppt_session_order", []) or [])

        base_bytes = initialize_combined_ppt_session(
            template_path=DEFAULT_PPT_TEMPLATE_PATH,
            config_path=PPT_TEMPLATE_CONFIG_PATH,
        )
        st.session_state["ppt_session_base_bytes"] = base_bytes
        st.session_state["ppt_session_template_signature"] = signature
        st.session_state.setdefault("ppt_session_diagrams", existing_diagrams)
        st.session_state.setdefault("ppt_session_order", existing_order)

        # If placement settings changed, preserve all session diagrams and simply
        # reflow them inside the newly configured area.
        diagrams = _ordered_ppt_session_diagrams()
        combined = generate_combined_ppt_from_session(
            session_base_ppt=base_bytes,
            diagrams=diagrams,
            config_path=PPT_TEMPLATE_CONFIG_PATH,
            price_pages=_ppt_price_pages_for_diagrams(diagrams),
        )
        st.session_state["ppt_session_pptx_bytes"] = combined
        st.session_state["pptx_bytes"] = combined
        _write_current_ppt_session_file(combined)
    else:
        if "ppt_session_diagrams" not in st.session_state:
            st.session_state["ppt_session_diagrams"] = {}
        if "ppt_session_order" not in st.session_state:
            st.session_state["ppt_session_order"] = []
        if not st.session_state.get("ppt_session_pptx_bytes"):
            base_bytes = st.session_state["ppt_session_base_bytes"]
            ordered_diagrams = _ordered_ppt_session_diagrams()
            combined = generate_combined_ppt_from_session(
                session_base_ppt=base_bytes,
                diagrams=ordered_diagrams,
                config_path=PPT_TEMPLATE_CONFIG_PATH,
                price_pages=_ppt_price_pages_for_diagrams(
                    ordered_diagrams
                ),
            )
            st.session_state["ppt_session_pptx_bytes"] = combined
            st.session_state["pptx_bytes"] = combined
            _write_current_ppt_session_file(combined)
        elif not st.session_state.get("pptx_bytes"):
            st.session_state["pptx_bytes"] = st.session_state["ppt_session_pptx_bytes"]

    _sync_external_ppt_edits_if_any()


def _rebuild_combined_ppt_session() -> None:
    ensure_ppt_session_state()
    ordered_diagrams = _ordered_ppt_session_diagrams()
    combined = generate_combined_ppt_from_session(
        session_base_ppt=st.session_state["ppt_session_base_bytes"],
        diagrams=ordered_diagrams,
        config_path=PPT_TEMPLATE_CONFIG_PATH,
        price_pages=_ppt_price_pages_for_diagrams(
            ordered_diagrams
        ),
    )
    st.session_state["ppt_session_pptx_bytes"] = combined
    st.session_state["pptx_bytes"] = combined
    _write_current_ppt_session_file(combined)


def _stage_diagram_for_ppt_session(worksheet_id: int, preview_png: bytes) -> None:
    """Record the latest worksheet PNG without rebuilding PowerPoint yet.

    This preserves the exact combined-PPT contents while moving the expensive
    presentation build to the existing PPT Edit/Download paths, where it is
    actually required.
    """
    if not preview_png:
        return

    diagram_id = _ppt_session_diagram_id(worksheet_id)
    diagrams = st.session_state.setdefault("ppt_session_diagrams", {})
    order = st.session_state.setdefault("ppt_session_order", [])
    diagram_hash = hashlib.sha256(preview_png).hexdigest()

    existing = diagrams.get(diagram_id)
    if not (
        isinstance(existing, dict)
        and existing.get("hash") == diagram_hash
    ):
        diagrams[diagram_id] = {
            "worksheet_id": int(worksheet_id),
            "png": preview_png,
            "hash": diagram_hash,
        }

    if diagram_id not in order:
        order.append(diagram_id)

    _mark_ppt_sync_pending(int(worksheet_id))


def add_diagram_to_ppt_session(worksheet_id: int, preview_png: bytes) -> None:
    """Add/update one worksheet image in the single current-session PPT."""
    if not preview_png:
        return

    # If no PPT bytes existed before this request, ensure_ppt_session_state()
    # materializes the staged diagram collection once. Avoid rebuilding it a
    # second time immediately afterward.
    had_materialized_ppt = bool(
        st.session_state.get("ppt_session_pptx_bytes")
    )
    ensure_ppt_session_state()

    diagram_id = _ppt_session_diagram_id(worksheet_id)
    diagram_hash = hashlib.sha256(preview_png).hexdigest()
    diagrams = st.session_state.setdefault("ppt_session_diagrams", {})
    order = st.session_state.setdefault("ppt_session_order", [])

    existing = diagrams.get(diagram_id)
    if isinstance(existing, dict) and existing.get("hash") == diagram_hash:
        # The same image may have been staged by the performance path without
        # rebuilding the actual PPT bytes yet. Rebuild only when that existing
        # pending-sync flag says a PPT operation now requires it.
        if (
            had_materialized_ppt
            and st.session_state.get(f"_ppt_sync_pending_{int(worksheet_id)}")
        ):
            _rebuild_combined_ppt_session()
        return

    diagrams[diagram_id] = {
        "worksheet_id": int(worksheet_id),
        "png": preview_png,
        "hash": diagram_hash,
    }
    if diagram_id not in order:
        order.append(diagram_id)

    _rebuild_combined_ppt_session()


def refresh_ppt_for_current_diagram() -> None:
    """Reflow all diagrams in the same session PPT after placement changes."""
    ensure_ppt_session_state()
    _rebuild_combined_ppt_session()


def _worksheet_render_sync_pending_key(worksheet_id: int) -> str:
    return f"_worksheet_render_sync_pending_{int(worksheet_id)}"


def _mark_worksheet_render_sync_pending(worksheet_id: int) -> None:
    """Mark PNG/PDF export rendering as deferred for a fast +/- action."""
    st.session_state[_worksheet_render_sync_pending_key(worksheet_id)] = True


def _render_current_worksheet_export_png(worksheet_id: int) -> bytes:
    """Render the current Worksheet model only when an export actually needs it."""
    worksheet_id = int(worksheet_id)
    diagram = st.session_state.get("diagram")
    if diagram is None:
        return b""

    return create_preview_png(
        diagram=diagram,
        assets_dir=ASSETS_DIR,
        manual_route_overrides=st.session_state.get(
            _manual_connection_overrides_key(worksheet_id), {}
        ) or {},
        manual_component_overrides=st.session_state.get(
            _manual_component_overrides_key(worksheet_id), {}
        ) or {},
    )


def _sync_pending_worksheet_render_if_needed(worksheet_id: int) -> None:
    """Materialize deferred PNG/PDF only for an explicit operation that needs it."""
    worksheet_id = int(worksheet_id)
    pending_key = _worksheet_render_sync_pending_key(worksheet_id)
    if not st.session_state.get(pending_key):
        return

    preview_png = _render_current_worksheet_export_png(worksheet_id)
    if preview_png:
        st.session_state["preview_png"] = preview_png
        st.session_state["pdf_bytes"] = png_to_pdf(preview_png)
        persist_active_worksheet_state()

    st.session_state.pop(pending_key, None)


def _deferred_current_png_download(worksheet_id: int):
    """Return PNG bytes, generating a deferred current PNG only on download click."""
    worksheet_id = int(worksheet_id)
    pending_key = _worksheet_render_sync_pending_key(worksheet_id)
    if not st.session_state.get(pending_key):
        return st.session_state.get("preview_png", b"")

    def _build_latest_png():
        return _render_current_worksheet_export_png(worksheet_id)

    return _build_latest_png


def _mark_ppt_sync_pending(worksheet_id: int) -> None:
    """Defer expensive PPT rebuilding during direct Worksheet interactions."""
    st.session_state[f"_ppt_sync_pending_{int(worksheet_id)}"] = True


def _sync_pending_ppt_if_needed(worksheet_id: int) -> None:
    """Synchronize a deferred Worksheet visual change only when PPT is requested."""
    pending_key = f"_ppt_sync_pending_{int(worksheet_id)}"
    if not st.session_state.get(pending_key):
        return
    preview_png = st.session_state.get("preview_png")
    if preview_png:
        add_diagram_to_ppt_session(int(worksheet_id), preview_png)
    st.session_state.pop(pending_key, None)


def _deferred_current_ppt_download(worksheet_id: int):
    """Return current PPT bytes, or lazily build the pending PPT on click.

    This is used only when a direct Worksheet component add/delete has deferred
    the expensive combined-PPT rebuild. It keeps ordinary Worksheet actions fast
    while preserving the exact existing PPT output when the user asks for it.
    """
    worksheet_id = int(worksheet_id)
    pending_key = f"_ppt_sync_pending_{worksheet_id}"
    if not st.session_state.get(pending_key):
        return _saved_ppt_download_data(
            worksheet_id,
            st.session_state.get("pptx_bytes", b""),
        )

    render_pending = bool(
        st.session_state.get(_worksheet_render_sync_pending_key(worksheet_id))
    )
    preview_png = (
        None
        if render_pending
        else st.session_state.get("preview_png")
    )
    diagram_id = _ppt_session_diagram_id(worksheet_id)

    # Snapshot the current PPT diagram collection without mutating it.
    session_diagrams = dict(st.session_state.get("ppt_session_diagrams", {}) or {})
    session_order = list(st.session_state.get("ppt_session_order", []) or [])

    if preview_png:
        session_diagrams[diagram_id] = {
            "worksheet_id": worksheet_id,
            "png": preview_png,
            "hash": hashlib.sha256(preview_png).hexdigest(),
        }
        if diagram_id not in session_order:
            session_order.append(diagram_id)

    diagrams_snapshot: list[tuple[str, bytes]] = []
    for item_id in session_order:
        item = session_diagrams.get(item_id)
        if not isinstance(item, dict):
            continue
        png = item.get("png")
        if png:
            diagrams_snapshot.append((str(item_id), bytes(png)))

    session_base = st.session_state.get("ppt_session_base_bytes")

    def _build_latest_ppt():
        base_bytes = session_base
        if not base_bytes:
            base_bytes = initialize_combined_ppt_session(
                template_path=DEFAULT_PPT_TEMPLATE_PATH,
                config_path=PPT_TEMPLATE_CONFIG_PATH,
            )

        latest_diagrams = list(diagrams_snapshot)
        if render_pending:
            latest_png = _render_current_worksheet_export_png(worksheet_id)
            if latest_png:
                latest_diagrams = [
                    (item_id, png)
                    for item_id, png in latest_diagrams
                    if item_id != diagram_id
                ]
                latest_diagrams.append((diagram_id, latest_png))

        latest_ppt = generate_combined_ppt_from_session(
            session_base_ppt=base_bytes,
            diagrams=latest_diagrams,
            config_path=PPT_TEMPLATE_CONFIG_PATH,
            price_pages=_ppt_price_pages_for_diagrams(
                latest_diagrams
            ),
        )
        _save_current_worksheet_ppt_to_library(worksheet_id, latest_ppt)
        return latest_ppt

    return _build_latest_ppt


def ensure_current_ppt_export() -> None:
    """Keep the one session-level PPT available without re-adding old previews."""
    ensure_ppt_session_state()


def start_new_ppt_session() -> None:
    """Save the current project, then open a separate blank PPT workspace."""
    active_worksheet_id = int(st.session_state.get("active_worksheet_id", 1))
    persist_active_worksheet_state()
    _sync_pending_worksheet_render_if_needed(active_worksheet_id)
    _sync_pending_ppt_if_needed(active_worksheet_id)
    ensure_current_ppt_export()
    complete_project_ppt = _materialize_complete_project_ppt_for_save()
    _save_complete_project_ppt_to_library(
        complete_project_ppt
        or st.session_state.get("pptx_bytes")
        or st.session_state.get("ppt_session_pptx_bytes"),
        active_worksheet_id,
    )
    _clear_saved_project_selection(
        active_worksheet_id,
        reset_loaded_state=True,
        force_reset=True,
    )


def open_current_ppt_for_editing() -> tuple[bool, str]:
    """Open the same combined PPT in desktop PowerPoint when running locally."""
    ensure_ppt_session_state()
    data = st.session_state.get("pptx_bytes")
    if not data or not _ordered_ppt_session_diagrams():
        return False, "Generate at least one worksheet diagram first."

    _write_current_ppt_session_file(data)
    active_worksheet_id = st.session_state.get("active_worksheet_id")
    if active_worksheet_id is not None:
        _save_current_worksheet_ppt_to_library(
            int(active_worksheet_id),
            data,
        )
    if os.name == "nt" and hasattr(os, "startfile"):
        try:
            os.startfile(str(PPT_SESSION_OUTPUT_PATH))  # type: ignore[attr-defined]
            return True, "Opened the current combined PPT in Microsoft PowerPoint."
        except OSError as exc:
            log_app_error("Open current PPT in desktop PowerPoint", exc)
            return False, "Could not open PowerPoint automatically. Please try again or download the PPT."

    return False, "Download the current PPT and open it in Microsoft PowerPoint."


def current_ppt_session_has_diagrams() -> bool:
    return bool(_ordered_ppt_session_diagrams())


@st.dialog("PPT Template Placement")
def configure_fixed_ppt_template() -> None:
    """Small modal editor for the fixed template; it does not alter the main UI."""
    try:
        metadata = get_template_metadata(DEFAULT_PPT_TEMPLATE_PATH)
    except Exception as exc:
        log_app_error("PPT template metadata", exc)
        show_friendly_error("loading the PowerPoint template")
        return

    config = load_placement_config(PPT_TEMPLATE_CONFIG_PATH)
    slide_count = int(metadata["slide_count"])
    slide_width = float(metadata["slide_width"])
    slide_height = float(metadata["slide_height"])

    with st.form("fixed_ppt_placement_form"):
        slide_number = st.number_input(
            "Diagram slide",
            min_value=1,
            max_value=max(1, slide_count),
            value=min(max(1, int(config["slide_number"])), max(1, slide_count)),
            step=1,
        )

        x_col, y_col = st.columns(2)
        with x_col:
            x = st.number_input(
                "X position (in)",
                min_value=0.0,
                max_value=max(0.0, slide_width),
                value=min(float(config["x"]), slide_width),
                step=0.05,
                format="%.2f",
            )
        with y_col:
            y = st.number_input(
                "Y position (in)",
                min_value=0.0,
                max_value=max(0.0, slide_height),
                value=min(float(config["y"]), slide_height),
                step=0.05,
                format="%.2f",
            )

        width_col, height_col = st.columns(2)
        with width_col:
            width = st.number_input(
                "Diagram area width (in)",
                min_value=0.10,
                max_value=max(0.10, slide_width),
                value=min(float(config["width"]), slide_width),
                step=0.05,
                format="%.2f",
            )
        with height_col:
            height = st.number_input(
                "Diagram area height (in)",
                min_value=0.10,
                max_value=max(0.10, slide_height),
                value=min(float(config["height"]), slide_height),
                step=0.05,
                format="%.2f",
            )

        maintain_aspect_ratio = st.checkbox(
            "Maintain diagram aspect ratio",
            value=bool(config.get("maintain_aspect_ratio", True)),
        )

        align_col, valign_col = st.columns(2)
        with align_col:
            horizontal_align = st.selectbox(
                "Horizontal fit",
                options=["left", "center", "right"],
                index=["left", "center", "right"].index(
                    str(config.get("horizontal_align", "center"))
                ),
                format_func=lambda value: value.title(),
            )
        with valign_col:
            vertical_align = st.selectbox(
                "Vertical fit",
                options=["top", "middle", "bottom"],
                index=["top", "middle", "bottom"].index(
                    str(config.get("vertical_align", "middle"))
                ),
                format_func=lambda value: value.title(),
            )

        save_clicked = st.form_submit_button(
            "Save PPT placement",
            use_container_width=True,
            type="primary",
        )

    if save_clicked:
        save_placement_config(
            PPT_TEMPLATE_CONFIG_PATH,
            {
                "slide_number": int(slide_number),
                "x": float(x),
                "y": float(y),
                "width": float(width),
                "height": float(height),
                "maintain_aspect_ratio": bool(maintain_aspect_ratio),
                "horizontal_align": horizontal_align,
                "vertical_align": vertical_align,
            },
        )
        refresh_ppt_for_current_diagram()
        st.rerun()


@st.cache_data(max_entries=512, show_spinner=False)
def _asset_digest_for_version(path_text: str, mtime_ns: int, file_size: int) -> str:
    """Hash an asset once per actual file version instead of on every UI rerun."""
    del mtime_ns, file_size  # deliberately part of the cache key
    return hashlib.sha256(Path(path_text).read_bytes()).hexdigest()


def asset_signature_for_hashing(root_dir: Path) -> str:
    """Return the same content-sensitive asset signature with near-zero rerun cost.

    The previous implementation reread and SHA-256 hashed every component image on
    every Streamlit rerun.  The resulting signature is unchanged; only unchanged
    file versions reuse their already-computed digest.
    """
    if not root_dir.exists():
        return ""

    parts: list[str] = []
    for path in sorted(root_dir.rglob('*')):
        if not path.is_file():
            continue
        suffix = path.suffix.lower()
        if suffix not in {'.png', '.jpg', '.jpeg', '.webp', '.bmp'}:
            continue
        try:
            stat = path.stat()
            digest = _asset_digest_for_version(
                str(path.resolve()),
                int(stat.st_mtime_ns),
                int(stat.st_size),
            )
            parts.append(f"{path.relative_to(root_dir)}:{digest}")
        except OSError:
            continue
    return '|'.join(parts)


def render_outputs(diagram, *, defer_exports: bool = False) -> None:
    """Render normally, or defer export-only raster work when explicitly safe."""
    active_sheet = get_active_worksheet()
    worksheet_id = int(active_sheet["id"])
    fast_change_key = f"_fast_worksheet_component_change_{worksheet_id}"
    fast_component_action = bool(st.session_state.pop(fast_change_key, False))

    # A newly generated topology starts with the router's untouched output.
    # Manual line edits belong only to the previous rendered version.
    st.session_state.pop(_manual_connection_overrides_key(worksheet_id), None)
    st.session_state.pop(_connection_history_key(worksheet_id), None)
    st.session_state.pop(_connection_history_index_key(worksheet_id), None)
    st.session_state.pop("editor_saved_state", None)

    existing_preview = st.session_state.get("preview_png")

    # Worksheet component-image visibility fix only.
    # A newly generated diagram must not reuse an earlier lightweight geometry /
    # sprite bundle. Rebuild only this render cache from the current diagram so
    # selected component images are immediately available on the Worksheet.
    st.session_state.pop(
        f"_worksheet_render_bundle_cache_{int(worksheet_id)}",
        None,
    )

    if defer_exports or (fast_component_action and existing_preview is not None):
        # The live Worksheet is drawn from the diagram model by the existing
        # geometry/sprite component, not from preview_png.  For manual component
        # generation, export-quality PNG/PDF/PPT bytes are therefore created only
        # when Download/PPT explicitly asks for them.  This changes no diagram,
        # geometry, routing, arrow, UI or eventual export output.
        st.session_state["diagram"] = diagram
        if "worksheets" in st.session_state:
            persist_active_worksheet_state()
        _mark_worksheet_render_sync_pending(worksheet_id)
        _mark_ppt_sync_pending(worksheet_id)
        return

    try:
        preview_png = create_preview_png(diagram=diagram, assets_dir=ASSETS_DIR)
        pdf_bytes = png_to_pdf(preview_png)
    except Exception as exc:
        log_app_error("Diagram render / PDF conversion", exc)
        raise

    st.session_state["diagram"] = diagram
    st.session_state["preview_png"] = preview_png
    st.session_state["pdf_bytes"] = pdf_bytes
    st.session_state.pop(_worksheet_render_sync_pending_key(worksheet_id), None)
    if "worksheets" in st.session_state:
        persist_active_worksheet_state()

    # Performance only: keep the latest worksheet image ready for the existing
    # combined-PPT workflow, but do not rebuild the PPT during ordinary diagram
    # generation. PPT Edit/Download already synchronize on demand.
    _stage_diagram_for_ppt_session(worksheet_id, preview_png)


# =============================================================================
# GENERATION PIPELINES
# =============================================================================

def generate_professional_diagram(uploaded_bytes: bytes, orientation: str) -> None:
    """Existing sketch → AI topology → professional diagram workflow."""
    model = os.getenv("GEMINI_MODEL", "gemini-3.6-flash")
    validate_required_assets()

    # Performance only: keep the expensive AI stages in this worksheet session.
    # If rendering/export later fails or an unrelated Streamlit rerun occurs, the
    # exact same uploaded sketch does not need to call the models again.
    ai_pipeline_path = ROOT_DIR / "src" / "ai_pipeline.py"
    try:
        ai_pipeline_version = str(ai_pipeline_path.stat().st_mtime_ns)
    except OSError:
        ai_pipeline_version = ""

    ai_cache_key = hashlib.sha256(
        b"sketch-ai|"
        + uploaded_bytes
        + orientation.encode("utf-8")
        + model.encode("utf-8")
        + ai_pipeline_version.encode("utf-8")
    ).hexdigest()
    ai_cache = st.session_state.setdefault("_sketch_ai_stage_cache", {})
    cached_entry = ai_cache.get(ai_cache_key)
    if not isinstance(cached_entry, dict):
        cached_entry = {}
        ai_cache[ai_cache_key] = cached_entry

    # Keep memory bounded while retaining the most recent sketch analyses.
    if len(ai_cache) > 4:
        for stale_key in list(ai_cache.keys())[:-4]:
            ai_cache.pop(stale_key, None)

    with st.status("Processing sketch and generating professional diagram...", expanded=True) as status:
        st.write("1/5  Loading hand-drawn image")
        st.write("2/5  Enhancing handwriting and pipeline geometry with OpenCV")

        extracted = cached_entry.get("extracted")
        reviewed = cached_entry.get("reviewed")

        if extracted is None:
            _, original, enhanced = _cached_sketch_processing(
                uploaded_bytes,
                orientation,
            )
            client = get_gemini_client()

            st.write("3/5  Sketch Understanding Agent extracting components and exact connections")
            extracted = analyze_sketch(
                client=client,
                model=model,
                original_image=original,
                enhanced_image=enhanced,
            )
            cached_entry["extracted"] = extracted
        else:
            st.write("3/5  Sketch Understanding Agent extracting components and exact connections")

        if reviewed is None:
            client = get_gemini_client()
            st.write("4/5  Engineering Review Agent validating topology and layout")
            reviewed = review_diagram(client=client, model=model, diagram=extracted)
            cached_entry["reviewed"] = reviewed
        else:
            st.write("4/5  Engineering Review Agent validating topology and layout")

        # The sketch decides WHICH component instances are connected.  Convert that
        # relationship intent into the exact same instance-level connection IDs used
        # by 2A, then build the final graph through the existing Component Selection
        # builder.  The router/renderers are therefore shared unchanged between
        # uploaded-sketch mode and manual-selection mode.
        final_diagram = build_sketch_using_existing_connection_logic(reviewed)

        st.write("5/5  Rendering premium PNG, editable PowerPoint and PDF")
        render_outputs(final_diagram)
        status.update(label="Diagram created successfully", state="complete", expanded=False)

def _remove_tracked_auto_components(
    components: list[str],
    tracked_components: list[str],
) -> list[str]:
    """Remove only instances previously auto-added by this specific generation rule."""
    if not tracked_components:
        return list(components or [])

    remove_counts = Counter(tracked_components)
    cleaned_reversed: list[str] = []
    for component_name in reversed(list(components or [])):
        if remove_counts.get(component_name, 0) > 0:
            remove_counts[component_name] -= 1
            continue
        cleaned_reversed.append(component_name)
    return list(reversed(cleaned_reversed))


def _option_label_base(value: object) -> str:
    """Return a connection-option component label without its instance suffix."""
    label = " ".join(str(value or "").strip().split())
    return re.sub(r"\s+\d+$", "", label).strip()


def _validate_required_connection_ids(
    expanded_components: list[str],
    candidate_connection_ids: list[str] | tuple[str, ...] | None,
) -> list[str]:
    """Keep only unique connection IDs already allowed by the trained catalog.

    This is a validation-only gate. It never creates a new component pair and
    never infers a relationship from component presence/proximity.
    """
    valid_ids = _allowed_connection_id_set(expanded_components)

    validated: list[str] = []
    seen: set[str] = set()
    for raw_id in list(candidate_connection_ids or []):
        connection_id = str(raw_id or "").strip()
        if (
            connection_id
            and connection_id in valid_ids
            and connection_id not in seen
        ):
            seen.add(connection_id)
            validated.append(connection_id)
    return validated


