def _automatic_requirement_signature(selected_names: list[str]) -> tuple[int, int, int]:
    counts = Counter(
        name
        for name in list(selected_names or [])
        if name in {"Sump", "Bore Well", "OHT Tank"}
    )
    return (
        int(counts.get("Sump", 0)),
        int(counts.get("Bore Well", 0)),
        int(counts.get("OHT Tank", 0)),
    )


def _automatic_requirement_components_compat(selected_names: list[str]) -> list[str]:
    catalog_func = getattr(
        component_catalog_module,
        "automatic_requirement_components",
        None,
    )
    if callable(catalog_func):
        return list(catalog_func(selected_names) or [])

    profile = _LOCAL_AUTOMATIC_REQUIREMENT_PROFILES.get(
        _automatic_requirement_signature(selected_names),
        {},
    )
    return list(profile.get("components", []) or [])


def _automatic_requirement_pairs_compat(
    selected_names: list[str],
) -> tuple[tuple[str, str], ...]:
    catalog_func = getattr(
        component_catalog_module,
        "automatic_requirement_pairs",
        None,
    )
    if callable(catalog_func):
        return tuple(catalog_func(selected_names) or ())

    profile = _LOCAL_AUTOMATIC_REQUIREMENT_PROFILES.get(
        _automatic_requirement_signature(selected_names),
        {},
    )
    return tuple(profile.get("pairs", []) or ())


def _connection_ids_for_required_pairs(
    expanded_components: list[str],
    required_pairs: tuple[tuple[str, str], ...] | list[tuple[str, str]],
) -> list[str]:
    """Resolve approved type-level requirement pairs to current instance IDs.

    The catalog remains authoritative: only options returned by
    allowed_connection_options() can be selected. This helper never fabricates
    a component-to-component relationship.
    """
    required_pair_set = {
        (str(source), str(target))
        for source, target in list(required_pairs or [])
    }
    if not required_pair_set:
        return []

    ids: list[str] = []
    for option in _conservative_allowed_connection_options(expanded_components):
        pair = (
            _option_label_base(getattr(option, "source_label", "")),
            _option_label_base(getattr(option, "target_label", "")),
        )
        if pair in required_pair_set:
            ids.append(str(getattr(option, "id", "") or ""))

    return _validate_required_connection_ids(expanded_components, ids)


def _requested_connection_ids_for_wireless_setup(
    expanded_components: list[str],
) -> list[str]:
    """Select only the newly requested relationships using existing option IDs.

    Two separate LLS instances are intentionally used:
      Master -> LLS 1
      Transmitter -> LLS 2
    No common LLS is shared by those two connections.
    """
    options = list(_conservative_allowed_connection_options(expanded_components) or [])
    by_pair: dict[tuple[str, str], list] = {}
    for option in options:
        source_name = _option_label_base(getattr(option, "source_label", ""))
        target_name = _option_label_base(getattr(option, "target_label", ""))
        by_pair.setdefault((source_name, target_name), []).append(option)

    requested_ids: list[str] = []

    def add_first(source_name: str, target_name: str, *, target_suffix: str | None = None) -> None:
        candidates = list(by_pair.get((source_name, target_name), []) or [])
        if target_suffix is not None:
            candidates = [
                option for option in candidates
                if str(getattr(option, "target_label", "") or "").strip().endswith(target_suffix)
            ]
        if candidates:
            requested_ids.append(str(getattr(candidates[0], "id", "") or ""))

    # Requested additions. Existing Master <-> Repeater <-> Transmitter auto-links
    # are deliberately not selected here; auto_expand_wireless_components keeps
    # controlling those existing relationships exactly as before.
    add_first("Bore Well", "Smart Motor Controller (SMC)")
    add_first("Bore Well", "Sump")
    add_first("Sump", "Master")
    add_first("Master", "Linear Level Sensor (LLS)", target_suffix=" 1")
    add_first("Sump", "OHT Tank")
    add_first("OHT Tank", "Transmitter")
    add_first("Transmitter", "Linear Level Sensor (LLS)", target_suffix=" 2")

    return _validate_required_connection_ids(
        expanded_components,
        requested_ids,
    )


def _component_catalog_cache_version() -> str:
    """Return a tiny source-version key for cached component-diagram generation."""
    version_parts: list[str] = []
    for relative_path in (
        "src/component_catalog.py",
        "src/topology.py",
    ):
        path = ROOT_DIR / relative_path
        try:
            stat = path.stat()
            version_parts.append(
                f"{relative_path}:{int(stat.st_mtime_ns)}:{int(stat.st_size)}"
            )
        except OSError:
            version_parts.append(f"{relative_path}:missing")
    return "|".join(version_parts)


@st.cache_data(max_entries=64, show_spinner=False)
def _cached_build_selected_component_diagram(
    selected_components_key: tuple[str, ...],
    connection_ids_key: tuple[str, ...],
    connection_settings_json: str,
    inline_flow_settings_json: str,
    catalog_version: str,
):
    """Cache deterministic component/topology generation across widget reruns.

    ``catalog_version`` is intentionally part of the cache key so edits to the
    existing component/topology source invalidate old cached diagrams.
    """
    del catalog_version  # used only as part of the Streamlit cache key

    connection_settings = (
        json.loads(connection_settings_json)
        if connection_settings_json
        else {}
    )
    inline_flow_settings = (
        json.loads(inline_flow_settings_json)
        if inline_flow_settings_json
        else {}
    )

    return _call_component_catalog_function(
        "build_selected_component_diagram",
        list(selected_components_key),
        required_connection_ids=list(connection_ids_key),
        connection_settings=connection_settings,
        inline_placement_settings=inline_flow_settings,
        expand_repeated_instances=True,
    )


def generate_selected_components(
    selected_components: list[str],
    selected_connection_ids: list[str],
    connection_transport_settings: dict[str, dict],
    inline_flow_meter_settings: dict[str, dict],
) -> None:
    """Build the selected diagram, auto-expanding wireless communication components."""
    worksheet_id = int(get_active_worksheet()["id"])
    deleted_connection_ids = {
        str(value)
        for value in st.session_state.get(
            _deleted_connection_ids_key(worksheet_id), []
        )
        or []
    }
    auto_component_key = f"_auto_wireless_components_{worksheet_id}"
    requested_auto_component_key = f"_auto_requested_connection_components_{worksheet_id}"
    trained_requirement_component_key = (
        f"_auto_trained_requirement_components_{worksheet_id}"
    )

    # Remove only communication components that this function auto-added during
    # the previous valid Distance + Interference generation. Manually selected
    # Master / Transmitter / Repeater instances are left untouched.
    base_components = list(selected_components or [])
    previous_auto_components = list(
        st.session_state.get(auto_component_key, []) or []
    )
    base_components = _remove_tracked_auto_components(
        base_components,
        previous_auto_components,
    )

    # Remove only SMC/LLS instances previously added by this requested connection
    # rule. Any manually selected SMC/LLS instances remain untouched.
    previous_requested_auto_components = list(
        st.session_state.get(requested_auto_component_key, []) or []
    )
    base_components = _remove_tracked_auto_components(
        base_components,
        previous_requested_auto_components,
    )

    # Remove only components previously added by the exact project-trained
    # automatic requirement profile. The user's base components remain untouched.
    previous_trained_requirement_components = list(
        st.session_state.get(trained_requirement_component_key, []) or []
    )
    base_components = _remove_tracked_auto_components(
        base_components,
        previous_trained_requirement_components,
    )

    # Restore the existing project-trained automatic requirement resolver.
    # It selects only exact approved profiles and never invents a relationship.
    trained_requirement_components = _automatic_requirement_components_compat(
        base_components
    )
    trained_requirement_pairs = _automatic_requirement_pairs_compat(base_components)

    # Master / Transmitter / Repeater remain governed by the existing strict
    # Distance + Interference logic below. Do not pre-add those communication
    # components from a trained profile.
    trained_requirement_components = [
        name
        for name in trained_requirement_components
        if name not in {"Master", "Transmitter", "Repeater"}
    ]

    for component_name in trained_requirement_components:
        base_components.append(component_name)

    st.session_state[trained_requirement_component_key] = list(
        trained_requirement_components
    )

    # Ignore stale transport rows that belong only to communication components
    # auto-generated in a previous run. The user's currently valid base
    # connection settings remain exactly as selected in 2A.
    valid_base_connection_ids = set(_allowed_connection_id_set(base_components))
    base_selected_connection_ids = [
        connection_id
        for connection_id in list(selected_connection_ids or [])
        if connection_id in valid_base_connection_ids
    ]
    base_transport_settings = {
        connection_id: _sanitize_connection_transport_setting(config)
        for connection_id, config in dict(
            connection_transport_settings or {}
        ).items()
        if connection_id in valid_base_connection_ids
    }

    # Wireless communication components are driven ONLY by an explicit user
    # Wireless selection. Automatic/Wired rows, distance values, interference,
    # normal component selection and automatic routing must never create Master /
    # Transmitter / Repeater components.
    explicit_wireless_selected = any(
        normalize_connection_mode(config.get("mode", "automatic")) == "wireless"
        for config in base_transport_settings.values()
    )
    communication_generation_allowed = bool(explicit_wireless_selected)

    # Defensive stale-state cleanup: communication devices are application-added
    # infrastructure and must not survive after the last explicit Wireless option
    # has been cleared. This also cleans worksheets saved by older builds where
    # those auto-added names were not tracked in ``previous_auto_components``.
    wireless_component_names = {"Master", "Transmitter", "Repeater"}
    if not explicit_wireless_selected:
        base_components = [
            name for name in base_components
            if name not in wireless_component_names
        ]

    if explicit_wireless_selected:
        # Pass the user's settings through unchanged. ``auto_expand_wireless_components``
        # already activates only from explicit Wireless mode; Automatic rows are
        # intentionally not promoted from distance/interference heuristics.
        (
            expanded_components,
            auto_connection_ids,
            expanded_transport_settings,
            wireless_active,
        ) = auto_expand_wireless_components(
            base_components,
            connection_settings=base_transport_settings,
        )
    else:
        expanded_components = list(base_components)
        auto_connection_ids = []
        expanded_transport_settings = dict(base_transport_settings)
        wireless_active = False

    # Track only components newly added by automatic communication expansion so
    # they can be cleanly removed if Distance or Interference is later cleared.
    base_counts = Counter(base_components)
    expanded_counts = Counter(expanded_components)
    newly_auto_added_components: list[str] = []
    for component_name in ("Master", "Transmitter", "Repeater"):
        added_count = max(
            0,
            int(expanded_counts.get(component_name, 0))
            - int(base_counts.get(component_name, 0)),
        )
        newly_auto_added_components.extend([component_name] * added_count)
    st.session_state[auto_component_key] = newly_auto_added_components

    # Add only the components required by the requested connection example when
    # the existing strict Distance + Interference communication condition succeeds
    # and Bore Well + Sump + OHT Tank are all present.
    requested_auto_components: list[str] = []
    requested_connection_ids: list[str] = []
    required_base_set = {"Bore Well", "Sump", "OHT Tank"}
    if (
        communication_generation_allowed
        and required_base_set.issubset(set(base_components))
    ):
        # One SMC is required for the existing Bore Well -> SMC relationship.
        if "Smart Motor Controller (SMC)" not in expanded_components:
            expanded_components.append("Smart Motor Controller (SMC)")
            requested_auto_components.append("Smart Motor Controller (SMC)")

        # Two independent sensors are required. Never share one LLS between
        # Master and Transmitter.
        current_lls_count = expanded_components.count("Linear Level Sensor (LLS)")
        required_lls_count = 2
        for _ in range(max(0, required_lls_count - current_lls_count)):
            expanded_components.append("Linear Level Sensor (LLS)")
            requested_auto_components.append("Linear Level Sensor (LLS)")

        requested_connection_ids = _requested_connection_ids_for_wireless_setup(
            expanded_components
        )

    st.session_state[requested_auto_component_key] = requested_auto_components

    # Apply only explicit hover-icon +/- changes after all existing automatic
    # requirement / wireless component rules have produced their normal result.
    # This does not replace or alter any trained component relationship rule.
    expanded_components, component_count_adjustments = (
        _apply_worksheet_component_count_adjustments(
            worksheet_id,
            expanded_components,
        )
    )

    trained_requirement_connection_ids = _connection_ids_for_required_pairs(
        expanded_components,
        trained_requirement_pairs,
    )

    # Restore the previously existing automatic connection-line generation.
    # Keep every explicitly selected connection and every existing automatic
    # wireless/unit relationship, then add only the trained water/process/tank
    # relationships when the current Type/Distance/Interference setup activates
    # the same automatic behavior used previously. No new relationship rule is
    # introduced here; all IDs still come from allowed_connection_options().
    automatic_water_labels = {
        "water flow",
        "process flow",
        "tank inter-connection",
    }

    distance_explicitly_mentioned = any(
        float(config.get("distance_km", 0.0) or 0.0) > 0.0
        for config in base_transport_settings.values()
    )

    should_auto_generate_water = bool(
        wireless_active or distance_explicitly_mentioned
    )

    auto_water_connection_ids = (
        [
            option.id
            for option in _conservative_allowed_connection_options(expanded_components)
            if str(
                getattr(option, "connection_label", "") or ""
            ).strip().lower()
            in automatic_water_labels
        ]
        if should_auto_generate_water
        else []
    )

    merged_connection_ids = _validate_required_connection_ids(
        expanded_components,
        list(base_selected_connection_ids)
        + list(auto_connection_ids or [])
        + list(requested_connection_ids or [])
        + list(trained_requirement_connection_ids or [])
        + list(auto_water_connection_ids or []),
    )
    merged_connection_ids = [
        connection_id
        for connection_id in merged_connection_ids
        if str(connection_id) not in deleted_connection_ids
        and f"edge__{connection_id}" not in deleted_connection_ids
    ]

    # Persist communication expansion only when the strict condition succeeds.
    # Also persist cleanup when a previously auto-generated chain is no longer
    # eligible, so no stale Master / Transmitter / Repeater / SMC / LLS remains.
    if (
        wireless_active
        or previous_auto_components
        or requested_auto_components
        or previous_requested_auto_components
        or trained_requirement_components
        or previous_trained_requirement_components
        or bool(component_count_adjustments)
    ):
        st.session_state["selected_components"] = list(expanded_components)
        st.session_state["selected_connections"] = merged_connection_ids
        st.session_state["connection_transport_settings"] = dict(
            expanded_transport_settings
        )
        if (
            (previous_auto_components and not wireless_active)
            or (
                previous_requested_auto_components
                and not requested_auto_components
            )
            or (
                previous_trained_requirement_components
                != trained_requirement_components
            )
        ):
            generation_key = f"component_compact_generation_{worksheet_id}"
            st.session_state[generation_key] = int(
                st.session_state.get(generation_key, 0) or 0
            ) + 1
            connection_generation_key = (
                f"connection_picker_generation_{worksheet_id}"
            )
            st.session_state[connection_generation_key] = int(
                st.session_state.get(connection_generation_key, 0) or 0
            ) + 1
        persist_active_worksheet_state()

    merged_connection_ids = _validate_required_connection_ids(
        expanded_components,
        merged_connection_ids,
    )
    merged_connection_ids = [
        connection_id
        for connection_id in merged_connection_ids
        if str(connection_id) not in deleted_connection_ids
        and f"edge__{connection_id}" not in deleted_connection_ids
    ]

    diagram = _cached_build_selected_component_diagram(
        tuple(str(name) for name in expanded_components),
        tuple(str(connection_id) for connection_id in merged_connection_ids),
        json.dumps(
            expanded_transport_settings,
            sort_keys=True,
            separators=(",", ":"),
            default=str,
        ),
        json.dumps(
            inline_flow_meter_settings or {},
            sort_keys=True,
            separators=(",", ":"),
            default=str,
        ),
        _component_catalog_cache_version(),
    )
    render_outputs(diagram, defer_exports=True)


