def render_fixed_ppt_section(active_worksheet_id: int, *, show_title: bool = True) -> None:
    """Compact fixed-template workflow for the one combined session PPT."""
    if show_title:
        st.markdown('<div class="panel-title">2. Edit in PPT</div>', unsafe_allow_html=True)
    with st.container(border=True):
        st.markdown("**Fixed PPT Template**")

        if DEFAULT_PPT_TEMPLATE_PATH.exists():
            ensure_ppt_session_state()
            has_diagrams = current_ppt_session_has_diagrams()

            if has_diagrams:
                st.success("Generated diagram is ready", icon="✅")
            else:
                st.caption("Generated diagram will appear here after generation.")

            if os.name == "nt" and hasattr(os, "startfile"):
                if st.button(
                    "Edit in PPT",
                    key="edit_combined_ppt",
                    use_container_width=True,
                    disabled=not has_diagrams,
                ):
                    opened, message = open_current_ppt_for_editing()
                    if opened:
                        st.toast(message, icon="✅")
                    else:
                        st.warning(message)
            else:
                if has_diagrams and st.session_state.get("pptx_bytes"):
                    st.download_button(
                        "Edit in PPT",
                        _saved_ppt_download_data(
                            active_worksheet_id,
                            st.session_state["pptx_bytes"],
                        ),
                        "final_diagram.pptx",
                        "application/vnd.openxmlformats-officedocument.presentationml.presentation",
                        use_container_width=True,
                        key="edit_combined_ppt_download",
                    )
                else:
                    st.button(
                        "Edit in PPT",
                        disabled=True,
                        use_container_width=True,
                        key="edit_combined_ppt_disabled",
                    )

            _sync_external_ppt_edits_if_any()
            if has_diagrams and st.session_state.get("pptx_bytes"):
                st.download_button(
                    "Download PPT",
                    _saved_ppt_download_data(
                        active_worksheet_id,
                        st.session_state["pptx_bytes"],
                    ),
                    "final_diagram.pptx",
                    "application/vnd.openxmlformats-officedocument.presentationml.presentation",
                    use_container_width=True,
                    key="section_download_combined_ppt",
                )
            else:
                st.button(
                    "Download PPT",
                    disabled=True,
                    use_container_width=True,
                    key="section_download_combined_ppt_disabled",
                )
        else:
            st.error("Fixed PPT template is missing.")


