def _render_automatic_requirement_output_panel(worksheet_id: int) -> None:
    """Render only the new read-only requirement summary in the existing UI style.

    This helper intentionally does not alter selections, connection settings,
    generated components, routing, worksheets, editor state, or PPT data. It only
    reflects the state already produced by the current application.
    """
    diagram = st.session_state.get("diagram")
    selected_names = list(st.session_state.get("selected_components", []) or [])

    base_component_names = {"Sump", "Bore Well", "OHT Tank"}
    auto_names: list[str] = []
    tank_interconnection_present = False

    if diagram is not None:
        seen: set[str] = set()
        for node in list(getattr(diagram, "nodes", []) or []):
            component_name = _component_name_from_diagram_node(node)
            if (
                component_name
                and component_name not in base_component_names
                and component_name not in seen
            ):
                seen.add(component_name)
                auto_names.append(component_name)

        for edge in list(getattr(diagram, "edges", []) or []):
            edge_label = str(getattr(edge, "label", "") or "").strip().lower()
            connection_label = str(
                getattr(edge, "connection_label", "") or ""
            ).strip().lower()
            if "tank inter-connection" in {edge_label, connection_label}:
                tank_interconnection_present = True
                break

    # The current strict Distance + Interference implementation already tracks
    # communication components it generated. Include those in the read-only list
    # even during the rerun in which the worksheet is being refreshed.
    for component_name in list(
        st.session_state.get(f"_auto_wireless_components_{int(worksheet_id)}", [])
        or []
    ):
        if component_name not in auto_names:
            auto_names.append(component_name)

    # If the diagram has not rendered yet, keep the panel neutral rather than
    # inventing a requirement or changing any generation decision.
    auto_added_text = ", ".join(auto_names) if auto_names else "Waiting for generated requirement"
    interconnection_text = "Based on customer requirement"
    tank_status_text = (
        "Enabled for selected OHT Tanks"
        if tank_interconnection_present
        else "Not required by current generated setup"
    )

    # Escape only UI text before inserting it into the HTML card.
    def _esc(value: object) -> str:
        return (
            str(value)
            .replace("&", "&amp;")
            .replace("<", "&lt;")
            .replace(">", "&gt;")
            .replace('"', "&quot;")
        )

    st.markdown(
        '<div class="panel-title compact-left-section-title" '
        'style="margin-top:8px !important;">3. Automatic Requirement Output</div>',
        unsafe_allow_html=True,
    )

    st.markdown(
        f"""
        <div style="
            width:90%;
            max-width:90%;
            margin:8px auto 0 0;
            padding:9px 11px 10px 11px;
            box-sizing:border-box;
            background:#ffffff;
            border:1px solid #d8e6f7;
            border-radius:10px;
            color:#173f75;
            font-family:Inter,'Segoe UI',Arial,sans-serif;
            box-shadow:none;
        ">
            <div style="
                display:grid;
                grid-template-columns:46% 54%;
                align-items:start;
                padding:6px 2px;
                border-bottom:1px solid #e8eff8;
                font-size:12px;
                line-height:1.35;
            ">
                <div style="color:#334f73;font-weight:600;">Detected Customer Requirement:</div>
                <div style="color:#0b4f94;font-weight:700;">Auto Applied</div>
            </div>
            <div style="
                display:grid;
                grid-template-columns:46% 54%;
                align-items:start;
                padding:7px 2px;
                border-bottom:1px solid #e8eff8;
                font-size:12px;
                line-height:1.38;
            ">
                <div style="color:#334f73;font-weight:600;">Auto Added Components:</div>
                <div style="color:#0b4f94;font-weight:650;">{_esc(auto_added_text)}</div>
            </div>
            <div style="
                display:grid;
                grid-template-columns:46% 54%;
                align-items:start;
                padding:7px 2px;
                border-bottom:1px solid #e8eff8;
                font-size:12px;
                line-height:1.35;
            ">
                <div style="color:#334f73;font-weight:600;">OHT Interconnection:</div>
                <div style="color:#0b4f94;font-weight:650;">{_esc(interconnection_text)}</div>
            </div>
            <div style="
                display:grid;
                grid-template-columns:46% 54%;
                align-items:start;
                padding:7px 2px;
                border-bottom:1px solid #e8eff8;
                font-size:12px;
                line-height:1.35;
            ">
                <div style="color:#334f73;font-weight:600;">Tank Interconnection Status:</div>
                <div style="color:#0b4f94;font-weight:650;">{_esc(tank_status_text)}</div>
            </div>
            <div style="
                display:grid;
                grid-template-columns:46% 54%;
                align-items:start;
                padding:7px 2px 8px 2px;
                font-size:12px;
                line-height:1.35;
            ">
                <div style="color:#334f73;font-weight:600;">Connection Logic:</div>
                <div style="color:#0b4f94;font-weight:700;">Auto Generated</div>
            </div>
            <div style="
                margin-top:7px;
                padding:8px 9px;
                display:flex;
                gap:8px;
                align-items:flex-start;
                background:#eef6ff;
                border:1px solid #b9d8ff;
                border-radius:8px;
                color:#164f96;
                font-size:11px;
                line-height:1.4;
            ">
                <div style="
                    flex:0 0 18px;
                    width:18px;
                    height:18px;
                    border-radius:50%;
                    background:#0a66e3;
                    color:#ffffff;
                    display:flex;
                    align-items:center;
                    justify-content:center;
                    font-size:11px;
                    font-weight:800;
                    margin-top:1px;
                ">i</div>
                <div>
                    Only Sump, Bore Well, and OHT Tank are manually selected.<br>
                    All other required components are generated automatically.
                </div>
            </div>
        </div>
        """,
        unsafe_allow_html=True,
    )




